            $worksheet->setCellValue('AG20', $dataForm['formType']);

            $dataForm['applicationRemark'] = Str::squish($dataForm['applicationRemark']);
            $arrAppRemark = preg_split('/\r\n|\r|\n/', $dataForm['applicationRemark']);
            if(count($arrAppRemark) == 3) {
                $worksheet->setCellValue('U23', $arrAppRemark[0]);
                $worksheet->setCellValue('U24', $arrAppRemark[1]);
                $worksheet->setCellValue('U25', $arrAppRemark[2]);
