                        }
                    }
                    else {
                        $unitPriceValue = $this->formatNumber($rowItemVendor['unitPriceValue']);
                    }

                    if(($rowItem['applianceItem'] == 'Discount' || $rowItem['applianceItem'] == 'PPh') && $rowItemVendor['totalPrice'] > 0) {
                        $totalPrice = '('.$this->formatNumber($rowItemVendor['totalPrice']).')';
                    }
                    else {
                        $totalPrice = $this->formatNumber($rowItemVendor['totalPrice']);
                    }

                    if($vendor == 1) {
                        $worksheet->setCellValue('H'.$row, ($unitPriceValue == '' || $unitPriceValue == '0' || $rowItem['applianceItem'] == 'VAT' || $rowItem['applianceItem'] == 'PPh') ? '' : $rowItem['currency']);
                        $worksheet->setCellValue('I'.$row, $unitPriceValue);
                        $worksheet->setCellValue('J'.$row, ($totalPrice == '' || $totalPrice == '0') ? '' : $rowItem['currency']);
                        $worksheet->setCellValue('K'.$row, $totalPrice);

                        if($rowItemVendor['comparisonVendorId'] == $dataForm['selectedVendorComparison']) {
                            $selectedCol = ['J','K'];
                        }
                    }
                    else if($vendor == 2) {
                        $worksheet->setCellValue('L'.$row, ($unitPriceValue == '' || $unitPriceValue == '0' || $rowItem['applianceItem'] == 'VAT') ? '' : $rowItem['currency']);
                        $worksheet->setCellValue('M'.$row, $unitPriceValue);
                        $worksheet->setCellValue('N'.$row, ($totalPrice == '' || $totalPrice == '0') ? '' : $rowItem['currency']);
                        $worksheet->setCellValue('O'.$row, $totalPrice);

                        if($rowItemVendor['comparisonVendorId'] == $dataForm['selectedVendorComparison']) {
                            $selectedCol = ['N','O'];
                        }
                    }
                    else if($vendor == 3) {
                        $worksheet->setCellValue('P'.$row, ($unitPriceValue == '' || $unitPriceValue == '0' || $rowItem['applianceItem'] == 'VAT') ? '' : $rowItem['currency']);
                        $worksheet->setCellValue('Q'.$row, $unitPriceValue);
                        $worksheet->setCellValue('R'.$row, ($totalPrice == '' || $totalPrice == '0') ? '' : $rowItem['currency']);
                        $worksheet->setCellValue('S'.$row, $totalPrice);

                        if($rowItemVendor['comparisonVendorId'] == $dataForm['selectedVendorComparison']) {
                            $selectedCol = ['R','S'];
                        }
                    }

                    $vendor++;
                }

                $no++;
                $row++;
            }

            $worksheet->getStyle('J'.($row - 1))->getFont()->setBold(true);
            $worksheet->getStyle('K'.($row - 1))->getFont()->setBold(true);
            $worksheet->getStyle('N'.($row - 1))->getFont()->setBold(true);
            $worksheet->getStyle('O'.($row - 1))->getFont()->setBold(true);
            $worksheet->getStyle('R'.($row - 1))->getFont()->setBold(true);
            $worksheet->getStyle('S'.($row - 1))->getFont()->setBold(true);
            if(count($selectedCol) > 0) {
                foreach ($selectedCol as $selectedCell) {
                    $worksheet->getStyle($selectedCell.($row - 1))->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('FFA4FFA4');
                }
            }

            $countHeight += $worksheet->getRowDimension($row)->getRowHeight();

            $selectedSectionStart = $baseRowEnd + 2;
            $selectedSectionEnd = $selectedSectionStart + 2;

            if($pageBreak == false && $countHeight > 722.5) {
                $worksheet->setBreak('A'.($selectedSectionStart - 1), Worksheet::BREAK_ROW);
                $pageBreak = true;
            }

            $row = $selectedSectionStart;
            $worksheet->setCellValue('E'.$row, $dataForm['selectedVendorName']);
            $comparisonNote = preg_split('/\r\n|\r|\n/', $dataForm['comparisonNote']);
            if(count($comparisonNote) == 2) {
                $worksheet->setCellValue('E'.($row + 1), $comparisonNote[0]);
                $worksheet->setCellValue('E'.($row + 2), $comparisonNote[1]);
            }
            else {
                $worksheet->setCellValue('E'.($row + 1), $comparisonNote[0]);
            }

            $pdfWriter = new Mpdf($spreadsheet);
            $pdfWriter->setFont('arial');
            $pdfWriter->save($tempPdfFile);

            $pdf = new Fpdi();
            $pdf->SetAutoPageBreak(false);
            $pdfSource = $pdf->setSourceFile($tempPdfFile);
            for ($i = 1; $i <= $pdfSource; $i++) {
                $template = $pdf->importPage($i);
                $size = $pdf->getTemplateSize($template);
                $pdf->AddPage('L');
                $pdf->useTemplate($template, 0, 0, $size['width'], $size['height'], true);

                $pdf->SetFont('arial', '', 8);
                $pdf->SetY(-12);
                $pdf->Cell(0, 10, "Page {$i} of {$pdfSource}", 0, 0, 'R');
            }
            $pdf->Output($tempPdfFile, 'F');

            return true;
        }
    }

    public function viewToPdf(Request $request) {
        // dd($request->all());
        $model = new DocumentApprovalModel();
        $documentType = $request->documentType;
        $forceBorders = function (Worksheet $sheet, string $range, array $sides = ['all']) {
            $borderStyle = \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN;
            $color = ['argb' => '000000'];
            $borderTypes = [];
            foreach ($sides as $side) {
                switch (strtolower($side)) {
                    case 'top':
                        $borderTypes['top'] = ['borderStyle' => $borderStyle, 'color' => $color];
                        break;
                    case 'bottom':
                        $borderTypes['bottom'] = ['borderStyle' => $borderStyle, 'color' => $color];
                        break;
                    case 'left':
                        $borderTypes['left'] = ['borderStyle' => $borderStyle, 'color' => $color];
                        break;
                    case 'right':
                        $borderTypes['right'] = ['borderStyle' => $borderStyle, 'color' => $color];
                        break;
                    case 'all':
                    case 'allborders':
                        $borderTypes['allBorders'] = ['borderStyle' => $borderStyle, 'color' => $color];
                        break;
                }
            }

            // Apply ke worksheet
            $sheet->getStyle($range)->applyFromArray([
                'borders' => $borderTypes
            ]);
        };

        if($documentType == '1') { // ORDER FORM
            $dataForm = $request->dataForm['dataForm'];
            if($dataForm['signer'][2]['flowAs'] == 'APPROVER') {
                $templatePath = 'private/template/F.PUR-02.01_ORDER_FORM_3_SIGN_NOT_LIMIT.xls';
            }
            else {
                $templatePath = 'private/template/F.PUR-02.01_ORDER_FORM_4_SIGN_NOT_LIMIT.xls';
            }
            $filePath = 'private/doc_approval'.$dataForm['filePath'];

            if (!Storage::exists($filePath)) {
                Storage::makeDirectory($filePath);
            }

            Storage::copy($templatePath, $filePath.$dataForm['filename'].'.xlsx');

            $tempXlsxFile = Storage::path($filePath.$dataForm['filename'].'.xlsx');
            $tempPdfFile = Storage::path($filePath.$dataForm['filename'].'.pdf');

            $spreadsheet = IOFactory::load($tempXlsxFile);
            $spreadsheet->getDefaultStyle()->getFont()->setName('arial');
            $spreadsheet->getDefaultStyle()->getAlignment()->setWrapText(true);

            $worksheet = $spreadsheet->getActiveSheet();
            $worksheet->getPageSetup()
                        ->setOrientation(PageSetup::ORIENTATION_PORTRAIT)
                        ->setPaperSize(PageSetup::PAPERSIZE_A4);

            $worksheet->getPageMargins()
                        ->setTop(0.2)
                        ->setLeft(0.2)
                        ->setRight(0.2)
                        ->setBottom(0.2);

            $worksheet->getPageSetup()->setFitToPage(true)
                                    ->setFitToWidth(1)
                                    ->setFitToHeight(0);

            $worksheet->setCellValue('E5', ': '.$dataForm['docNumber']);
            $worksheet->setCellValue('E6', ': '.$dataForm['requestDate']);
            $worksheet->setCellValue('Y5', ': '.$dataForm['departmentName']);
            $worksheet->setCellValue('Y6', ': '.$dataForm['locationName']);
            $worksheet->setCellValue('AA9', $dataForm['currency']);
            $worksheet->setCellValue('AF9', $dataForm['currency']);

            $worksheet->getStyle('A8:AL9')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('ffb8cce4');

            // Dynamic row management for items > 20
            $itemCount = count($dataForm['itemForm']);
            $baseRowStart = 10; // Starting row for items
            $baseRowEnd = 29;   // Default ending row (A10 to A29 = 20 rows)
            $templateRowCount = 20; // Default template rows

            if($itemCount > $templateRowCount) {
                $additionalRows = $itemCount - $templateRowCount;

                // Get the last row with content to determine where to insert
                $insertAfterRow = $baseRowEnd;

                // Copy style and merge information from template row (using row 10 as template)
                $templateRow = $baseRowStart;

                for($x = 1; $x <= $additionalRows; $x++) {
                    $newRow = $insertAfterRow + $x;

                    // Insert new row
                    $worksheet->insertNewRowBefore($newRow, 1);

                    // Copy row height
                    // $templateHeight = $worksheet->getRowDimension($templateRow)->getRowHeight();
                    $worksheet->getRowDimension($newRow)->setRowHeight(13.80);

                    $lastColumn = 'AL';
                    $columnRange = range('A', 'Z');
                    // Add AA to AL manually
                    $columnRange = array_merge($columnRange, ['AA', 'AB', 'AC', 'AD', 'AE', 'AF', 'AG', 'AH', 'AI', 'AJ', 'AK', 'AL']);

                    // Copy styles and formats for each cell in the row
                    foreach($columnRange as $col) {
                        $templateCell = $col . $templateRow;
                        $newCell = $col . $newRow;

                        // Copy cell style
                        $templateStyle = $worksheet->getStyle($templateCell);
                        $worksheet->duplicateStyle($templateStyle, $newCell);

                        // Copy cell value if it's a formula or default value
                        $templateCellValue = $worksheet->getCell($templateCell)->getValue();
                        if(!empty($templateCellValue) && is_string($templateCellValue) && strpos($templateCellValue, '=') === 0) {
                            // If it's a formula, copy it
                            $worksheet->setCellValue($newCell, $templateCellValue);
                        }
                    }

                    // Handle merged cells - copy merge information from template row
                    $mergedCells = $worksheet->getMergeCells();
                    foreach($mergedCells as $mergeRange) {
                        // Check if merge range includes our template row
                        if(preg_match('/([A-Z]+)(\d+):([A-Z]+)(\d+)/', $mergeRange, $matches)) {
                            $startCol = $matches[1];
                            $startRow = (int)$matches[2];
                            $endCol = $matches[3];
                            $endRow = (int)$matches[4];

                            // If the merge range includes our template row
                            if($startRow <= $templateRow && $endRow >= $templateRow) {
                                // Calculate the new merge range for the new row
                                $rowOffset = $newRow - $templateRow;
                                $newStartRow = $startRow + $rowOffset;
                                $newEndRow = $endRow + $rowOffset;

                                $newMergeRange = $startCol . $newStartRow . ':' . $endCol . $newEndRow;

                                // Only merge if it doesn't conflict with existing merges
                                try {
                                    $worksheet->mergeCells($newMergeRange);
                                } catch (Exception $e) {
                                    // If merge fails, continue with next merge
                                    continue;
                                }
                            }
                        }
                    }
                }
            }

            $row = $baseRowStart;
            $no = 1;
            foreach($dataForm['itemForm'] as $rowItem) {
                $worksheet->setCellValue('A'.$row, $no);
                $worksheet->setCellValue('B'.$row, $rowItem['costCenter'] ?? ' ');
                $worksheet->setCellValue('E'.$row, $rowItem['applianceItem'] ?? ' ');
                $worksheet->setCellValue('M'.$row, $rowItem['brandType'] ?? ' ');
                $worksheet->setCellValue('U'.$row, $rowItem['unitQuantity'] ?? ' ');
                $worksheet->setCellValue('X'.$row, $rowItem['unitName'] ?? ' ');

                // Handle price formatting
                $unitPrice = ($rowItem['unitPriceEst'] == '0' || $rowItem['unitPriceEst'] == '-' || empty($rowItem['unitPriceEst']))
                            ? '-'
                            : $this->formatNumber($rowItem['unitPriceEst']);
                $worksheet->setCellValue('AA'.$row, $unitPrice);

                $totalPrice = ($rowItem['totalPriceEst'] == '0' || $rowItem['totalPriceEst'] == '-' || empty($rowItem['totalPriceEst']))
                            ? '-'
                            : $this->formatNumber($rowItem['totalPriceEst']);
                $worksheet->setCellValue('AG'.$row, $totalPrice);

                $worksheet->setCellValue('AL'.$row, $rowItem['requiredDate'] ?? ' ');

                $row++;
                $no++;
            }

            if($itemCount > $templateRowCount) {
                $worksheet->getStyle('A'.$row.':U'.$row)->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('ffb8cce4');
                $worksheet->setCellValue('AF'.$row, '('.$dataForm['currency'].')');
                $worksheet->setCellValue('AG'.$row, ($dataForm['grandTotal'] == '0' || $dataForm['grandTotal'] == '-') ? '-' : $this->formatNumber($dataForm['grandTotal']));
            }
            else {
                $worksheet->getStyle('A'.($baseRowEnd + 1).':U'.($baseRowEnd + 1))->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('ffb8cce4');
                $worksheet->setCellValue('AF'.($baseRowEnd + 1), '('.$dataForm['currency'].')');
                $worksheet->setCellValue('AG'.($baseRowEnd + 1), ($dataForm['grandTotal'] == '0' || $dataForm['grandTotal'] == '-') ? '-' : $this->formatNumber($dataForm['grandTotal']));
            }

            $row++;
            $purposeRow = ($itemCount > $templateRowCount) ? $row + 3 : $baseRowEnd + 5;
            $signatureRow = ($itemCount > $templateRowCount) ? $row + 12 : $baseRowEnd + 14;

            $worksheet->getStyle('A'.($purposeRow - 1).':AB'.($purposeRow - 1))->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('ffebf1de');
            if(isset($dataForm['purpose'][0])) {
                $purpose = $dataForm['purpose'][0];
                $purposeDescription = $purpose['description'] ?? ' ';

                switch($purposeDescription) {
                    case 'New purchase':
                        $worksheet->setCellValue('K'.$purposeRow, $purpose['reason'] ?? ' ');
                        $worksheet->setCellValue('AB'.$purposeRow, $purpose['remarks'] ?? ' ');
                        break;

                    case 'Replacement purchase':
                        $purposeRow += 1;
                        $worksheet->setCellValue('K'.$purposeRow, $purpose['reason'] ?? ' ');
                        $worksheet->setCellValue('AB'.$purposeRow, $purpose['remarks'] ?? ' ');
                        break;

                    case 'Routine purchase':
                        $purposeRow += 2;
                        $worksheet->setCellValue('K'.$purposeRow, $purpose['reason'] ?? ' ');
                        $worksheet->setCellValue('AB'.$purposeRow, $purpose['remarks'] ?? ' ');
                        break;

                    case 'Repair':
                        $purposeRow += 3;
                        $worksheet->setCellValue('K'.$purposeRow, $purpose['reason'] ?? ' ');
                        $worksheet->setCellValue('AB'.$purposeRow, $purpose['remarks'] ?? ' ');
                        break;

                    case 'Routine maintenance/service':
                        $purposeRow += 4;
                        $richText = new RichText();
                        $checkmark = $richText->createTextRun('✓ ');
                        $checkmark->getFont()->setBold(true)->setSize(11);

                        $reasonText = $purpose['reason'] ?? ' ';
                        $richText->createTextRun($reasonText);

                        switch($reasonText) {
                            case 'Monthly':
                                $worksheet->getCell('K'.$purposeRow)->setValue($richText);
                                $worksheet->getStyle('K'.$purposeRow)->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('ffebf1de');
                                break;
                            case 'Yearly':
                                $worksheet->getCell('P'.$purposeRow)->setValue($richText);
                                $worksheet->getStyle('P'.$purposeRow)->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('ffebf1de');
                                break;
                            case 'Others':
                                $worksheet->getCell('V'.$purposeRow)->setValue($richText);
                                $worksheet->getStyle('V'.$purposeRow)->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('ffebf1de');
                                break;
                        }

                        $worksheet->setCellValue('AB'.$purposeRow, $purpose['remarks'] ?? '');
                        break;

                    case 'Fixed asset':
                        $purposeRow += 5;
                        $richText = new RichText();
                        $checkmark = $richText->createTextRun('✓ ');
                        $checkmark->getFont()->setBold(true)->setSize(11);

                        $reasonText = $purpose['reason'] ?? ' ';
                        $richText->createTextRun($reasonText);

                        if(in_array($reasonText, ['Budget (Y)', 'Budget (N)'])) {
                            $worksheet->getCell('K'.$purposeRow)->setValue($richText);
                            $worksheet->getStyle('K'.$purposeRow)->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('ffebf1de');
                        } elseif($reasonText == 'New Investment') {
                            $worksheet->getCell('P'.$purposeRow)->setValue($richText);
                            $worksheet->getStyle('P'.$purposeRow)->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('ffebf1de');
                        } elseif($reasonText == 'Replacement') {
                            $worksheet->getCell('V'.$purposeRow)->setValue($richText);
                            $worksheet->getStyle('V'.$purposeRow)->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('ffebf1de');
                        }

                        $worksheet->setCellValue('AB'.$purposeRow, $purpose['remarks'] ?? '');
                        break;
                }
            }

            // $thinBorderStyle = [
            //     'borders' => [
            //         'allBorders' => [
            //             'borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN,
            //             'color' => ['argb' => 'FF000000'],
            //         ],
            //     ],
            // ];

            if(isset($dataForm['signer']) && $dataForm['signer'][2]['flowAs'] == 'APPROVER') {
                // Signer 1 (Submitter)
                if(isset($dataForm['signer'][0])) {
                    $signer = $dataForm['signer'][0];
                    $worksheet->setCellValue('AI'.$signatureRow, 'Submitted at '.($signer['decisionAtTime'] ?? ' '));

                    $model->docApprovalFlowSign()
                        ->where('sign_flow_id', $signer['signerId'])
                        ->update(['cell_column' => 'AI', 'cell_row' =>$signatureRow]);

                    $worksheet->setCellValue('AI'.($signatureRow + 2), $signer['employeeName'] ?? ' ');
                    $worksheet->setCellValue('AI'.($signatureRow + 3), 'Date: '.($signer['decisionAt'] ?? ' '));
                }

                // Signer 2 (Checker)
                if(isset($dataForm['signer'][1])) {
                    $signer = $dataForm['signer'][1];
                    if(!empty($signer['decisionAtTime'])) {
                        $worksheet->setCellValue('AB'.$signatureRow, 'Checked at '.$signer['decisionAtTime']);
                    }

                    $model->docApprovalFlowSign()
                        ->where('sign_flow_id', $signer['signerId'])
                        ->update(['cell_column' => 'AB', 'cell_row' => $signatureRow]);

                    $worksheet->setCellValue('AB'.($signatureRow + 2), $signer['employeeName'] ?? ' ');
                    $worksheet->setCellValue('AB'.($signatureRow + 3), 'Date: '.($signer['decisionAt'] ?? ' '));
                }

                // Signer 3 (Approver)
                if(isset($dataForm['signer'][2])) {
                    $signer = $dataForm['signer'][2];
                    if(!empty($signer['decisionAtTime'])) {
                        $worksheet->setCellValue('T'.$signatureRow, 'Approved at '.$signer['decisionAtTime']);
                    }

                    $model->docApprovalFlowSign()
                        ->where('sign_flow_id', $signer['signerId'])
                        ->update(['cell_column' => 'T', 'cell_row' => $signatureRow]);

                    $worksheet->setCellValue('T'.($signatureRow + 2), $signer['employeeName'] ?? ' ');
                    $worksheet->setCellValue('T'.($signatureRow + 3), 'Date: '.($signer['decisionAt'] ?? ' '));
                }

                // $worksheet->getStyle('AO'.$signatureRow.':AO'.($signatureRow + 3))->applyFromArray($thinBorderStyle);
            }
            else if(isset($dataForm['signer']) && $dataForm['signer'][2]['flowAs'] == 'CHECKER_2') {
                // Signer 1 (Submitter)
                if(isset($dataForm['signer'][0])) {
                    $signer = $dataForm['signer'][0];
                    $worksheet->setCellValue('AJ'.$signatureRow, 'Submitted at '.($signer['decisionAtTime'] ?? ' '));

                    $model->docApprovalFlowSign()
                        ->where('sign_flow_id', $signer['signerId'])
                        ->update(['cell_column' => 'AJ', 'cell_row' => $signatureRow]);

                    $worksheet->setCellValue('AJ'.($signatureRow + 2), $signer['employeeName'] ?? ' ');
                    $worksheet->setCellValue('AJ'.($signatureRow + 3), 'Date: '.($signer['decisionAt'] ?? ' '));
                }

                // Signer 2 (Checker)
                if(isset($dataForm['signer'][1])) {
                    $signer = $dataForm['signer'][1];
                    if(!empty($signer['decisionAtTime'])) {
                        $worksheet->setCellValue('AD'.$signatureRow, 'Checked at '.$signer['decisionAtTime']);
                    }

                    $model->docApprovalFlowSign()
                        ->where('sign_flow_id', $signer['signerId'])
                        ->update(['cell_column' => 'AD', 'cell_row' => $signatureRow]);

                    $worksheet->setCellValue('AD'.($signatureRow + 2), $signer['employeeName'] ?? ' ');
                    $worksheet->setCellValue('AD'.($signatureRow + 3), 'Date: '.($signer['decisionAt'] ?? ' '));
                }

                // Signer 3 (Checker)
                if(isset($dataForm['signer'][2])) {
                    $signer = $dataForm['signer'][2];
                    if(!empty($signer['decisionAtTime'])) {
                        $worksheet->setCellValue('X'.$signatureRow, 'Checked at '.$signer['decisionAtTime']);
                    }

                    $model->docApprovalFlowSign()
                        ->where('sign_flow_id', $signer['signerId'])
                        ->update(['cell_column' => 'X', 'cell_row' => $signatureRow]);

                    $worksheet->setCellValue('X'.($signatureRow + 2), $signer['employeeName'] ?? ' ');
                    $worksheet->setCellValue('X'.($signatureRow + 3), 'Date: '.($signer['decisionAt'] ?? ' '));
                }

                // Signer 4 (Approver)
                if(isset($dataForm['signer'][3])) {
                    $signer = $dataForm['signer'][3];
                    if(!empty($signer['decisionAtTime'])) {
                        $worksheet->setCellValue('R'.$signatureRow, 'Approved at '.$signer['decisionAtTime']);
                    }

                    $model->docApprovalFlowSign()
                        ->where('sign_flow_id', $signer['signerId'])
                        ->update(['cell_column' => 'R', 'cell_row' => $signatureRow]);

                    $worksheet->setCellValue('R'.($signatureRow + 2), $signer['employeeName'] ?? ' ');
                    $worksheet->setCellValue('R'.($signatureRow + 3), 'Date: '.($signer['decisionAt'] ?? ' '));
                }
            }

            // $forceBorders($worksheet, 'AL'.$signatureRow.':AL'.($signatureRow + 3), ['right']);

            $highestRow = $worksheet->getHighestRow();
            $highestColumn = $worksheet->getHighestColumn();
            $worksheet->getPageSetup()->setPrintArea('A1:'.$highestColumn.$highestRow);

            $writer = new Xlsx($spreadsheet);
            $writer->save($tempXlsxFile);

            $pdfWriter = new Mpdf($spreadsheet);
            $pdfWriter->setFont('arial');
            $pdfWriter->save($tempPdfFile);
            return true;
        }
        else if($documentType == '2') { // APPLICATION & PO FORM
            $dataForm = $request->dataForm['dataForm'];
            // dd($request->dataForm['dataForm']);
            // $headerPath = Storage::path('private/template/header_bml_pakuwon.png');

            $templatePath = 'private/template/F.PUR-02.02-04_APPLICATION_FINAL.xlsx';
            $templatePathPo = 'private/template/F.PUR-02.02-04_PO_WITH_QR.xlsx';
            if($dataForm['companyId'] == '316') {
                $headerPath = storage_path('app/private/template/Leterhead_LID_Pakuwon.png');
            }
            else if($dataForm['companyId'] == '317') {
                $headerPath = storage_path('app/private/template/Leterhead_BML_Pakuwon.png');
            }
            else if($dataForm['companyId'] == '322') {
                // $templatePath = 'private/template/F.PUR-02.02-04_APPLICATION_FINAL_VANTEC.xls';
                $templatePathPo = 'private/template/F.PUR-02.02-04_PO_WITH_QR_VANTEC.xlsx';
                $headerPath = storage_path('app/private/template/Leterhead_VID.jpg');
            }

            // APPLICATION FORM
            $spreadsheet = IOFactory::load(Storage::path($templatePath));
            $spreadsheet->getDefaultStyle()->getFont()->setName('arial');
            $spreadsheet->getDefaultStyle()->getAlignment()->setWrapText(true);
            $worksheet = $spreadsheet->getActiveSheet();
            // $worksheet = $spreadsheet->setActiveSheetIndex(0);

            // $drawing = new Drawing();
            // $drawing->setName('Header');
            // $drawing->setDescription('Header Image');
            // $drawing->setPath($headerPath);

            // Positioning
            // $drawing->setCoordinates('A1');

            // // Ukuran dan skala yang tepat
            // $drawing->setWidthAndHeight(1000, 200); // Sesuaikan dengan kebutuhan

            // // Positioning lebih presisi
            // $drawing->setOffsetX(0);
            // $drawing->setOffsetY(0);

            // Pastikan gambar menutupi sel secara penuh
            // $drawing->setResizeProportional(false);

            // $drawing->setWorksheet($worksheet);

            $worksheet->getPageSetup()
                        ->setFitToPage(true)
                        ->setOrientation(PageSetup::ORIENTATION_PORTRAIT)
                        ->setPaperSize(PageSetup::PAPERSIZE_A4)
                        ->setFitToWidth(1)
                        ->setFitToHeight(1);

