                                    <button type="button" class="btn btn-info w-100 w-md-auto me-md-2 saveForm" id="submitDocumentForm" data-type="NEW" data-form="PAYMENT_JOURNAL" data-token="" data-action="SUBMIT">
                                        <i class="fa-regular fa-file-import"></i> Submit Document
                                    </button>
                                </div>';
            }
        }
        else if($requestType == 'NEW_REPORT') {
            $requestData = new Request();
            $requestData->merge(['documentType' => $documentType, 'companyId' => $companyId]);
            $getDocumentType = $this->getDocumentType($requestData);
            $response['title'] = 'REPORT '.$getDocumentType[0]['doc_name'];
            $dataForm = $dataForm->merge([
                'documentType' => $documentType,
            ]);
            $response->put('form', view('documentapproval::report.order_form', compact('dataForm'))->render());
        }

        $response['footerButton'] = '<div class="container-fluid p-0">
                                        <div class="row justify-content-center w-100 mx-0">
