                                        </div>
                                    </div>';

        return response()->json([
            'status' => 200,
            'message' => 'Success',
            'data' => $response,
        ], 200);
    }

    public function suggestion(Request $request) {
        $companyId = $this->companyId;
        $perPage = 10; // Number of items per page
        $currentPage = $request->input('page', 1);
        $search = $request->search;
        $type = $request->type;
        $data = [];
        $hasMorePages = false;
        if(!empty($search) && !empty($type)) {
            $model = new DocumentApprovalModel();
            if($type === 'ITEM') {
                $getSuggestion = $model->masterGoods()
                                    ->from('master_goods as a')
                                    ->leftJoin('master_goods_type as b', 'a.goods_type_id', '=', 'b.goods_type_id')
                                    ->select('a.goods_id', 'a.goods_code', 'a.goods_name', 'a.goods_type_id', 'b.goods_type_name', 'a.unit_id')
                                    ->where(function($getSuggestion) use ($companyId) {
                                        $getSuggestion->whereNull('a.company_id')
                                            ->orWhere('a.company_id',  $companyId);
                                    })
                                    ->where(function($getSuggestion) use ($search) {
                                        $getSuggestion->where('a.goods_name', 'like', '%'.$search.'%')
                                            ->orWhere('a.goods_code', 'like', '%'.$search.'%');
                                    })
                                    ->where('a.is_active', '1')
                                    ->orderBy('goods_name', 'asc')
                                    ->paginate($perPage, ['*'], 'page', $currentPage);
                foreach($getSuggestion as $row) {
                    $data[] = [
                                'id' => $row->goods_id,
                                'text' => $row->goods_name,
                                'goodsTypeId' => $row->goods_type_id,
                                'goodsTypeName' => $row->goods_type_name,
                                'unit' => $row->unit_id,
                            ];
                }
            }
            else if($type === 'TYPE') {
                $getSuggestion = $model->masterGoodsType()
                                    ->select('goods_type_id', 'goods_type_name')
                                    ->where(function($getSuggestion) use ($companyId) {
                                        $getSuggestion->whereNull('company_id')
                                            ->orWhere('company_id',  $companyId);
                                    })
                                    ->where(function($getSuggestion) use ($search) {
                                        $getSuggestion->where('goods_type_name', 'like', '%'.$search.'%')
                                            ->orWhere('goods_type_code', 'like', '%'.$search.'%');
                                    })
                                    ->where('is_active', '1')
                                    // ->orderBy('goods_type_name', 'asc')
                                    ->paginate($perPage, ['*'], 'page', $currentPage);
                foreach($getSuggestion as $row) {
                    $data[] = [
                                'id' => $row->goods_type_id,
                                'text' => $row->goods_type_name,
                            ];
                }
            }

            $hasMorePages = $getSuggestion->hasMorePages();
        }

        return response()->json([
            'data' => $data,
            'status' => 200,
            'hasMorePages' => $hasMorePages,
        ], 200);
    }

    public function getCompany(Request $request) {
        $employeeId = $request->employeeId;
        $model = new DocumentApprovalModel();
        $getUser = $model->vwMasterEmployeeActive()
                        ->from('vw_master_employee_active as a')
                        ->leftJoin('master_company as b', function($join) {
                            $join->on('b.company_id', 'a.company_id');
                        })
                        ->select('a.employee_name', 'a.company_id', 'b.company_code', 'b.company_name')
                        ->where('a.employee_id', $employeeId)
                        ->first();

        $token = ['id' => $employeeId, 'c' => $getUser->company_id];
        $encodedToken = SafeToken::encode($token);
        $arrCompany[] = [
                        'id' => $encodedToken,
                        'text' => $getUser->company_id.' - '.$getUser->company_name,
                        'selected' => true,
                    ];

        $getUserMultiCompany = $model->masterEmployeesMultiCompany()
                                    ->from('master_employees_multi_company as a')
                                    ->leftJoin('master_company as b', function($join) {
                                        $join->on('b.company_id', 'a.company_id');
                                    })
                                    ->select('a.company_id', 'b.company_code', 'b.company_name')
                                    ->where('a.employee_id', $employeeId)
                                    ->where('a.company_id', '<>', $getUser->company_id)
                                    ->where(function($query) {
                                        $query->whereNull('a.menu_id')
                                            ->orWhere('a.menu_id', '=', '3') // 3 = Document Eapproval
                                            ->orWhere('a.menu_id', '=', '4'); // 4 = Procurement & Purchasing
                                    })
                                    ->where('a.is_active', 1)
                                    ->orderBy('a.company_id', 'asc')
                                    ->get();
        if ($getUserMultiCompany->isNotEmpty()) {
            if($request->selectedDefault == false) {
                $arrCompany[0]['selected'] = false;
            }

            foreach($getUserMultiCompany as $rowUserMultiCompany) {
                $token = ['id' => $employeeId, 'c' => $rowUserMultiCompany->company_id];
                $encodedToken = SafeToken::encode($token);
                $arrCompany[] = [
                                    'id' => $encodedToken,
                                    'text' => $rowUserMultiCompany->company_id.' - '.$rowUserMultiCompany->company_name,
                                    'selected' => false,
                                ];
            }
        }

        return $arrCompany;
    }

    public function getDepartment(Request $request) {
        $companyId = $this->companyId;
        $departmentId = $request->departmentId;
        if($request->companyId) {
            try {
                $decryptedToken = SafeToken::decode($request->companyId);
                $companyId = $decryptedToken['c'];
            }
            catch (\Exception $e) {
                $companyId = $request->companyId;
            }
        }

        $model = new DocumentApprovalModel();
        if($departmentId == 'ALL' || $departmentId == '') {
            $getData = $model->vwMasterDepartment()
                            ->from('vw_master_department as a')
                            ->select('a.department_id as departmentId',
                                    'a.department_name as departmentName',
                                    DB::raw('(
                                        SELECT GROUP_CONCAT(DISTINCT cost_center SEPARATOR ", ")
                                        FROM vw_master_cost_center
                                        WHERE company_id = '.$companyId.'
                                        AND department_id = a.department_id
                                        AND cost_center IS NOT NULL
                                        ORDER BY cost_center ASC
                                    ) as costCenter')
                                )
                            ->where('a.company_id', '=', $companyId)
                            ->orderBy('a.department_name', 'asc')
                            ->get();
        }
        else {
            $getData = $model->vwMasterDepartment()
                            ->from('vw_master_department as a')
                            ->select('a.department_id as departmentId',
                                    'a.department_name as departmentName',
                                    DB::raw('(
                                        SELECT GROUP_CONCAT(DISTINCT cost_center SEPARATOR ", ")
                                        FROM vw_master_cost_center
                                        WHERE company_id = '.$companyId.'
                                        AND department_id = a.department_id
                                        AND cost_center IS NOT NULL
                                        ORDER BY cost_center ASC
                                    ) as costCenter')
                            )
                            ->where('a.department_id', '=', $departmentId)
                            ->where('a.company_id', '=', $companyId)
                            ->first();
        }
        return $getData;
    }

    public function getDocumentType(Request $request) {
        $companyId = $request->companyId;
        $viewType = $request->viewType;
        $model = new DocumentApprovalModel();
        $getData = $model->masterDocumentTypes()
                        ->from('master_doc_types as a')
                        ->select('a.*', 'b.group_name', 'b.group_description')
                        ->leftJoin('master_doc_groups as b', 'b.doc_group_id', '=', 'a.doc_group_id')
                        ->where(function($query) use ($companyId) {
                            $query->whereNull('a.company_id')
                                ->orWhere('a.company_id', '=', $companyId);
                        });

        // if($viewType == 'APPROVAL') {
        //     $getData = $getData->where(function($query) use ($viewType) {
        //         $query->where('a.view_type', '=', $viewType)
        //             ->orWhere('a.view_type', '=', 'REQUEST');
        //     });
        // }
        // else {
        //     $getData = $getData->where('a.view_type', '=', $viewType);
        // }

        if($request->documentType != 'ALL') {
            $getData = $getData->where('a.doc_type_id', $request->documentType);
        }

        $getData = $getData->where('a.is_active', '=', '1')
                            ->where('a.is_view', '=', '1')
                            ->orderBy('a.doc_order', 'asc')
                            ->orderBy('a.doc_group_id', 'asc')
                            ->orderBy('a.doc_type_id', 'asc')
                            ->get();
        return $getData;
    }

    public function getDocumentTypeRequest(Request $request) {
        $employeeId = $this->employeeId;
        $companyId = $this->companyId;
        $viewType = $request->viewType;
        $model = new DocumentApprovalModel();
        $getData = $model->masterDocumentTypes()->from('master_doc_types as a')
                                                ->select('a.doc_type_id', 'a.doc_name', 'b.doc_group_id', 'b.group_name', 'b.group_description')
                                                ->leftJoin('master_doc_groups as b', 'b.doc_group_id', '=', 'a.doc_group_id')
                                                ->where(function($query) use ($companyId) {
                                                    $query->whereNull('a.company_id')
                                                        ->orWhere('a.company_id', '=', $companyId);
                                                });
        if($request->documentType != 'ALL') {
            $getData = $getData->where('a.doc_type_id', $request->documentType);
        }

        $getData = $getData->where('a.is_active', '=', '1')
                            ->where('a.is_view', '=', '1')
                            ->where('a.view_type', '=', $viewType);

            if($viewType == 'APPROVAL') {
                $getData = $getData->orWhere('a.view_type', '=', 'REQUEST');
            }

            $getData = $getData->orderBy('b.group_order', 'asc')
                            ->orderBy('a.doc_order', 'asc')
                            ->orderBy('a.doc_type_id', 'asc')
                            ->get();

        $documentType = [];
        foreach ($getData as $rowData) {
            $groupId = $rowData->doc_group_id;
            if (!isset($documentType[$groupId])) {
                $documentType[$groupId] = [
                    'groupName' => $rowData->group_name,
                    'items' => [],
                ];
            }

            $documentType[$groupId]['items'][] = [
                'id' => $rowData->doc_type_id,
                'text' => $rowData->doc_name,
            ];
        }

        // Reset indeks array JSON
        $documentType = array_values($documentType);
        return response()->json([
            'data' => $documentType,
        ]);
    }

