        $getData = $model->masterDocPurpose()->select('purpose_id', 'purpose_name', 'purpose_description')
                                            ->where('is_active', '=', '1')
                                            ->orderBy('purpose_name', 'asc')
                                            ->get();
        $response = array();
        $x = 0;
        foreach ($getData as $row) {
            $getReason = $model->masterDocPurposeReason()->select('reason_id', 'reason_name')
                                            ->where('purpose_id', '=', $row->purpose_id)
                                            ->where('is_active', '=', '1')
                                            ->orderBy('reason_id', 'asc')
                                            ->get();
            $arrReason = array();
            foreach ($getReason as $rowReason) {
                $getReasonOption = $model->masterDocPurposeReasonOption()->select('reason_option_id', 'reason_option_name')
                                    ->where('reason_id', '=', $rowReason->reason_id)
                                    ->where('is_active', '=', '1')
                                    ->orderBy('reason_option_id', 'asc')
                                    ->get();

                $arrReasonOption = array();
                foreach ($getReasonOption as $rowReasonOption) {
                    $arrReasonOption[] = array(
                                                'reason_option_id' => $rowReasonOption->reason_option_id,
                                                'reason_option_name' => $rowReasonOption->reason_option_name,
                                        );
                }

                $arrReason[] = array(
                                        'reason_id' => $rowReason->reason_id,
                                        'reason_name' => $rowReason->reason_name,
                                        'reason_option' => $arrReasonOption,
                                );
            }

            $response[] = array(
                                'purpose_id' => $row->purpose_id,
                                'purpose_name' => $row->purpose_name,
                                'purpose_description' => $row->purpose_description,
                                'reason' => $arrReason,
                            );
        }
        return $response;
    }

    public function getReason(Request $request){
        $documentTypeId = $request->documentType;
        $purposeId = $request->purposeId;
        $model = new DocumentApprovalModel();
        $getReason = $model->masterDocPurposeReason()->select('reason_id', 'reason_name')
                                            ->where('purpose_id', '=', $purposeId)
                                            ->where('is_active', '=', '1')
                                            ->orderBy('reason_id', 'asc')
                                            ->get();
        return $getReason;
    }

    public function getLocation(Request $request){
        if($request->token) {
            $token = SafeToken::decode($request->token);
            $companyId = $token['c'];
            $departmentId = $token['d'];
        }
        else {
            $companyId = $request->companyId;
            $departmentId = $request->departmentId;
        }

        $model = new DocumentApprovalModel();
        $getLocation = $model->vwMasterLocation()
                            ->select('location_name')
                            ->where('company_id', '=', $companyId)
                            ->where('department_id', '=', $departmentId)
                            ->groupBy('location_name')
                            ->get();

        $data = [];
        foreach ($getLocation as $row) {
            $data[] = ['locationId' => $row->location_name, 'locationName' => $row->location_name];
        }
        return response()->json(['data' => $data,'status' => 200], 200);
    }

    public function getApproval(Request $request){
        $employeeId = $this->employeeId;
        $companyId = $this->companyId;
        $employeeName = $this->employeeName;
        $roleId = $this->roleId;

        $documentTypeId = $request->documentType;
        $dataType = $request->dataType;
        $departmentId = $request->departmentId;
        $locationId = $request->locationId;
        $model = new DocumentApprovalModel();

        if($documentTypeId == '7' || $documentTypeId == '8' || $documentTypeId == '9') { // OTHER DOCUMENT
            $getApproval = $model->docApprovalMatrix()
                                ->select('b.employee_id', 'b.employee_name', 'b.position_name')
                                ->leftJoin('vw_master_employee_active as b', function($join) {
                                    $join->on('b.employee_id', '=', 'doc_approval_matrix.employee_id_approval');
                                })
                                ->where('doc_approval_matrix.company_id', '=', $companyId)
                                ->where('doc_approval_matrix.doc_type_id', '=', $documentTypeId)
                                ->where('doc_approval_matrix.matrix_as', '=', $dataType)
                                ->where('doc_approval_matrix.is_active', '=', '1')
                                ->orderBy('b.employee_name', 'asc')
                                ->get();
            return $getApproval;
        }
        else {
            if ($request->token) {
                $token = SafeToken::decode($request->token);
                $validator = Validator::make($token, [
                    'id' => 'required',
                    'a' => 'required',
                    'b' => 'required',
                ]);

                $docApprovalId = $token['a'];
                $referenceId = $token['b'];
                $response = collect();

                if($documentTypeId == '1') {
                    $getForm = $model->documentApprovalDetailOrder()
                                    ->from('doc_approval_detail_order_form')
                                    ->select('order_form_status as form_status', 'employee_id', 'department_id', 'location_id')
                                    ->where('doc_approval_id', $docApprovalId)
                                    ->where('order_form_id', '=', $referenceId)
                                    ->where('is_active', '1')
                                    ->first();
                }

                if($getForm) {
                    if($getForm->form_status == '2') { // 2 = SUBMITTED
                        $arrSigner = array();
                        $readonlyStep = '';
                        $getFlowSign = $model->docApprovalFlowSign()
                                            ->from('doc_approval_flow_sign as a')
                                            ->leftJoin('vw_master_employee_all as b', function($join) {
                                                $join->on('b.employee_id', '=', 'a.employee_id');
                                            })
                                            ->select('a.employee_id', 'a.flow_as', 'a.status', 'b.employee_name')
                                            ->where('a.flow_as', '<>', 'APPLICANT')
                                            ->where('a.doc_approval_id', '=', $docApprovalId)
                                            ->where('a.doc_type_id', '=', $documentTypeId)
                                            ->where('a.reference_id', '=', $referenceId)
                                            ->whereIn('a.status', ['3', '8', '9', '13'])
                                            ->where('a.is_active', '=', '1')
                                            ->orderBy('a.sign_flow_id', 'asc')
                                            ->get();
                        foreach($getFlowSign as $rowFlowSign) {
                            if($rowFlowSign->flow_as == 'CHECKER') {
                                if(!array_key_exists('REVIEWER_1', $arrSigner)) {
                                    $rowFlowSign->flow_as = 'REVIEWER_1';
                                }
                                else {
                                    $rowFlowSign->flow_as = 'REVIEWER_2';
                                }
                            }

                            $arrSigner[$rowFlowSign->flow_as] = [
                                                                    'employeeId' => $rowFlowSign->employee_id,
                                                                    'employeeName' => Str::upper($rowFlowSign->employee_name),
                                                                    'positionName' => null,
                                                                    'flowAS' => $rowFlowSign->flow_as,
                                                                    'readonly' => ($rowFlowSign->status == '3' || $rowFlowSign->status == '13') ? false : true,
                                                                ];
                        }

                        $arrApproval = array();
                        $getApproval = $model->docApprovalMatrix()
                                            ->from('doc_approval_matrix as a')
                                            ->leftJoin('vw_master_employee_active as b', function($join) {
                                                $join->on('b.employee_id', '=', 'a.employee_id_approval');
                                            })
                                            ->select('b.employee_id', 'b.employee_name', 'b.position_name', 'a.matrix_as', 'a.matrix_order')
                                            ->where('a.employee_id', '=', $getForm->employee_id)
                                            ->where('a.department_id', '=', $getForm->department_id)
                                            ->where('a.doc_type_id', '=', $documentTypeId)
                                            ->where('a.is_active', '=', '1')
                                            ->orderBy('a.matrix_as', 'asc')
                                            ->orderBy('b.employee_name', 'asc')
                                            ->get();
                        foreach($getApproval as $rowApproval) {
                            if($rowApproval->matrix_as == 'REVIEWER') {
                                $flowAs = $rowApproval->matrix_as.'_'.$rowApproval->matrix_order;
                            }
                            else {
                                $flowAs = $rowApproval->matrix_as;
                            }

                            if(array_key_exists($flowAs, $arrSigner)) {
                                if($arrSigner[$flowAs]['readonly'] == true && $readonlyStep == $flowAs){
                                    continue;
                                }

                                if($arrSigner[$flowAs]['readonly'] == true && $arrSigner[$flowAs]['employeeId'] == $rowApproval->employee_id) {
                                    $arrApproval[$flowAs][] = ['employeeId' => $arrSigner[$flowAs]['employeeId'],
                                                             'employeeName' => $arrSigner[$flowAs]['employeeName'],
                                                             'positionName' => $arrSigner[$flowAs]['positionName'],
                                                             'flowAs' => $flowAs,
                                                             'readonly' => $arrSigner[$flowAs]['readonly'],
                                                             'selected' => true,
                                                        ];
                                    $readonlyStep = $flowAs;
                                }
                                else {
                                    $selected = false;
                                    if($arrSigner[$flowAs]['employeeId'] == $rowApproval->employee_id) {
                                        $selected = true;
                                    }

                                    $arrApproval[$flowAs][] = ['employeeId' => $rowApproval->employee_id,
                                                               'employeeName' => Str::upper($rowApproval->employee_name),
                                                               'positionName' =>$rowApproval->position_name,
                                                               'readonly' => false,
                                                               'selected' => $selected,
                                                            ];
                                }
                            }
                            else {
                                $arrApproval[$flowAs][] = ['employeeId' => $rowApproval->employee_id,
                                                           'employeeName' => Str::upper($rowApproval->employee_name),
                                                           'positionName' => $rowApproval->position_name,
                                                           'readonly' => false,
                                                           'selected' => false,
                                                        ];
                            }
                        }

                        if(!array_key_exists('REVIEWER_2', $arrSigner)) {
                            $arrApproval['REVIEWER_2'] = array();
                        }

                        $response->put('approval', $arrApproval);
                        $response->put('locationId', $getForm->location_id);
                        $response->put('departmentId', $getForm->department_id);

                        return response()->json([
                            'status' => 200,
                            'message' => 'Success',
                            'data' => $response->toArray(),
                        ], 200);
                    }
                    else {
                        $formStatus = '';
                        if($getForm->form_status == '6') {
                            $formStatus = 'REVISED';
                        }
                        else if($getForm->form_status == '8') {
                            $formStatus = 'APPROVED';
                        }
                        else if($getForm->form_status == '9') {
                            $formStatus = 'REJECTED';
                        }
                        else if($getForm->form_status == '12') {
                            $formStatus = 'CANCELED';
                        }

                        $message = 'Form has been '.$formStatus.', please refresh this page.';
                        return response()->json([
                            'status' => 200,
                            'message' => $message,
                            'data' => $response,
                        ], 200);
                    }
                }
                else {
                    return response()->json([
                        'status' => 404,
                        'message' => 'Form not found, please refresh this page.',
                        'data' => $response,
                    ], 404);
                }
            }
            else {
                $matrixAs = $dataType;
                if($dataType == 'REVIEWER_1' || $dataType == 'REVIEWER_2') {
                    $matrixAs = 'REVIEWER';
                }

                $getApproval = $model->docApprovalMatrix()
                                    ->from('doc_approval_matrix as a')
                                    ->leftJoin('vw_master_employee_active as b', function($join) {
                                        $join->on('b.employee_id', '=', 'a.employee_id_approval');
                                    })
                                    ->select('b.employee_id', 'b.employee_name', 'b.position_name')
                                    ->where('a.employee_id', '=', $employeeId)
                                    ->where('a.department_id', '=', $departmentId)
                                    ->where('a.doc_type_id', '=', $documentTypeId)
                                    ->where('a.matrix_as', '=', $matrixAs);

                                    if($dataType == 'REVIEWER_1') {
                                        $getApproval = $getApproval->where('matrix_order', '1');
                                    }
                                    else if($dataType == 'REVIEWER_2') {
                                        $getApproval = $getApproval->where('matrix_order', '2');
                                    }

                $getApproval = $getApproval->where('a.is_active', '=', '1')
                                    ->orderBy('b.employee_name', 'asc')
                                    ->get();
                if($getApproval->isNotEmpty()){
                    return $getApproval;
                }
                else if($dataType != 'CC'){
                    // $myData = $model->viewMasterEmployeeActive()->select('job_code')
                    //             ->where('employee_id', '=', $employeeId)
                    //             ->first();

                    // $getApproval = $model->viewMasterEmployeeActive()
                    //                     ->select('employee_id', 'employee_name', 'position_name')
                    //                     ->where('employee_id', '<>', $employeeId);

                    // if ($dataType === 'REVIEWER') {
                    //     if($departmentId){
                    //         $getApproval->where('department_id', '=', $departmentId);
                    //     }

                    //     $getApproval->where('job_code', '<', $myData->job_code);
                    // }
                    // else if ($dataType === 'APPROVER') {
                    //     $getApproval->where('job_code', '<=',  $myData->job_code);
                    // }

                    // $getApproval = $getApproval->orderBy('employee_name', 'asc')->get();
                    // if($getApproval->isEmpty()){
                    //     $getApproval = $model->viewMasterEmployeeActive()->select('employee_id', 'employee_name', 'position_name')
                    //                     ->where('job_code', '=', '3')
                    //                     ->get();
                    // }

                    // return $getApproval;
                    return null;
                }
            }
        }
    }

    public function getEmployee(Request $request){
        $companyId = $this->companyId;
        $search = $request->input('term');
        $dataType = $request->dataType;
        $page = (int) $request->input('page', 1);
        $perPage = 10;

        $model = new DocumentApprovalModel();
        if($request->company) {
            $decryptedToken = SafeToken::decode($request->company);
            $companyId = $decryptedToken['c'];
        }

        $data = array();
        if($request->dataForm == 'ORDER_FORM') {
            if($dataType == 'APPLICANT_MATRIX') {
                $decryptedToken = SafeToken::decode($request->tokenForm);
                $employeeId = $decryptedToken['id'];
                $companyId = $decryptedToken['c'];

                if($request->dataMatrix === 'DEPARTMENT') {
                    $getMatrix = $model->docApprovalMatrix()
                                    ->from('doc_approval_matrix as a')
                                    ->leftJoin('vw_master_department as b', 'b.department_id', '=', 'a.department_id')
                                    ->leftJoin('vw_master_cost_center as c', 'c.department_id', '=', 'b.department_id')
                                    ->select('a.department_id', 'b.department_name', 'c.cost_center')
                                    ->distinct()
                                    ->where('a.employee_id', $employeeId)
                                    ->where('a.company_id', $companyId)
                                    ->where('a.doc_type_id', '1') // 1 = ORDER FORM
                                    ->where('a.is_active', '1')
                                    ->orderBy('b.department_name', 'asc')
                                    ->get();
                    if($getMatrix->isNotEmpty()) {
                        foreach($getMatrix as $rowMatrix) {
                            $data[] = [
                                        'departmentId' => $encodeToken = SafeToken::encode(['id' => $employeeId, 'c' => $companyId, 'd' => $rowMatrix->department_id]),
                                        'departmentName' => $rowMatrix->department_name,
                                        'costCenter' => $rowMatrix->cost_center,
                                    ];
                        }
                    }
                }
                else if($request->dataMatrix === 'APPROVAL_FLOW') {
                    $departmentId = $decryptedToken['d'];
                    $orderFormFlow = ['APPLICANT', 'CHECKER_1', 'CHECKER_2', 'CC', 'APPROVER', 'RECEIVER'];
                    $getMatrix = $model->docApprovalMatrix()
                                    ->from('doc_approval_matrix as a')
                                    ->leftJoin('vw_master_employee_active as b', 'b.employee_id', '=', 'a.employee_id')
                                    ->leftJoin('vw_master_department as c', 'c.department_id', '=', 'a.department_id')
                                    ->leftJoin('vw_master_employee_active as d', 'd.employee_id', '=', 'a.employee_id_approval')
                                    ->select('a.employee_id', 'b.employee_name', 'b.department_name as applicant_department_name', 'b.position_name as applicant_position_name', 'c.department_name', 'a.matrix_as', 'a.matrix_order', 'a.employee_id_approval as employee_id_approver', 'd.employee_name as approver_name', 'd.position_name as approver_position_name',
                                    DB::raw('(
                                        SELECT GROUP_CONCAT(DISTINCT cost_center SEPARATOR ", ")
                                        FROM vw_master_cost_center
                                        WHERE company_id = '.$companyId.'
                                        AND department_id = a.department_id
                                        AND cost_center IS NOT NULL
                                        ORDER BY cost_center ASC
                                    ) as cost_center'))
                                    ->where('a.employee_id', $employeeId)
                                    ->where('a.department_id', $departmentId);
                    if($request->matrixType) {
                        $getMatrix = $getMatrix->where('matrix_as', $request->matrixType);
                    }

                    $getMatrix = $getMatrix->whereIn('a.doc_type_id', ['1','4']) // 1 = ORDER FORM, 4 = INSPECTION FORM
                                    ->where('a.is_active', '1')
                                    ->orderBy('a.matrix_id', 'asc')
                                    ->get();
                    if($getMatrix->isNotEmpty()) {
                        $data[] = [
                                    'flow' => 'APPLICANT',
                                    'employeeId' => $getMatrix[0]->employee_id,
                                    'employeeName' => Str::upper($getMatrix[0]->employee_name),
                                    'departmentNameApplicant' => $getMatrix[0]->applicant_department_name,
                                    'positionName' => $getMatrix[0]->applicant_position_name,
                                    'departmentId' => $departmentId,
                                    'departmentName' => $getMatrix[0]->department_name,
                                    'costCenter' => $getMatrix[0]->cost_center,
                                ];

                        foreach($getMatrix as $rowMatrix) {
                            $data[] = [
                                        'flow' => $rowMatrix->matrix_as,
                                        'employeeId' => $rowMatrix->employee_id_approver,
                                        'employeeName' => $rowMatrix->approver_name,
                                        'positionName' => $rowMatrix->approver_position_name,
                                    ];
                        }
                    }
                }
                return response()->json(['data' => $data,'status' => 200], 200);
            }
            else {
                $getData = $model->vwMasterEmployeeActive()
                                ->from('vw_master_employee_active as a')
                                ->leftJoin('master_employees_multi_company as b', function($join) {
                                    $join->on('b.employee_id', '=', 'a.employee_id')
                                        ->where('b.is_active', '1');
                                })
                                ->select('a.employee_id', 'a.employee_name', 'a.position_name', 'a.department_name')
                                ->distinct()
                                ->where(function($query) use ($companyId) {
                                    $query->where('a.company_id', '=', $companyId)
                                        ->orWhere('b.company_id', '=', $companyId);
                                })
                                ->where(function($query) use ($search) {
                                    $query->where('a.employee_name', 'like', '%'.$search.'%')
                                        ->orWhere('a.employee_id', 'like', '%'.$search.'%')
                                        ->orWhere('a.position_name', 'like', '%'.$search.'%')
                                        ->orWhere('a.department_name', 'like', '%'.$search.'%');
                                });

                if ($dataType === 'APPLICANT') {
                    $getData->whereNotIn('a.job_code', ['FO','OPC','OC']);

                }
                else if ($dataType === 'CHECKER_1' || $dataType === 'CHECKER_2') {
                    $getData->whereIn('a.job_code', ['MGR','SPV','SNM','AMG','SOF','SLP','SPV','ASV','STM','OP']);

                }
                else if ($dataType === 'APPROVER') {
                    $getData->whereIn('a.job_code', ['DIR','GM','MGR','SNM','AMG','SPV','ASV','STM','OP','SOF']);
                }
                else if ($dataType === 'CC') {
                    $getData->whereIn('a.job_code', ['MGR','SNM','AMG','SPV','ASV','STM','OP','SOF']);
                }
                else if ($dataType === 'PO_APPLICANT') {
                    $getData->whereIn('a.job_code', ['AMG','SPV','SCC','OFE','ASV','SOF','SLD','STP']);
                }

                $getData = $getData->orderBy('a.employee_name', 'asc');
                $total = $getData->count();

                $results = $getData->skip(($page - 1) * $perPage)
                    ->take($perPage)
                    ->get()
                    ->map(function ($row) {
                        return [
                            'id' => $row->employee_id,
                            'text' => Str::upper($row->employee_name),
                            'description1' => $row->position_name,
                            'description2' => ($row->department_name) ? 'Dept. : '.$row->department_name : null,
                        ];
                    });

                return response()->json([
                    'data' => $results,
                    'more' => ($total > $page * $perPage)
                ]);
            }
        }
        else if($request->dataForm == 'APPLICATION_PO_FORM') {
            if($dataType == 'APPLICANT_MATRIX') {
                $decryptedToken = SafeToken::decode($request->tokenForm);
                $ruleGroupId = $decryptedToken['i'];

                $getFlowRuleGroup = $model->masterFlowRuleGroup()
                                    ->from('master_flow_rule_group as a')
                                    ->leftJoin('master_flow_rule_condition as b', function($join) {
                                        $join->on('b.rule_group_id', '=', 'a.rule_group_id')
                                            ->where('b.is_active', '1');
                                    })
                                    ->leftJoin('master_flow_rule_field as c', function($join) {
                                        $join->on('c.field_id', '=', 'b.field_id')
                                            ->where('c.is_active', '1');
                                    })
                                    ->select('a.rule_group_name', 'b.condition_id', 'b.field_id', 'b.field', 'b.operator', 'c.value_type', 'b.value_id', 'b.value', 'b.logical_operator', 'b.group_condition', 'b.group_color')
                                    ->where('a.rule_group_id', $ruleGroupId)
                                    ->orderBy('b.order', 'asc')
                                    ->get();
                foreach($getFlowRuleGroup as $rowFlowRuleGroup) {
                    $encodeToken = SafeToken::encode(['i' => $rowFlowRuleGroup->condition_id]);
                    $flowRule = [
                                    'conditionId' => $encodeToken,
                                    'groupColor' => $rowFlowRuleGroup->group_color,
                                    'ruleGroupName' => $rowFlowRuleGroup->rule_group_name,
                                    'fieldId' => $rowFlowRuleGroup->field_id,
                                    'fieldName' => $rowFlowRuleGroup->field,
                                    'operator' => $rowFlowRuleGroup->operator,
                                    'nextFlow' => $rowFlowRuleGroup->value_type,
                                    'valueId' => $rowFlowRuleGroup->value_id,
                                    'value' => $rowFlowRuleGroup->value,
                                ];

                    $data['rule'][] = $flowRule;
                }

                $applicationFormFlow = ['APPLICANT','REVIEWER','CONFIRMER_1','REVIEW_ADMIN','CONFIRMER_2','ACKNOWLEDGER','APPROVER'];
                $getFlowRuleAction = $model->masterFlowRuleAction()
                                    ->from('master_flow_rule_action as a')
                                    ->leftJoin('vw_master_employee_active as b', 'a.action_value', '=', 'b.employee_id')
                                    ->leftJoin('master_flow_rule_group as c', 'a.rule_group_id', '=', 'c.rule_group_id')
                                    ->select('b.employee_name', 'a.action_type', 'a.action_value')
                                    ->whereNotNull('b.employee_name')
                                    ->where('a.rule_group_id', $ruleGroupId)
                                    ->where('a.is_active', '1')
                                    ->orderBy('a.action_id', 'asc')
                                    ->get();
                foreach($getFlowRuleAction as $rowFlowRuleAction) {
                    $flowRule = [
                                    'flow' => $rowFlowRuleAction->action_type,
                                    'employeeId' => $rowFlowRuleAction->action_value,
                                    'employeeName' => Str::upper($rowFlowRuleAction->employee_name),
                                ];

                    $data['action'][] = $flowRule;
                }

                return response()->json(['data' => $data,'status' => 200], 200);
            }
            else {
                $getData = $model->vwMasterEmployeeActive()
                                ->from('vw_master_employee_active as a')
                                ->leftJoin('master_employees_multi_company as b', function($join) {
                                    $join->on('b.employee_id', '=', 'a.employee_id')
                                        ->where('b.is_active', '1');
                                })
                                ->select('a.employee_id', 'a.employee_name', 'a.position_name', 'a.department_name')
                                ->distinct()
                                ->where(function($query) use ($companyId) {
                                    $query->where('a.company_id', '=', $companyId)
                                        ->orWhere('b.company_id', '=', $companyId);
                                })
                                ->where(function($query) use ($search) {
                                    $query->where('a.employee_name', 'like', '%'.$search.'%')
                                        ->orWhere('a.employee_id', 'like', '%'.$search.'%')
                                        ->orWhere('a.position_name', 'like', '%'.$search.'%');
                                });


                if ($dataType === 'APPLICANT') {
                    $getData->whereIn('a.job_code', ['STP','SPV','SLD','SLP','OFE','SCC']);
                }
                elseif ($dataType === 'REVIEWER' || $dataType === 'REVIEW_ADMIN') {
                    $getData->whereIn('a.job_code', ['SNM','MGR','SCC','SPV','SLD','OFE','ASV','STM','AMG']);
                }
                else if($dataType == 'CONFIRMER_1') {
                    $getData->whereIn('a.job_code', ['SNM','MGR','ASV','SPV','SCC','SLD','STM','AMG']);
                }
                else if($dataType == 'CONFIRMER_2') {
                    $getData->whereIn('a.job_code', ['SNM','MGR','STM','AMG']);
                }
                else if($dataType == 'ACKNOWLEDGER') {
                    $getData->whereIn('a.job_code', ['DIR','GM','SNM','MGR']);
                }
                else if($dataType == 'APPROVER') {
                    $getData->whereIn('a.job_code', ['PD','DIR','GM','SNM','MGR']);
                }

                $getData = $getData->orderBy('a.employee_name', 'asc');
                $total = $getData->count();

                $results = $getData->skip(($page - 1) * $perPage)
                    ->take($perPage)
                    ->get()
                    ->map(function ($row) {
                        return [
                            'id' => $row->employee_id,
                            'text' => Str::upper($row->employee_name),
                            'description1' => $row->position_name,
                            'description2' => ($row->department_name) ? 'Dept. : '.$row->department_name : null,
                        ];
                    });

                return response()->json([
                    'data' => $results,
                    'more' => ($total > $page * $perPage)
                ]);
            }
        }
        else if($request->dataForm == 'INSPECTION_FORM') {
            if($dataType == 'INSPECTION_MATRIX') {
                $decryptedToken = SafeToken::decode($request->tokenForm);
                $employeeId = $decryptedToken['id'];
                $companyId = $decryptedToken['c'];

                if($request->dataMatrix === 'DEPARTMENT') {
                    $getMatrix = $model->docApprovalMatrix()
                                    ->from('doc_approval_matrix as a')
                                    ->leftJoin('vw_master_department as b', 'b.department_id', '=', 'a.department_id')
                                    ->leftJoin('vw_master_cost_center as c', 'c.department_id', '=', 'b.department_id')
                                    ->select('a.department_id', 'b.department_name', 'c.cost_center')
                                    ->distinct()
                                    ->where('a.employee_id', $employeeId)
                                    ->where('a.company_id', $companyId)
                                    ->where('a.doc_type_id', '4') // 1 = ORDER FORM
                                    ->where('a.is_active', '1')
                                    ->orderBy('b.department_name', 'asc')
                                    ->get();
                    if($getMatrix->isNotEmpty()) {
                        foreach($getMatrix as $rowMatrix) {
                            $data[] = [
                                        'departmentId' => $encodeToken = SafeToken::encode(['id' => $employeeId, 'c' => $companyId, 'd' => $rowMatrix->department_id]),
                                        'departmentName' => $rowMatrix->department_name,
                                        'costCenter' => $rowMatrix->cost_center,
                                    ];
                        }
                    }
                }
                else if($request->dataMatrix === 'APPROVAL_FLOW') {
                    $departmentId = $decryptedToken['d'];
                    $orderFormFlow = ['INSPECTION_RECEIVER', 'INSPECTION_CHECKER', 'INSPECTION_APPROVER'];
                    $getReceiver = $model->docApprovalMatrix()
                                    ->from('doc_approval_matrix as a')
                                    ->leftJoin('vw_master_employee_active as b', 'b.employee_id', '=', 'a.employee_id_approval')
                                    ->leftJoin('vw_master_department as c', 'c.department_id', '=', 'a.department_id')
                                    ->select('a.employee_id_approval', 'b.employee_name', 'b.position_name', 'c.department_name', 'a.matrix_as')
                                    ->where('a.employee_id_approval', $employeeId)
                                    ->where('a.department_id', $departmentId)
                                    ->where('a.doc_type_id', '4')
                                    ->where('a.matrix_as', 'INSPECTION_RECEIVER')
                                    ->where('a.is_active', '1')
                                    ->first();
                    if($getReceiver) {
                        $data[] = [
                            'flow' => 'INSPECTION_RECEIVER',
                            'employeeId' => $getReceiver->employee_id_approval,
                            'employeeName' => Str::upper($getReceiver->employee_name),
                            'departmentName' => $getReceiver->department_name,
                            'positionName' => $getReceiver->position_name,
                            'departmentId' => $departmentId
                        ];

                        $getMatrix = $model->docApprovalMatrix()
                                        ->from('doc_approval_matrix as a')
                                        ->leftJoin('vw_master_employee_active as b', 'b.employee_id', '=', 'a.employee_id_approval')
                                        ->select('a.employee_id_approval', 'b.employee_name', 'b.position_name', 'a.matrix_as', 'a.matrix_order')
                                        ->where('a.employee_id', $employeeId)
                                        ->where('a.department_id', $departmentId)
                                        ->where('a.matrix_as', '<>', 'INSPECTION_RECEIVER');
                        if($request->matrixType) {
                            $getMatrix = $getMatrix->where('matrix_as', $request->matrixType);
                        }

                        $getMatrix = $getMatrix->where('a.doc_type_id', '4') // 4 = INSPECTION FORM
                                        ->where('a.is_active', '1')
                                        ->orderBy('a.matrix_id', 'asc')
                                        ->get();
                        foreach($getMatrix as $rowMatrix) {
                            $data[] = [
                                'flow' => $rowMatrix->matrix_as,
                                'employeeId' => $rowMatrix->employee_id_approval,
                                'employeeName' => Str::upper($rowMatrix->employee_name),
                                'positionName' => $rowMatrix->position_name,
                            ];
                        }
                    }
                }

                return response()->json(['data' => $data,'status' => 200], 200);
            }
            else {
                $getData = $model->vwMasterEmployeeActive()
                                ->from('vw_master_employee_active as a')
                                ->leftJoin('master_employees_multi_company as b', function($join) {
                                    $join->on('b.employee_id', '=', 'a.employee_id')
                                        ->where('b.is_active', '1');
                                })
                                ->select('a.employee_id', 'a.employee_name', 'a.position_name', 'a.department_name')
                                ->distinct()
                                ->where(function($query) use ($companyId) {
                                    $query->where('a.company_id', '=', $companyId)
                                        ->orWhere('b.company_id', '=', $companyId);
                                })
                                ->where(function($query) use ($search) {
                                    $query->where('a.employee_name', 'like', '%'.$search.'%')
                                        ->orWhere('a.employee_id', 'like', '%'.$search.'%')
                                        ->orWhere('a.position_name', 'like', '%'.$search.'%')
                                        ->orWhere('a.department_name', 'like', '%'.$search.'%');
                                });

                if($dataType == 'INSPECTION_RECEIVER') {
                    // $getData->whereNotIn('a.job_code', ['FO','OPC','OC']);
                }
                else if($dataType == 'INSPECTION_CHECKER') {
                    $getData->whereIn('a.job_code', ['MGR','SPV','SNM','AMG','SOF','SLP','SPV','ASV','STM','OP','OFE','STP','OR','SCC','OPE']);
                }
                else if($dataType == 'INSPECTION_CONFIRMER') {
                    $getData->whereIn('a.job_code', ['DIR','GM','MGR','SNM','AMG','SPV','ASV','STM','OP','SCC']);
                }

                $getData = $getData->orderBy('a.employee_name', 'asc');
                $total = $getData->count();

                $results = $getData->skip(($page - 1) * $perPage)
                    ->take($perPage)
                    ->get()
                    ->map(function ($row) {
                        return [
                            'id' => $row->employee_id,
                            'text' => Str::upper($row->employee_name),
                            'description1' => $row->position_name,
                            'description2' => ($row->department_name) ? 'Dept. : '.$row->department_name : null,
                        ];
                    });

                return response()->json([
                    'data' => $results,
                    'more' => ($total > $page * $perPage)
                ]);
            }
        }
        else if($request->dataForm == 'SELECTED') {
            $getData = $model->vwMasterEmployeeActive()
                            ->from('vw_master_employee_active as a')
                            ->select('a.employee_id as employeeId', 'a.employee_name as employeeName', 'a.position_name as positionName', 'a.company_id as companyId')
                            ->where('a.employee_id', '=', $request->employeeId)
                            ->first();
            return response()->json(['data' => $getData,'status' => 200], 200);
        }
        else {
            $departmentId = $request->departmentId;
            $getData = $model->vwMasterEmployeeActive()
                            ->from('vw_master_employee_active as a')
                            ->leftJoin('master_employees_multi_company as b', function($join) {
                                $join->on('b.employee_id', '=', 'a.employee_id')
                                    ->where('b.is_active', '1');
                            })
                            ->select('a.employee_id', 'a.employee_name', 'a.position_name')
                            ->distinct()
                            ->where(function($query) use ($companyId) {
                                $query->where('a.company_id', '=', $companyId)
                                    ->orWhere('b.company_id', '=', $companyId);
                            })
                            ->where(function($query) use ($search) {
                                $query->where('a.employee_name', 'like', '%'.$search.'%')
                                    ->orWhere('a.employee_id', 'like', '%'.$search.'%')
                                    ->orWhere('a.position_name', 'like', '%'.$search.'%');
                            });

            if ($dataType === 'REVIEWER') {
                // $getData->where('a.job_code', '>', 1)
                //         ->where('a.job_code', '<=', 5);

                $getData->whereIn('a.job_code', ['DIR','GM','MGR','SPV','SNM','AMG','SOF','SLP','OL']);

            }
            else if ($dataType === 'APPROVER') {
                // $getData->where('a.job_code', '<=', 5);
                $getData->whereIn('a.job_code', ['DIR','GM','MGR','SNM','AMG','SPV']);
            }
            else if($dataType === 'ALL_EMPLOYEE') {
                $dataEmployeeId = $request->dataEmployeeId;
                if ($departmentId != null) {
                    $getData->where('a.department_id', '=', $departmentId);
                }

                if ($dataEmployeeId != null && $dataEmployeeId != 'ALL') {
                    $getData->where('a.employee_id', '=', $dataEmployeeId);
                }
            }

            $getData = $getData->orderBy('a.employee_name', 'asc')->get();

            $results = $getData->map(function ($row) {
                return [
                    'id' => $row->employee_id,
                    'text' => Str::upper($row->employee_name)
                ];
            });

            return response()->json($results, 200);
        }
    }

