                            'inspectionRemarks' => empty($request->inspectionRemarks) ? '' : EscapeHelper::unescapeInput($request->inspectionRemarks),
                            'itemForm' => $arrItem,
                            'filePath' => $pathDetail,
                            'filename' => $formFilename,
                            'checklist' => $dataChecklist,
                            'signer' => $arrSigner,
                        ]);

                        $requestData = new Request();
                        $requestData->replace([
                                                'documentType' => '4',
                                                'dataForm' => compact('dataForm'),
                                            ]);
                        $this->generatePdf($requestData);

                        $docApprovalId = $docApprovalIdInspection;
                        $submittedStatus = true;
                    }
                    else {
                        return response()->json(['message' => 'PO Form not found.', 'errors' => $errorItem], 404)
                                ->setStatusCode(404, 'PO Form not found.');
                    }
                }
            }
            else if($request->documentType === '7' || $request->documentType === '8' || $request->documentType === '9'){
                $companyId = $this->companyId;
                if($request->documentType === '7') {
                    $validatedData = $request->validate([
                        'documentType' => 'required|int',
                        'departmentOrder' => 'required|string|max:255',
                        // 'reviewer.*' => 'required|string|max:255',
                        'approver.*' => 'required|string|max:255',
                        'documentTitle' => 'required|string|max:255',
                        'attachmentFileDocument.*' => 'required|file|max:5120|mimetypes:application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document', // 5MB per file
                    ], [
                        'documentType.required' => 'Document type is required',
                        'departmentOrder.required' => 'Department is required',
                        // 'reviewer.*.required' => 'Reviewer is required',
                        'approver.*.required' => 'Approver is required',
                        'documentTitle.required' => 'Document title is required',
                        'attachmentFileDocument.*.required' => 'Document to approve file is required',
                        'attachmentFileDocument.*.mimetypes' => 'Document must be a PDF or Word.',
                        'attachmentFileDocument.*.max' => 'Document may not be greater than 5 MB.',
                    ]);
                }
                else if($request->documentType === '8' || $request->documentType === '9') {
                    $validatedData = $request->validate([
                        'documentType' => 'required|int',
                        'departmentOrder' => 'required|string|max:255',
                        // 'reviewer.*' => 'required|string|max:255',
                        'approver.*' => 'required|string|max:255',
                        // 'documentTitle' => 'required|string|max:255',
                        'attachmentFileDocument.*' => 'required|file|max:5120|mimetypes:application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', // 5MB per file
                    ], [
                        'documentType.required' => 'Document type is required',
                        'departmentOrder.required' => 'Department is required',
                        // 'reviewer.*.required' => 'Reviewer is required',
                        'approver.*.required' => 'Approver is required',
                        // 'documentTitle.required' => 'Document title is required',
                        'attachmentFileDocument.*.required' => 'Document to approve file is required',
                        'attachmentFileDocument.*.mimetypes' => 'Document must be a Excel file',
                        'attachmentFileDocument.*.max' => 'Document may not be greater than 5 MB.',
                    ]);
                }

                $myData = $model->vwMasterEmployeeActive()->select('*')
                        ->where('company_id', '=', $companyId)
                        ->where('employee_id', '=', $employeeId)
                        ->first();

                $documentTypeId = $request->documentType;
                $getDocumentType = $model->masterDocumentTypes()->select('doc_type_id', 'doc_name')
                                        ->where('doc_type_id', '=', $documentTypeId)
                                        ->first();
                if($getDocumentType) {
                    $year = date('Y');
                    $dateTime = Carbon::now()->format('Y-m-d H:i:s');

                    $departmentName = null;
                    if($request->departmentOrder){
                        $requestData = new Request();
                        $requestData->merge(['companyId' => $companyId, 'departmentId' => $request->departmentOrder]);
                        $getDepartment = $this->getDepartment($requestData);
                        $departmentName = $getDepartment->departmentName;
                    }

                    $dataInsert = [
                        'employee_id' => $employeeId,
                        'company_id' => $companyId,
                        'doc_type_id' => $documentTypeId,
                        'doc_name' => $getDocumentType->doc_name,
                        'year' => $year,
                        'seq_id' => $seqId,
                        'doc_number' => $documentNumber,
                        'doc_status_id' => '2',
                        'form_status_id' => '2',
                        'department_id' => $request->input('departmentOrder', null),
                        'department_name' => $departmentName,
                        'location_id' => $request->locationOrder,
                    ];
                    $insertHeader = $model->documentApprovalHeader()->create($dataInsert);
                    $docApprovalId = $insertHeader->id;
                    $arrNotifications[$docApprovalId] = array();

                    // $folderName = $departmentName.'_'.$seqNumber;
                    $documentName = str_replace(' ', '_', strtolower($getDocumentType->doc_name));
                    $documentName = str_replace('&', '_', strtolower($documentName));
                    $docVersion = 1;
                    $mainDirectory = "private/doc_approval";
                    $pathDetail = "/{$year}/other_document/{$employeeId}/";
                    $formFilename = $documentName.'_'.$employeeId.'_'.$docVersion.'_'.uniqid();
                    $dataInsert = [
                        'doc_approval_id' => $docApprovalId,
                        'company_id' => $companyId,
                        'year' => $year,
                        'doc_version' => $docVersion,
                        'doc_type_id' => $request->documentType,
                        'document_status' => '2',
                        'department_id' => $request->input('departmentOrder', null),
                        'document_title' => $request->documentType === '7' ? $request->documentTitle : $getDocumentType->doc_name,
                        // 'document_description' => $request->documentDescription,
                        'created_by' => $employeeId,
                        'created_at' => $dateTime,
                        'path_detail' => $pathDetail,
                        'filename' => $formFilename,
                    ];
                    $insertDetail = $model->docApprovalOther()->create($dataInsert);
                    $referenceId = $insertDetail->id;

                    $transactionStatusId = '2'; // 2 = SUBMITTED
                    $arrSigner = [];
                    $dataInsert = [
                        'company_id' => $companyId,
                        'employee_id' => $employeeId,
                        'flow_as' => 'APPLICANT',
                        'status' => $transactionStatusId,
                        'doc_approval_id' => $docApprovalId,
                        'doc_type_id' => $documentTypeId,
                        'reference_id' => $referenceId,
                        'received_at' => $dateTime,
                        'decision_at' => $dateTime,
                    ];
                    $insertFlowSign = $model->docApprovalFlowSign()->create($dataInsert);
                    $arrSigner[] = [
                        'signerId' => $insertFlowSign->id,
                        'employeeName' => Str::upper($myData->employee_name),
                        'company_id' => $companyId,
                        'flowAs' => 'APPLICANT',
                        'receivedAt' => Carbon::parse($dateTime)->format('d-M-Y'),
                        'statusName' => 'SUBMITTED',
                        'decisionAt' => Carbon::parse($dateTime)->format('d-M-Y'),
                        'decisionAtTime' => Carbon::parse($dateTime)->format('d-M-Y H:i:s'),
                    ];

                    $reviewerFlow = 'SEQUENCE'; // SEQUENCE OR PARALEL
                    $approverFlow = 'SEQUENCE'; // SEQUENCE OR PARALEL

                    $arrReviewerAsApprover = array();
                    for($x = 0; $x < count($request->reviewer); $x++) {
                        $checkerStatus = $receivedDatetime = null;
                        if($transactionStatusId == '2') { // 2 = SUBMITTED
                            $checkerStatus = '13'; // 13 = PENDING
                            if($reviewerFlow == 'SEQUENCE') {
                                if($x == 0) {
                                    $checkerStatus = '3'; // 3 = RECEIVED
                                    $receivedDatetime = $dateTime;
                                }
                            }
                            else {
                                $checkerStatus = '3'; // 3 = RECEIVED
                                $receivedDatetime = $dateTime;
                            }
                        }

                        $dataInsert = [
                            'employee_id' => $request->reviewer[$x],
                            'company_id' => $companyId,
                            'flow_as' => 'REVIEWER',
                            'status' => $checkerStatus,
                            'doc_approval_id' => $docApprovalId,
                            'doc_type_id' => $documentTypeId,
                            'reference_id' => $referenceId,
                            'received_at' => $receivedDatetime,
                        ];
                        $insertFlowSign = $model->docApprovalFlowSign()->create($dataInsert);

                        $getEmployee = $model->vwMasterEmployeeActive()->select('employee_name')
                                        ->where('employee_id', $request->reviewer[$x])
                                        ->first();
                        $arrSigner[] = [
                                            'signerId' => $insertFlowSign->id,
                                            'employeeName' => Str::upper($getEmployee->employee_name),
                                            'flowAs' => 'REVIEWER',
                                            'receivedAt' => ($receivedDatetime != null) ? Carbon::parse($dateTime)->format('d-M-Y') : '',
                                            'statusName' => ($checkerStatus == '3') ? 'RECEIVED' : 'PENDING',
                                            'decisionAt' => '',
                                            'decisionAtTime' => '',
                                        ];

                        if(!in_array($request->reviewer[$x], $request->approver) && $checkerStatus == '3') {
                            $arrNotifications[$docApprovalId][] = [
                                                                    'docApprovalId' => $docApprovalId,
                                                                    'referenceId' => $referenceId,
                                                                    'signFlowId' => $insertFlowSign->id,
                                                                    'companyId' => $companyId,
                                                                    'employeeId' => $request->reviewer[$x],
                                                                    'flowAs' => 'REVIEWER',
                                                                    'notification' => 'NEED_APPROVAL'
                                                                ];
                        }
                    }

                    for($x = 0; $x < count($request->approver); $x++) {
                        $approverStatus = $receivedDatetime = null;
                        if($transactionStatusId == '2') { // 2 = SUBMITTED
                            if(count($request->reviewer) == 1 && in_array($request->approver[$x], $request->reviewer)) {
                                // REVIEWER ONLY 1 AND REVIEWER ALSO AS APPROVER
                                $approverStatus = '3'; // 3 = RECEIVED
                                $receivedDatetime = $dateTime;
                            }
                            else if(count($request->reviewer) >= 1) {
                                $approverStatus = '13'; // 13 = PENDING
                            }
                            else if($approverFlow == 'SEQUENCE') {
                                if($x == 0) {
                                    $approverStatus = '3'; // 3 = RECEIVED
                                    $receivedDatetime = $dateTime;
                                }
                                else {
                                    $approverStatus = '13'; // 13 = PENDING
                                }
                            }
                            else {
                                $approverStatus = '3'; // 3 = RECEIVED
                                $receivedDatetime = $dateTime;
                            }
                        }

                        $dataInsert = [
                            'employee_id' => $request->approver[$x],
                            'company_id' => $companyId,
                            'flow_as' => 'APPROVER',
                            'status' => $approverStatus,
                            'received_at' => $receivedDatetime,
                            'doc_approval_id' => $docApprovalId,
                            'doc_type_id' => $documentTypeId,
                            'reference_id' => $referenceId,
                        ];
                        $insertFlowSign = $model->docApprovalFlowSign()->create($dataInsert);

                        $getEmployee = $model->vwMasterEmployeeActive()->select('employee_name')
                                        ->where('employee_id', $request->approver[$x])
                                        ->first();

                        if($approverStatus == '3') {
                            $arrNotifications[$docApprovalId][] = [
                                                                    'signerId' => $insertFlowSign->id,
                                                                    'docApprovalId' => $docApprovalId,
                                                                    'referenceId' => $referenceId,
                                                                    'signFlowId' => $insertFlowSign->id,
                                                                    'companyId' => $companyId,
                                                                    'employeeId' => $request->approver[$x],
                                                                    'flowAs' => 'APPROVER',
                                                                    'notification' => 'NEED_APPROVAL'
                                                                ];
                        }

                        $arrSigner[] = [
                            'employeeName' => Str::upper($getEmployee->employee_name),
                            'flowAs' => 'APPROVER',
                            'receivedAt' => ($receivedDatetime != null) ? Carbon::parse($dateTime)->format('d-M-Y') : '',
                            'statusName' => ($approverStatus == '3') ? 'RECEIVED' : 'PENDING',
                            'decisionAt' => '',
                            'decisionAtTime' => '',
                        ];
                    }

                    if ($request->hasFile('attachmentFileDocument')) {
                        foreach ($request->file('attachmentFileDocument') as $file) {
                            // $mimeType = $file->getMimeType();
                            $filenameOriginal = DecodeModSecurityPlaceholders::decodeFilenameStatic($file->getClientOriginalName());
                            $mimeType = $this->getMimeTypeByExtension($filenameOriginal);

                            // $filenameOriginal = $file->decodedFilename ?? $file->getClientOriginalName();
                            // $filenameOriginal = $file->getClientOriginalName();

                            // $filenameOriginal = preg_replace('/[^a-zA-Z0-9_\-\. \p{Hiragana}\p{Katakana}\p{Han}]/u', '_', $filenameOriginal);
                            // $filenameOriginal = substr($filenameOriginal, 0, 100);

                            $filename = $formFilename.'.'.$file->getClientOriginalExtension();
                            $file->storeAs($mainDirectory.$pathDetail, $filename, 'local');

                            $converted = str_contains($mimeType, 'pdf') ? null : 0;
                            // if (str_contains($mimeType, 'excel') || str_contains($mimeType, 'spreadsheetml') || str_contains($mimeType, 'wordprocessingml')) {
                            //     $converted = '0';
                            // }

                            $dataInsert = [
                                'doc_approval_id' => $docApprovalId,
                                'company_id' => $companyId,
                                'doc_type_id' => $request->documentType,
                                'reference_id' => $referenceId,
                                'path_detail' => $pathDetail,
                                'filename' => $filename,
                                'filename_original' => $filenameOriginal,
                                'converted' => $converted,
                                'mime_type' => $mimeType,
                                'downloadable' => '1',
                            ];
                            $insertAttachment = $model->docApprovalAttachment()->create($dataInsert);

                            // if (str_contains($mimeType, 'excel') || str_contains($mimeType, 'spreadsheetml') || str_contains($mimeType, 'wordprocessingml')) {
                            //     ConvertFileJob::dispatch($insertAttachment->id);
                            // }
                            if (!str_contains($mimeType, 'pdf')) {
                                ConvertFileJob::dispatch($insertAttachment->id);
                            }
                        }
                    }

                    if ($request->hasFile('attachmentFile')) {
                        foreach ($request->file('attachmentFile') as $file) {
                            // $mimeType = $file->getMimeType();
                            $filenameOriginal = DecodeModSecurityPlaceholders::decodeFilenameStatic($file->getClientOriginalName());
                            $mimeType = $this->getMimeTypeByExtension($filenameOriginal);
                            // $filenameOriginal = $file->decodedFilename ?? $file->getClientOriginalName();
                            // $filenameOriginal = $file->getClientOriginalName();

                            // $filenameOriginal = preg_replace('/[^a-zA-Z0-9_\-\. \p{Hiragana}\p{Katakana}\p{Han}]/u', '_', $filenameOriginal);
                            // $filenameOriginal = substr($filenameOriginal, 0, 100);

                            $filename = $documentName.'_'.$employeeId.'_'.$docVersion.'_attachment_'.uniqid().'.'.$file->getClientOriginalExtension();
                            $file->storeAs($mainDirectory.$pathDetail, $filename, 'local');

                            $converted = str_contains($mimeType, 'pdf') ? null : 0;
                            // if (str_contains($mimeType, 'excel') || str_contains($mimeType, 'spreadsheetml') || str_contains($mimeType, 'wordprocessingml')) {
                            //     $converted = '0';
                            // }

                            $dataInsert = [
                                'doc_approval_id' => $docApprovalId,
                                'company_id' => $companyId,
                                'doc_type_id' => $request->documentType,
                                'reference_id' => $referenceId,
                                'path_detail' => $pathDetail,
                                'filename' => $filename,
                                'filename_original' => $filenameOriginal,
                                'converted' => $converted,
                                'mime_type' => $mimeType,
                                'downloadable' => '1',
                            ];
                            $insertAttachment = $model->docApprovalAttachment()->create($dataInsert);

                            // if (str_contains($mimeType, 'excel') || str_contains($mimeType, 'spreadsheetml') || str_contains($mimeType, 'wordprocessingml')) {
                            //     ConvertFileJob::dispatch($insertAttachment->id);
                            // }
                            if (!str_contains($mimeType, 'pdf')) {
                                ConvertFileJob::dispatch($insertAttachment->id);
                            }
                        }
                    }

                    $submittedStatus = true;

                }
                else {
                    return response()->json(['message' => 'Document type not found.'], 422)
                                    ->setStatusCode(422, 'Document type not found.');
                }
            }

            if($submittedStatus) {
                // CHECK ARRAY NOTIFICATIONS
                if (count($arrNotifications[$docApprovalId]) > 0) {
                    $requestData = new Request();
                    $requestData->merge(['notifications' => $arrNotifications]);
                    $this->sendEmail($requestData);
                }

                if($request->actionType == 'DRAFT'){
                    $message = 'Successfully Save to Draft'; // 1 = DRAFT
                }
                else if($request->actionType == 'SUBMIT'){
                    $message = 'Successfully Submitted Form'; // 1 = DRAFT
                }

                return response()->json(['message' => $message], 200);
            }
            else {
                return response()->json(['message' => 'Failed to submitted data'], 202)
                                ->setStatusCode(202, 'Failed to submitted data');
            }
        }
        catch (ValidationException $e) {
            return response()->json(['message' => 'Please fill the required form.', 'errors' => $e->errors()], 422)
                            ->setStatusCode(422, 'Please fill the required form.');
        }
    }

    public function ongoing(Request $request) {
        $token = $request->token;
        $docApprovalId = null;
        if(!empty($token)) {
            $decodeToken = SafeToken::decode($token);
            $employeeId = $decodeToken['id'];
            // $companyId = (array_key_exists('cid', $decodeToken)) ? $decodeToken['cid'] : '1';
            $docApprovalId = $decodeToken['a'];
            $referenceId = $decodeToken['b'];
        }
        else {
            $employeeId = $this->employeeId;
            $companyId = $this->companyId;
        }

        $response = [];

        $requestTypeAll = $request->requestTypeAll;
        $company = $request->company;
        $requestType = $request->requestType;
        if((empty($requestTypeAll) && empty($requestType)) || empty($company)){
            return response()->json([
                'status' => 404,
                'message' => 'No item to view',
                'data' => $response,
                'hasMorePages' => null,
            ], 200);
        }

        $model = new DocumentApprovalModel();
        $type = $request->type;
        $perPage = 10; // Number of items per page
        $currentPage = $request->input('page', 1);
        $search = $request->input('search', '');
        $viewForm = false;
        $rowId = null;
        if($type == 'MY_REQUEST') {
            $dateLabel = 'Submitted';
        }
        else{
            $dateLabel = 'Received';
        }

        if($docApprovalId != null) {
            // GET FORM EXSITING, AMBIL FORM EXISTING DAHULU SESUAI TOKEN, TARUH PALING ATAS
            $getHeader = $model->documentApprovalHeader()
                                ->from('doc_approval_header AS a')
                                ->leftJoin(DB::raw('(SELECT doc_approval_id, employee_id, sign_flow_id, flow_as, received_at, status FROM doc_approval_flow_sign
                                                    WHERE doc_approval_id = "' . $docApprovalId . '"
                                                    AND employee_id = "' . $employeeId . '"
                                                    ORDER BY sign_flow_id DESC
                                                    LIMIT 1) as b'), function($join) {
                                    $join->on('b.doc_approval_id', '=', 'a.doc_approval_id');
                                })
                                ->leftJoin('vw_master_employee_all as c', 'c.employee_id', 'a.employee_id')
                                ->leftJoin('master_company as d', 'd.company_id', 'a.company_id')
                                ->select('a.doc_number', 'b.employee_id', 'a.doc_approval_id', 'a.doc_type_id', 'a.doc_name', 'a.department_name', 'b.sign_flow_id', 'b.received_at', 'b.status', 'c.employee_name', 'c.avatar', 'a.company_id', 'd.company_name', 'a.priority', 'a.priority_name')
                                ->where('a.doc_approval_id', $docApprovalId);

            if($company[0] !== 'ALL') {
                $getHeader = $getHeader->whereIn('a.company_id', $company);
            }

            if (!empty($search)) {
                $getHeader = $getHeader->where(function($query) use ($search) {
                                    $query->where('c.employee_name', 'like', $search.'%')
                                        ->orWhere('a.doc_number', 'like', $search.'%')
                                        ->orWhere('a.department_name', 'like', $search.'%');
                                });
            }

            $getHeader = $getHeader->whereIn('b.flow_as', ['CHECKER_1', 'CHECKER_2', 'CONFIRMER_1', 'REVIEW_ADMIN', 'CONFIRMER_2', 'ACKNOWLEDGER', 'APPROVER', 'RECEIVER'])
                                ->where('a.is_active', '1')
                                ->first();
            if($getHeader) {
                if ($getHeader->doc_type_id == '1') { // ORDER FORM
                    $getForm = $model->documentApprovalDetailOrder()
                                    ->from('doc_approval_detail_order_form as a')
                                    ->leftJoin('doc_approval_detail_order_form_purpose as b', 'b.order_form_id', 'a.order_form_id')
                                    ->where('a.doc_approval_id', '=', $getHeader->doc_approval_id)
                                    ->where('a.is_active', '1')
                                    ->select('a.order_form_id', 'a.order_form_status', 'a.order_form_number', 'a.all_items', 'a.grand_total', 'a.currency_code', 'b.description')
                                    ->orderBy('a.order_form_id', 'desc')
                                    ->first();

                    if ($getForm) {
                        $token = ['cid' => $getHeader->company_id, 'id' => $getHeader->employee_id,'a' => $getHeader->doc_approval_id,'b' => $getForm->order_form_id,'c' => null,'d'=> $getHeader->sign_flow_id];
                        $encodedToken = SafeToken::encode($token);

                        $allItems = '';
                        if($getForm->all_items != null){
                            $allItemsArray = explode('## ', $getForm->all_items);
                            if (count($allItemsArray) === 1) {
                                $allItems = '<li>'.$getForm->all_items.'</li>';
                            }
                            else {
                                foreach ($allItemsArray as $index => $value) {
                                    if($index + 1 == 6) {
                                        $allItems .= '<li>... and others</li>';
                                        break;
                                    }
                                    else {
                                        $allItems .= '<li>'.($index + 1).'. '.$value.'</li>';
                                    }
                                }
                            }
                        }

                        $formStatus = $bgClassName = '';
                        if($getForm->order_form_status == '2') { // 2 = SUBMITTED
                            if($getHeader->status == '8') { // 8 = APPROVED
                                $formStatus = '<span class="badge bg-info fs-9 fw-semibold">PARTIAL APPROVED</span>';
                            }
                        }
                        else if($getForm->order_form_status == '5') { // 5 = NEED REVISION
                            $formStatus = '<span class="badge bg-secondary fs-9 fw-semibold">SEND BACK TO REVISE</span>';
                        }
                        else if($getForm->order_form_status == '8') { // 8 = APPROVED
                            $formStatus = '<span class="badge bg-success fs-9 fw-semibold">ORDER FORM APPROVED</span>';
                        }
                        else if($getForm->order_form_status == '9') { // 9 = REJECTED
                            $formStatus = '<span class="badge bg-danger fs-9 fw-semibold">FULLY REJECTED</span>';
                        }
                        $formStatus = $formStatus != '' ? '<div class="float-end badge-status">'.$formStatus.'</div>' : '';

                        if($type == 'MY_APPROVAL' && ($getHeader->priority == '1' || $getHeader->priority == '2')) { // 1 = TOP URGENT, 2= URGENT
                            $formStatus = '<div class="float-end badge-status">
                                                <span class="badge bg-danger fs-9 fw-semibold badge-priority">'.$getHeader->priority_name.'</span>
                                            </div>';
                            $bgClassName = ' bg-urgent';
                        }

                        $avatar = '<div class="d-flex align-items-center">
                                        <div class="avatar avatar-xs d-flex align-items-center me-1">
                                            <img class="avatar-img" src="'.asset('storage/avatars/'.$getHeader->avatar).'" alt="">
                                        </div>
                                        <span class="avatar-name-card fs-8 fw-medium">'.Str::upper($getHeader->employee_name).'</span>
                                    </div>';
                        $bottomCard = '<div class="d-flex justify-content-between align-items-center">
                                            '.$avatar.'
                                            <div class="text-end">
                                                <small class="text-muted text-nowrap">'.$dateLabel.' '.$this->timeAgo($getHeader->received_at, false).'</small>
                                            </div>
                                        </div>';

                        $uniqId = uniqid();
                        $viewForm = true;
                        $uniqIdView = $uniqId;
                        $grandTotal = $this->formatNumber($getForm->grand_total) > 0 ? $this->formatNumber($getForm->grand_total) : '--';
                        $response[] = [
                            'html' => '<div class="card card-link-content mb-2-2'.$bgClassName.' active" id="'.$uniqId.'" data-token="'.$encodedToken.'" data-row="'.$uniqId.'">
                                        <div class="card-header p-2-2 pb-0">
                                            <div class="card-title m-0 fs-7">'.$getHeader->doc_name.'
                                                '.$formStatus.'
                                            </div>
                                        </div>
                                        <div class="card-body p-2-2 pt-0">
                                            <div class="mb-2 pt-1 data-details">
