                            $formStatus = '<div class="float-end badge-status">
                                                <span class="badge bg-danger fs-9 fw-semibold badge-priority">'.$rowFlowSign->priority_name.'</span>
                                            </div>';
                            $bgClassName = ' bg-urgent';
                        }

                        $avatar = '<div class="d-flex align-items-center">
                                        <div class="avatar avatar-xs d-flex align-items-center me-1">
                                            <img class="avatar-img" src="'.asset('storage/avatars/'.$rowFlowSign->avatar).'" alt="">
                                        </div>
                                        <span class="avatar-name-card fs-8 fw-medium">'.Str::upper($rowFlowSign->employee_name).'</span>
                                    </div>';
                        $bottomCard = '<div class="d-flex justify-content-between align-items-center">
                                            '.$avatar.'
                                            <div class="text-end">
                                                <small class="text-muted text-nowrap">'.$dateLabel.' '.$this->timeAgo($rowFlowSign->received_at, false).'</small>
                                            </div>
