                    $uniqId = uniqid();
                    $response[] = [
                        'html' => '<div class="card card-link-content mb-2-2'.$bgClassName.'" id="'.$uniqId.'" data-token="'.$encodedToken.'" data-form="APPLICATION_FORM" data-row="'.$uniqId.'" data-type="'.$type.'">
                                    <div class="card-header p-2-2 pb-0">
                                        <div class="card-title m-0 fs-7">'.$rowFlowSign->doc_name.$formStatus.'</div>
                                    </div>
                                    <div class="card-body p-2-2 pt-0">
                                        <div class="mb-2 pt-1 data-details">
                                            <div class="data-row">
                                                <span class="data-label">Company</span>
                                                <span class="data-separator">:</span>
                                                <span class="data-value">'.$getForm->company_name.'</span>
                                            </div>
                                            <div class="data-row">
                                                <span class="data-label">Department</span>
                                                <span class="data-separator">:</span>
                                                <span class="data-value">'.$rowFlowSign->department_name.'</span>
                                            </div>
                                            <div class="data-row">
                                                <span class="data-label">PO Number</span>
                                                <span class="data-separator">:</span>
                                                <span class="data-value">'.$getForm->po_number.'</span>
                                            </div>
                                            <div class="data-row">
                                                <span class="data-label">Vendor</span>
                                                <span class="data-separator">:</span>
                                                <span class="data-value">'.$getForm->vendor_name.'</span>
                                            </div>
                                            <div class="data-row">
                                                <span class="data-label">Items</span>
                                                <span class="data-separator">:</span>
