        return response()->json([
            'status' => 200,
            'message' => 'Success',
            'ongoing' => $countOngoing,
            'data' => $response,
            'viewForm' => $viewForm,
            'rowId' => $rowId,
            'hasMorePages' => $getFlowSign->hasMorePages() // Indicate if there are more pages to load
        ], 200);
    }

    public function documentHistory(Request $request) {
        $companyId = $request->company;
        $employeeId = $this->employeeId;

        $status = $request->input('status', 'ALL');
        $submittedStartDate = $request->input('submittedStartDate', '');
        $submittedEndDate = $request->input('submittedEndDate', '');
        $completedStartDate = $request->input('completedStartDate', '');
        $completedEndDate = $request->input('completedEndDate', '');
        $sortBy = $request->input('sortBy', 'LATEST');
        $type = $request->input('type');

        $model = new DocumentApprovalModel();
        $subquery = DB::table('doc_approval_flow_sign as a')
            ->leftJoin('doc_approval_header as b', 'b.doc_approval_id', '=', 'a.doc_approval_id');
        if($type == 'APPROVAL_HISTORY') {
            $subquery = $subquery->leftJoin('vw_master_employee_all as d', 'b.employee_id', '=', 'd.employee_id')
                                ->select([
                                    'a.sign_flow_id',
                                    'a.doc_approval_id',
                                    'a.doc_type_id',
                                    'b.doc_name',
                                    'a.reference_id',
                                    'a.reference_group_id',
                                    'a.company_id',
                                    'a.employee_id',
                                    'a.flow_as',
                                    'a.status',
                                    'a.received_at',
                                    'a.decision_at',
                                    'a.is_active',
                                    'b.doc_number',
                                    'b.doc_status_id',
                                    'b.department_name',
                                    'b.company_name',
                                    'b.priority',
                                    'b.priority_name',
                                    'd.employee_name',
                                    DB::raw('ROW_NUMBER() OVER (PARTITION BY a.employee_id, a.doc_approval_id ORDER BY a.sign_flow_id DESC) AS row_num'),
                                ]);
        }
        else {
            $subquery = $subquery->select([
                                    'a.sign_flow_id',
                                    'a.doc_approval_id',
                                    'a.doc_type_id',
                                    'b.doc_name',
                                    'a.reference_id',
                                    'a.reference_group_id',
                                    'a.company_id',
                                    'a.employee_id',
                                    'a.flow_as',
                                    'a.status',
                                    'a.received_at',
                                    'a.decision_at',
                                    'a.is_active',
                                    'b.doc_number',
                                    'b.doc_status_id',
                                    'b.department_name',
                                    'b.company_name',
                                    'b.priority',
                                    'b.priority_name',
                                    DB::raw('ROW_NUMBER() OVER (PARTITION BY a.employee_id, a.doc_approval_id ORDER BY a.sign_flow_id DESC) AS row_num'),
                                ]);
        }

        $subquery = $subquery->where('a.employee_id', $employeeId)
                            ->where('a.is_active', '1')
                            ->where('b.is_active', '1');

        if($type == 'REQUEST_HISTORY') {
            $subquery = $subquery->whereNotIn('a.doc_type_id', ['2']) // 2 = APPLICATION FORM => HISTORY ADA DI MENU PURCHASING
                                ->where('a.flow_as', 'APPLICANT')
                                ->whereNot('b.doc_status_id', '2');
        }
        else if($type == 'APPROVAL_HISTORY') {
            $subquery = $subquery->whereIn('a.status', ['14','8','9']) // 14 = SEND_BACK, 8 = APPROVED, 9 = REJECTED
                                ->whereNotIn('a.flow_as', ['APPLICANT','RECEIVER']);
        }

        if($companyId != 'ALL') {
            $subquery = $subquery->where('a.company_id', $companyId);
        }

        if($status != 'ALL') {
            $subquery = $subquery->where('b.doc_status_id', $status);
        }

        if($submittedStartDate != '' && $submittedEndDate != '') {
            $submittedStartDate = Carbon::parse($submittedStartDate)->format('Y-m-d');
            $submittedEndDate = Carbon::parse($submittedEndDate)->format('Y-m-d');
            $subquery = $subquery->whereDate('b.submitted_at', '>=', $submittedStartDate)
                                ->whereDate('b.submitted_at', '<=', $submittedEndDate);
        }

        if($completedStartDate != '' && $completedEndDate != '') {
            $completedStartDate = Carbon::parse($completedStartDate)->format('Y-m-d');
            $completedEndDate = Carbon::parse($completedEndDate)->format('Y-m-d');
            $subquery = $subquery->whereDate('b.final_decision_at', '>=', $completedStartDate)
                                ->whereDate('b.final_decision_at', '<=', $completedEndDate);
        }

        if ($request->filled('search')) {
            $search = Str::squish($request->input('search'));
            // TEMPORARY ONLY ORDER FORM
            $subquery = $subquery->leftJoin('doc_approval_detail_order_form_item as e', function($join) {
                                    $join->on('e.doc_approval_id', '=', 'a.doc_approval_id')
                                        ->on('e.order_form_id', '=', 'a.reference_id')
                                        ->where('b.is_active', '1');
                                });
            // END TEMPORARY ONLY ORDER FORM
            $subquery = $subquery->where(function($q) use ($search, $type) {
                            $q->where('b.department_name', 'LIKE', "%{$search}%")
                                ->orWhere('b.doc_number', 'LIKE', "%{$search}%")
                                ->orWhere('e.appliance_item', 'LIKE', "%{$search}%");

                            if($type == 'APPROVAL_HISTORY') {
                                $q = $q->orWhere('d.employee_name', 'LIKE', "%{$search}%");
                            }
                        });
        }

        $sub = clone $subquery;
        $query = DB::table(DB::raw("({$subquery->toSql()}) as rankedflows"))
                    ->mergeBindings($sub);
        if($type == 'APPROVAL_HISTORY') {
            $query =  $query->select([
                        'rankedflows.sign_flow_id',
                        'rankedflows.doc_approval_id',
                        'rankedflows.doc_type_id',
                        'rankedflows.doc_name as docName',
                        'rankedflows.reference_id',
                        'rankedflows.reference_group_id',
                        'rankedflows.company_id',
                        'rankedflows.employee_id',
                        'rankedflows.flow_as',
                        'rankedflows.status',
                        'rankedflows.received_at',
                        'rankedflows.decision_at',
                        'rankedflows.is_active',
                        'rankedflows.doc_number as docNo',
                        'rankedflows.doc_status_id',
                        'rankedflows.department_name as deptName',
                        'rankedflows.company_name as companyName',
                        'rankedflows.priority as priority_id',
                        'rankedflows.priority_name as priority',
                        'rankedflows.employee_name as employeeName',
                        'rankedflows.row_num',
                    ]);
        }
        else {
                $query =  $query->select([
                        'rankedflows.sign_flow_id',
                        'rankedflows.doc_approval_id',
                        'rankedflows.doc_type_id',
                        'rankedflows.doc_name as docName',
                        'rankedflows.reference_id',
                        'rankedflows.reference_group_id',
                        'rankedflows.company_id',
                        'rankedflows.employee_id',
                        'rankedflows.flow_as',
                        'rankedflows.status',
                        'rankedflows.received_at',
                        'rankedflows.decision_at',
                        'rankedflows.is_active',
                        'rankedflows.doc_number as docNo',
                        'rankedflows.doc_status_id',
                        'rankedflows.department_name as deptName',
                        'rankedflows.company_name as companyName',
                        'rankedflows.priority as priority_id',
                        'rankedflows.priority_name as priority',
                        'rankedflows.row_num',
                    ]);
        }

        $query = $query->where('rankedflows.row_num', 1);

        if($sortBy == 'LATEST') {
            $query = $query->latest('rankedflows.decision_at');
        }
        else if($sortBy == 'OLDEST') {
            $query = $query->oldest('rankedflows.decision_at');
        }
        else if($sortBy == 'LEVEL_PRIORITY') {
            $query = $query->orderBy('rankedflows.priority_id', 'asc')
                        ->oldest('rankedflows.decision_at');
        }

        return DataTables::of($query)
            ->addIndexColumn()
            ->addColumn('items', function($row) use ($model) {
                $allItems = '';
                if($row->doc_type_id == '1') {
                    $getDetails = $model->documentApprovalDetailOrderItem()
                                        ->from('doc_approval_detail_order_form_item as a')
                                        ->select('a.appliance_item')
                                        ->where('a.doc_approval_id', '=', $row->doc_approval_id)
                                        ->where('a.order_form_id', '=', $row->reference_id)
                                        ->where('a.company_id', '=', $row->company_id)
                                        ->where('a.is_active', '1')
                                        ->oldest('a.order_detail_id', 'desc')
                                        ->get();
                    if (count($getDetails) === 1) {
                        $allItems = $getDetails[0]->appliance_item;
                    }
                    else {
                        foreach ($getDetails as $index => $rowDetail) {
                            if($index + 1 == 6) {
                                $allItems .= "\n... and others";
                                break;
                            }
                            else {
                                $allItems .= $index > 0 ? "\n".($index + 1).'. '.$rowDetail->appliance_item : ($index + 1).'. '.$rowDetail->appliance_item;
                            }
                        }
                    }
                }
                else if($row->doc_type_id == '2') {
                    $getDetails = $model->documentApprovalDetailOrderItem()
                                        ->from('doc_approval_order_application_item as a')
                                        ->select('a.appliance_item')
                                        ->where('a.application_id', '=', $row->reference_id)
                                        ->where('a.company_id', '=', $row->company_id)
                                        ->whereNotNull('a.order_detail_id')
                                        ->where('a.is_active', '1')
                                        ->oldest('a.application_item_id')
                                        ->get();
                    if (count($getDetails) === 1) {
                        $allItems = $getDetails[0]->appliance_item;
                    }
                    else {
                        foreach ($getDetails as $index => $rowDetail) {
                            if($index + 1 == 6) {
                                $allItems .= "\n... and others";
                                break;
                            }
                            else {
                                $allItems .= $index > 0 ? "\n".($index + 1).'. '.$rowDetail->appliance_item : ($index + 1).'. '.$rowDetail->appliance_item;
                            }
                        }
                    }
                }
                else if($row->doc_type_id == '4') {
                    $getDetails = $model->docApprovalOrderInspectionItem()
                                        ->from('doc_approval_order_inspection_item as a')
                                        ->select('a.appliance_item')
                                        ->where('a.inspection_id', '=', $row->reference_id)
                                        ->where('a.company_id', '=', $row->company_id)
                                        ->where('a.is_active', '1')
                                        ->oldest('a.inspection_item_id')
                                        ->get();
                    if (count($getDetails) === 1) {
                        $allItems = $getDetails[0]->appliance_item;
                    }
                    else {
                        foreach ($getDetails as $index => $rowDetail) {
                            if($index + 1 == 6) {
                                $allItems .= "\n... and others";
                                break;
                            }
                            else {
                                $allItems .= $index > 0 ? "\n".($index + 1).'. '.$rowDetail->appliance_item : ($index + 1).'. '.$rowDetail->appliance_item;
                            }
                        }
                    }
                }

                return $allItems;
            })
            ->addColumn('action', function($row) use ($companyId, $employeeId) {
                $token = ['cid' => $row->company_id, 'id' => $row->employee_id,'a' => $row->doc_approval_id,'b' => $row->reference_id,'c' => null,'d'=> $row->sign_flow_id];
                $encodedToken = SafeToken::encode($token);

                $token = ['cid' => $companyId, 'id' => $employeeId,'a' => $row->doc_approval_id,'b' => $row->reference_id, 'c'=>null, 'd'=>null, 'g'=>$row->reference_group_id];
                $tokenAttachment = SafeToken::encode($token);

                $actionList = '<li><a class="dropdown-item" href="javascript:void(0);" onclick="actionTable('."'".$encodedToken."'".', '."'VIEW'".')"><i class="fa-regular fa-files me-2"></i> View Document</a></li>
                <li><a class="dropdown-item actionBtnHeader" href="javascript:void(0);" data-token="'.$tokenAttachment.'" data-type="PRINT"><i class="fa-solid fa-print me-2"></i> Print Documents</a></li>
                <li><a class="dropdown-item actionBtnHeader" href="javascript:void(0);" data-token="'.$tokenAttachment.'" data-type="DOWNLOAD"><i class="fa-solid fa-arrow-down-to-line me-2"></i> Download Documents</a></li>';

                $action = '<div class="dropdown">
                                    <button class="btn btn-sm btn-secondary dropdown-toggle" data-bs-boundary="viewport" id="dropdownMenuButton"
                                        type="button" data-coreui-toggle="dropdown"
                                        aria-expanded="false">Action</button>
                                    <ul class="dropdown-menu dropdown-menu-end" aria-labelledby="dropdownMenuButton1" style="">
                                        '.$actionList.'
                                    </ul>
                                </div>';

                return $action;
            })
            ->editColumn('status', function($row) use ($type) {
                if($type == 'APPROVAL_HISTORY') {
                    $statuses = [
                        '8' => '<i title="Approved" class="fa-solid fa-circle-check text-success fs-5"></i>',
                        '9' => '<i title="Rejected" class="fa-solid fa-circle-xmark text-danger fs-5"></i>',
                        '11' => '<i title="Completed" class="fa-solid fa-circle-check text-success fs-5"></i>',
                        '14' => '<i title="Need Revision" class="fa-solid fa-circle-arrow-left text-warning fs-5"></i>',
                    ];
                    return $statuses[$row->status];
                }
                else if($type == 'REQUEST_HISTORY') {
                    $statuses = [
                        '8' => '<i title="Approved" class="fa-solid fa-circle-check text-success fs-5"></i>',
                        '9' => '<i title="Rejected" class="fa-solid fa-circle-xmark text-danger fs-5"></i>',
                        '11' => '<i title="Completed" class="fa-solid fa-circle-check text-success fs-5"></i>',
                        '12' => '<i title="Need Revision" class="fa-solid fa-circle-arrow-left text-warning fs-5"></i>',
                        '5' => '<i title="Need Revision" class="fa-solid fa-circle-arrow-left text-warning fs-5"></i>',
                    ];
                    return $statuses[$row->doc_status_id];
                }
            })
            ->rawColumns(['items','action', 'status'])
            ->make(true);
    }

    public function view(Request $request) {
        $token = $request->token;
        $decodeToken = SafeToken::decode($token);
        $employeeId = $decodeToken['id'];
        $companyId = (array_key_exists('cid', $decodeToken)) ? $decodeToken['cid'] : '1';

        // dd($decodeToken);
        $requestData = new Request();
        $requestData->merge(['documentType' => 'ALL', 'companyId' => $companyId]);
        $getDocumentType = $this->getDocumentType($requestData);

        $getCompany = UserSelectionRole::userCompanyRole([
                                                            'employeeId' => $employeeId,
                                                            'companyId' => $companyId,
                                                            'menuId' => '4',
                                                            'submenuId' => '3',
                                                            'selectedDefault' => false
                                                        ]);
        // foreach ($getCompany as $key => $value) {
        //     $getCompany[$key]['id'] = SafeToken::encode(['c' => $value['id']]);
        // }

        if(count($getCompany) > 1) {
            $getCompany = Arr::prepend($getCompany, ['id' => 'ALL', 'text' => '-- ALL COMPANY --', 'selected' => true]);
        }
        $arrCompany = $getCompany;

        if(array_key_exists('t', $decodeToken)) {
            if($decodeToken['t'] == 'INSPECTION_FORM') {
                return view('documentapproval::view_form_inspection', compact('getDocumentType','token','employeeId','arrCompany'));
            }
            else {
                return view('documentapproval::view_form', compact('getDocumentType','token','employeeId', 'arrCompany'));
            }
        }
        else {
            return view('documentapproval::view_form', compact('getDocumentType','token','employeeId','arrCompany'));
        }
    }

