    public function viewForm(Request $request) {
        $encodedToken = $request->token;
        $token = SafeToken::decode($encodedToken);
        $validator = Validator::make($token, [
            'id' => 'required',
            'a' => 'required',
            'b' => 'required',
        ]);

        if ($validator->fails()) {
            return response()->json(['message' => 'Invalid token form', 'errors' => $validator->errors()], 422)
                            ->setStatusCode(422, 'Invalid token form');
        }

        $rowId = $request->row_id;
        $sourceView = $request->source;
        $type = $request->type;
        $companyId = (array_key_exists('cid', $token)) ? $token['cid'] : '1';
        $employeeId = $token['id'];
        $docApprovalId = $token['a'];
        $referenceId = $token['b'];
        $groupId = (array_key_exists('g', $token)) ? $token['g'] : null;
        $tokenType = (array_key_exists('t', $token)) ? $token['t'] : null;
        // $approvalSignId = $token['c'];

        // dd($token);
        $response = collect();
        $model = new DocumentApprovalModel();

        $response['signStatusName'] = null;
        if($tokenType == 'INSPECTION_FORM') {
            $referenceId = $token['d'];
            $getInspection = $model->docApprovalOrderInspection()
                                ->from('doc_approval_order_inspection as a')
                                ->leftJoin('doc_approval_order_application as b', function($join) {
                                    $join->on('b.application_id', '=', 'a.application_id')
                                        ->where('b.is_active', '1');
                                })
                                ->leftJoin('doc_approval_order_group as c', function($join) {
                                    $join->on('c.application_id', 'b.application_id')
                                        ->on('c.comparison_id', 'b.comparison_id');
                                })
                                ->leftJoin('doc_approval_detail_order_form as d', function($join) {
                                    $join->on('d.order_form_id', 'c.order_form_id');
                                })
                                ->select('a.inspection_id', 'a.order_form_id', 'a.path_detail', 'a.filename', 'a.po_number', 'a.application_id', 'a.comparison_id', 'b.doc_approval_id', 'c.order_group_id', 'd.doc_approval_id as doc_approval_id_order')
                                ->where('a.application_id', $token['b'])
                                ->where('a.inspection_id', $referenceId)
                                ->where('a.is_active', '1')
                                ->orderBy('a.inspection_id', 'desc')
                                ->first();
            if($getInspection) {
                $token = ['cid'=>$companyId,'id'=>$employeeId, 't' =>'INSPECTION_FORM', 'a'=>$getInspection->doc_approval_id, 'b'=>$getInspection->application_id, 'c' =>$getInspection->comparison_id, 'd'=>$getInspection->inspection_id,'g'=>$getInspection->order_group_id];
                $encodedToken = SafeToken::encode($token);

                $tokenOrderForm = ['cid'=>$companyId,'id'=>$employeeId, 't' =>'INSPECTION_FORM', 'a' =>$getInspection->doc_approval_id_order, 'b' =>$getInspection->order_form_id, 'c'=>null, 'd'=>null,'g'=>$getInspection->order_group_id];
                $tokenOrderForm = SafeToken::encode($tokenOrderForm);

                $response['tokenForm'] = $encodedToken;
                $response['tokenAttachment'] = $tokenOrderForm;
                $response['title'] = 'INSPECTION FORM';
                $response['footerButton'] = '<button class="btn btn-outline-company col-sm-3 actionBtnHeader" data-type="PRINT" data-doc="" data-token="'.$encodedToken.'"><i class="fa-solid fa-print"></i> Print</button>
                <button class="btn btn-outline-danger col-sm-3 actionBtnHeader" data-type="DOWNLOAD" data-token="'.$encodedToken.'" data-selectedversion=""><i class="fa-solid fa-arrow-down-to-line"></i> Download</button>';

                return response()->json([
                    'status' => 200,
                    'message' => 'Success',
                    'data' => $response,
                ], 200);
            }
            else {
                $message = 'Not found';
                $response['form'] = view('documentapproval::form.view_disallowed', compact('message'))->render();
                return response()->json([
                    'status' => 404,
                    'message' => 'Not found',
                    'data' => $response,
                ], 200);
            }
        }
        else {
            $getHeader = $model->documentApprovalHeader()
                                ->from('doc_approval_header AS a')
                                ->leftJoin('master_transaction_status AS c', 'c.transaction_status_id', 'a.doc_status_id')
                                ->select('a.*', 'c.transaction_status_name')
                                ->where('a.doc_approval_id', $docApprovalId)
                                ->where('a.is_active', '1')
                                ->first();
            if($getHeader) {
                // GET LATEST SIGN FLOW
                $getSigner = $model->docApprovalFlowSign()
                                ->from('doc_approval_flow_sign as a')
                                ->leftJoin('vw_master_employee_active as b', 'b.employee_id', 'a.employee_id')
                                ->leftJoin('master_transaction_status as c', 'c.transaction_status_id', 'a.status')
                                ->select('a.*', 'b.employee_name', 'c.transaction_status_name')
                                ->where('a.doc_approval_id', $getHeader->doc_approval_id)
                                ->where('a.employee_id', $employeeId)
                                ->whereNotIn('a.flow_as', ['CC','RECEIVER']);

                if($getHeader->doc_type_id != '1' && $getHeader->doc_type_id != '4' && $groupId != null) {
                    $getSigner = $getSigner->where('a.reference_group_id', $groupId);
                }

                $getSigner = $getSigner->where('a.is_active', '1')
                                    ->orderBy('a.sign_flow_id', 'desc')
                                    ->first();

                if(!$getSigner) {
                    $message = 'Item not found';
                    $response['form'] = view('documentapproval::form.view_disallowed', compact('message'))->render();
                    return response()->json([
                        'status' => 404,
                        'message' => $message,
                        'data' => $response,
                        'rowId' => $rowId,
                    ], 200);
                }

                // dd($getHeader->doc_type_id);

                if($getSigner->flow_as != 'APPLICANT' && $getHeader->doc_status_id != '12' && ($getSigner->status == '13' || $getSigner->status == '15' || $getSigner->status == '16')) {
                    // 12 = CANCELED, 13 = PENDING, 15 = CHANGED, 16 = NOT SUBMITTED
                    // DISALLOWED TO VIEW FORM, IF LATEST STATUS 13 OR 15, EVENT FORM IS REVISE
                    if($getSigner->status == '13') {
                        // CHECK OTHER SIGN FLOW
                        $getOtherSignerFlow = $model->docApprovalFlowSign()
                                                ->from('doc_approval_flow_sign as a')
                                                ->leftJoin('vw_master_employee_active as b', 'b.employee_id', 'a.employee_id')
                                                ->leftJoin('master_transaction_status as c', 'c.transaction_status_id', 'a.status')
                                                ->select('a.*', 'b.employee_name', 'c.transaction_status_name')
                                                ->where('a.doc_approval_id', $getHeader->doc_approval_id)
                                                ->where('a.employee_id', $employeeId)
                                                ->whereNotIn('a.flow_as', ['APPLICANT','CC','RECEIVER']);
                        if($groupId != null) {
                            $getOtherSignerFlow = $getOtherSignerFlow->where('a.reference_group_id', $groupId);
                        }

                        $getOtherSignerFlow = $getOtherSignerFlow->whereIn('a.status', ['3','8']) // 3 = RECEIVED
                                                ->where('a.is_active', '1')
                                                ->orderBy('a.sign_flow_id', 'desc')
                                                ->first();
                        if($getOtherSignerFlow) {
                            $getSigner = $getOtherSignerFlow;
                            $referenceId = $referenceId ? $getOtherSignerFlow->reference_id : null;
                            // dd($referenceId);
                        }
                        else {
                            if($getSigner->status == '13') {
                                $message = 'Your current status on this version form is '.$getSigner->transaction_status_name.', please wait for the decision of another approver';
                            }
                            else if($getSigner->status == '15' || $getSigner->status == '16') {
                                $message = 'Approval form has been modified by the Applicant, currently your NOT AVAILABLE on this form';
                            }

                            $response['form'] = view('documentapproval::form.view_disallowed', compact('message'))->render();
                            return response()->json([
                                'status' => 404,
                                'message' => $message,
                                'data' => $response,
                                'rowId' => $rowId,
                            ], 200);
                        }
                    }
                }

                $lastFormSignRefId = $getSigner->reference_id;

                $dataForm = collect([
                    'docNumber' => $getHeader->doc_number,
                    'departmentName' => $getHeader->department_name,
                ]);

                $footerButton = false;
                $response['footerButton'] = '';

                if($getHeader->doc_type_id == '1') { // 1 = ORDER FORM
                    // GET FORM
                    // dd($token);
                    $getForm = $model->documentApprovalDetailOrder()
                                    ->from('doc_approval_detail_order_form as a')
                                    ->leftJoin('master_locations as b', 'b.location_id', '=', 'a.location_id')
                                    ->leftJoin('doc_approval_detail_order_form_purpose as c', 'c.order_form_id', '=', 'a.order_form_id');

                    // if($groupId != null) {
                    //     $getForm = $getForm->leftJoin(DB::raw('(SELECT reference_id, doc_approval_id, flow_as, status, is_active, employee_id, sign_flow_id, reference_group_id
                    //     FROM doc_approval_flow_sign
                    //     WHERE doc_approval_id = "'.$docApprovalId.'"
                    //     AND employee_id = "'.$employeeId.'"
                    //     AND reference_group_id = "'.$groupId.'"
                    //     AND flow_as NOT IN ("RECEIVER", "CC")
                    //     ORDER BY sign_flow_id DESC
                    //     LIMIT 1) as d'), 'd.reference_id', '=', 'a.order_form_id');
                    // }
                    // else {
                        $getForm = $getForm->leftJoin(DB::raw('(SELECT reference_id, doc_approval_id, flow_as, status, is_active, employee_id, sign_flow_id, reference_group_id
                        FROM doc_approval_flow_sign
                        WHERE doc_approval_id = "'.$docApprovalId.'"
                        AND employee_id = "'.$employeeId.'"
                        AND flow_as NOT IN ("RECEIVER", "CC")
                        ORDER BY sign_flow_id DESC
                        LIMIT 1) as d'), 'd.reference_id', '=', 'a.order_form_id');
                    // }

                    $getForm = $getForm->leftJoin('master_transaction_status as e', 'e.transaction_status_id', '=', 'd.status')
                                    ->leftJoin('doc_approval_order_group as g', function($join) {
                                        $join->on('g.order_group_id', '=', 'd.reference_group_id')
                                            ->where('g.is_active', '1');
                                    })
                                    ->leftJoin('doc_approval_order_inspection as f', function($join) {
                                        $join->on('f.order_form_id', '=', 'a.order_form_id')
                                            // ->on('f.application_id', '=', 'g.application_id')
                                            ->where('f.is_active', '1')
                                            ->whereNotNull('f.created_by');
                                    })

                                    ->select('a.doc_approval_id', 'a.order_form_status', 'a.doc_version', 'a.order_form_id', 'a.grand_total', 'a.request_date', 'a.currency_code', 'a.created_at', 'b.location_name', 'c.description', 'd.flow_as', 'd.status as status_sign', 'd.is_active as signer_active', 'e.transaction_status_name', 'f.inspection_id', 'g.comparison_id', 'g.application_id', 'g.order_group_id');

                    if($referenceId != null) {
                        // IF REFERENCE ID VALUE IS SET, GET BY REFERENCE ID, IF NOT GET LATEST FORM
                        $getForm = $getForm->where('a.order_form_id', $referenceId);
                    }

                    $getForm = $getForm->where('a.doc_approval_id', $getHeader->doc_approval_id)
                                        ->where('a.is_active', '1')
                                        ->orderBy('a.order_form_id', 'desc')
                                        ->first();

                    $referenceId = $getForm->order_form_id;
                    $token = ['cid' => $companyId, 'id' => $employeeId,'a' => $docApprovalId,'b' => $getForm->order_form_id,'c' =>null,'d'=>null,'g'=>$groupId];
                    $encodedToken = SafeToken::encode($token);
                    $response['tokenForm'] = $encodedToken;

                    // dd($getForm);
                    if($getForm->order_form_status == '6') { // 6 = REVISED
                        $getAllVersion = $model->documentApprovalDetailOrder()
                                                ->from('doc_approval_detail_order_form as a')
                                                ->select('a.doc_approval_id', 'a.doc_version', 'a.order_form_id')
                                                ->where('a.doc_approval_id', $getHeader->doc_approval_id)
                                                ->where('a.is_active', '1')
                                                ->orderBy('a.order_form_id', 'desc')
                                                ->get();
                        $latestVersion = null;
                        $versionList = '';
                        $x = 1;
                        foreach ($getAllVersion as $rowAllVersion) {
                            $token = ['cid' => $companyId, 'id' => $employeeId,'a' => $getHeader->doc_approval_id,'b' => $rowAllVersion->order_form_id,'c' => null,'d'=>null];
                            $encodedToken = SafeToken::encode($token);

                            $latestLabel = '';
                            if($x == 1) {
                                $latestVersion = $rowAllVersion->doc_version;
                                $latestLabel = ' (Latest)';
                            }

                            $active = $rowAllVersion->order_form_id == $getForm->order_form_id ? ' active' : '';
                            // $versionLabel = ($rowAllVersion->doc_version - 1 > 0) ? 'Rev. 0'.$rowAllVersion->doc_version - 1 : 'Old Version' ;
                            $versionLabel = 'Ver. '.$rowAllVersion->doc_version;
                            $selectedVersionLabel = $versionLabel.$latestLabel;
                            $versionList .= '<li><span class="dropdown-item docVersionItem'.$active.'" data-token="'.$encodedToken.'" data-form="ORDER_FORM">'.$selectedVersionLabel.'</span></li>';
                            $x++;
                        }

                        if($getForm->doc_version == $latestVersion) {
                            $selectedVersionLabel = 'Ver. '.$getForm->doc_version.' (Latest)';
                        }
                        else {
                            $selectedVersionLabel = 'Ver. '.$getForm->doc_version;
                        }

                        $response['selectedVersionLabel'] = 'for '.$selectedVersionLabel;
                        $response['title'] = $getHeader->doc_name.' <div class="dropdown dropdownDocVersion">
                                                        <button type="button" class="btn btn-default dropdown-toggle py-1 px-2" data-bs-boundary="viewport" id="dropdownDocVersion" data-coreui-toggle="dropdown" aria-expanded="false" title="Document Version">'.$selectedVersionLabel.'
                                                        </button>
                                                        <ul class="dropdown-menu dropdown-menu-end" aria-labelledby="dropdownDocVersion" style="">
                                                            '.$versionList.'
                                                        </ul>
                                                    </div>';

                        $response['footerButton'] = '<button class="btn btn-outline-company col-sm-3 actionBtn" data-type="PROGRESS" data-token="'.$response['tokenForm'].'" data-selectedversion="'.$response['selectedVersionLabel'].'"><i class="fa-regular fa-circle-info"></i> View Progress</button> <div class="alert alert-warning m-0 w-100 p-2" role="alert">This form has been <span class="fw-semibold">REVISED</span>, You can change the latest version form on the top of document</div>';
                    }
                    else {
                        if($getForm->doc_version > 1) {
                            $token = ['cid' => $companyId, 'id' => $employeeId,'a' => $getHeader->doc_approval_id,'b' => $getForm->order_form_id,'c' => null,'d'=>null, 'g'=>$groupId];
                            $encodedTokenLatest = SafeToken::encode($token);

                            $getAllVersion = $model->documentApprovalDetailOrder()
                                                ->from('doc_approval_detail_order_form as a')
                                                ->select('a.doc_approval_id', 'a.doc_version', 'a.order_form_id')
                                                ->where('a.doc_approval_id', $getHeader->doc_approval_id)
                                                ->where('a.order_form_id', '<>', $getForm->order_form_id)
                                                ->where('a.is_active', '1')
                                                ->orderBy('a.order_form_id', 'desc')
                                                ->get();
                            $versionList = '';
                            foreach ($getAllVersion as $rowAllVersion) {
                                $token = ['cid' => $companyId, 'id' => $employeeId,'a' => $getHeader->doc_approval_id,'b' => $rowAllVersion->order_form_id,'c' => null,'d'=>null];
                                $encodedToken = SafeToken::encode($token);

                                // $versionLabel = ($rowAllVersion->doc_version - 1 > 0) ? 'Rev. 0'.$rowAllVersion->doc_version - 1 : 'Old Version' ;
                                $versionLabel = 'Ver. '.$rowAllVersion->doc_version;
                                $versionList .= '<li><span class="dropdown-item docVersionItem" data-token="'.$encodedToken.'" data-form="ORDER_FORM">'.$versionLabel.'</span></li>';
                            }

                            $selectedVersionLabel = 'Ver. '.$getForm->doc_version.' (Latest)';
                            $response['selectedVersionLabel'] = 'for '.$selectedVersionLabel;
                            $response['title'] = $getHeader->doc_name.' <div class="dropdown dropdownDocVersion">
                                                        <button type="button" class="btn btn-default dropdown-toggle py-1 px-2" data-bs-boundary="viewport" id="dropdownDocVersion" data-coreui-toggle="dropdown" aria-expanded="false" title="Document Version">
                                                            Ver. '.$getForm->doc_version.' (Latest)
                                                        </button>
                                                        <ul class="dropdown-menu dropdown-menu-end" aria-labelledby="dropdownDocVersion" style="">
                                                            <li><span class="dropdown-item docVersionItem active" data-token="'.$encodedTokenLatest.'" data-form="ORDER_FORM">'.$selectedVersionLabel.'</span></li>
                                                            '.$versionList.'
                                                        </ul>
                                                    </div>';
                        }
                        else {
                            $response['selectedVersionLabel'] = '';
                            $response['title'] = $getHeader->doc_name;
                        }

                        if($getForm->flow_as == 'APPLICANT') {
                            if($getForm->order_form_status == '2' || $getForm->order_form_status == '5') { // 2 = SUBMITTED, 5 = NEED REVISE
                                if($getForm->order_form_status == '5' && $groupId != null) {
                                    $getOrderGroup = $model->documentApprovalOrderGroup()
                                                        ->from('doc_approval_order_group as a')
                                                        ->select('a.is_need_revision')
                                                        ->where('a.order_form_id', $referenceId)
                                                        ->where('a.order_group_id', $groupId)
                                                        ->where('a.is_active', '1')
                                                        ->orderBy('a.order_group_id', 'desc')
                                                        ->first();
                                    if($getOrderGroup->is_need_revision == '0') {
                                        $response['footerButton'] = '<button class="btn btn-outline-company actionBtn" data-type="PROGRESS" data-token="'.$response['tokenForm'].'" data-selectedversion="'.$response['selectedVersionLabel'].'"><i class="fa-regular fa-circle-info"></i> View Progress</button>';
                                    }
                                    else {
                                        $response['footerButton'] = '<button class="btn btn-outline-company actionBtn" data-type="PROGRESS" data-token="'.$response['tokenForm'].'" data-selectedversion="'.$response['selectedVersionLabel'].'"><i class="fa-regular fa-circle-info"></i> View Progress</button>
                                        <button class="btn btn-default actionBtn" data-type="REVISE" data-doc="'.$getHeader->doc_type_id.'" data-token="'.$response['tokenForm'].'"><i class="fa-regular fa-pen-to-square"></i> Revise Form</button>
                                        <button class="btn btn-outline-danger actionBtn" data-type="CANCEL" data-token="'.$response['tokenForm'].'"><i class="fa-solid fa-xmark"></i> Cancel Form</button>';
                                    }
                                }
