                if($getHeader->doc_status_id == '12') { // 12 = CANCELED
                    $comment = '--';
                    $getComment = $model->docApprovalFlowComment()
                                        ->from('doc_approval_flow_comment as a')
                                        ->select('a.comment_id', 'a.reply_comment_id', 'a.is_reply', 'a.comment')
                                        ->leftJoin('doc_approval_flow_sign as b', function($join) {
                                            $join->on('b.sign_flow_id', 'a.sign_flow_id')
                                                ->on('b.employee_id', 'a.employee_id')
                                                ->where('b.is_active', '1');
                                        })

                                        ->where('b.doc_approval_id', $docApprovalId)
                                        ->where('a.employee_id', $getHeader->employee_id)
                                        ->where('a.is_main', '1')
                                        ->where('a.is_active', '1')
                                        ->orderBy('a.comment_id', 'desc')
                                        ->first();

                    if($getComment) {
                        $comment = $getComment->comment;
                    }

                    $response['footerButton'] = '<button class="btn btn-outline-company col-sm-3 actionBtn" data-type="PROGRESS" data-token="'.$response['tokenForm'].'" data-selectedversion="'.$response['selectedVersionLabel'].'"><i class="fa-regular fa-circle-info"></i> View Progress</button> <div class="alert alert-danger m-0 w-100 p-2" role="alert">This form has been <span class="fw-semibold">'.$getHeader->transaction_status_name.'</span> by APPLICANT. Reason : '.$comment;
                }
                else if($getHeader->doc_type_id == '1' && $getHeader->employee_id != $getSigner->employee_id && $getSigner->flow_as == 'RECEIVER') {
                    $getInspection = $model->docApprovalOrderInspection()
                                            ->from('doc_approval_order_inspection AS a')
                                            ->leftJoin('doc_approval_order_group as b', function($join) {
                                                $join->on('b.inspection_id', 'a.inspection_id')
                                                    ->where('b.is_active', '1');
                                            })
                                            ->select('a.inspection_id', 'a.created_at', 'a.created_by', 'b.order_group_id')
                                            ->where('a.order_form_id', $referenceId)
                                            ->where('b.order_group_id', $getSigner->reference_group_id)
                                            ->whereNotNull('a.created_by')
                                            ->where('a.is_active', '1')
                                            ->orderBy('a.inspection_id', 'desc')
                                            ->first();
                    if($getInspection) {
                        $response['footerButton'] = '<button class="btn btn-outline-company col-sm-3 actionBtn" data-type="PROGRESS" data-token="'.$response['tokenForm'].'" data-selectedversion="'.$response['selectedVersionLabel'].'"><i class="fa-regular fa-circle-info"></i> View Progress</button> <div class="alert alert-info m-0 w-100 p-2" role="alert">This Order Form has been <span class="fw-semibold">COMPLETED</span>, view on menu Procurement & Purchasing <i class="fa-regular fa-arrow-right"></i> History</div>';
                    }
                    else {
                        $response['footerButton'] = '<button class="btn btn-outline-company col-sm-3 actionBtn" data-type="PROGRESS" data-token="'.$response['tokenForm'].'" data-selectedversion="'.$response['selectedVersionLabel'].'"><i class="fa-regular fa-circle-info"></i> View Progress</button> <div class="alert alert-info m-0 w-100 p-2" role="alert">This Order Form has been <span class="fw-semibold">'.$getHeader->transaction_status_name.'</span>, view on menu Procurement & Purchasing <i class="fa-regular fa-arrow-right"></i> Purchasing Request</div>';
                    }

                    // $response->put('frameSrc', '/framePdf?token='.$encodedToken);
                    // $response->put('form', view('procurementpurchasing::form.order_form.view_form', compact('dataForm'))->render());
                    // $response->put('form', view('procurementpurchasing::form.order_form.view_form_pdf', compact('dataForm'))->render());
                    // $requestData = new Request();
                    // $requestData->replace([
                    //                         'documentType' => $getHeader->doc_type_id,
                    //                         'dataForm' => compact('dataForm'),
                    //                     ]);
                    // $viewToPdf = $this->viewToPdf($requestData);
                    // // return response()->download($viewToPdf)->deleteFileAfterSend(true);
                    // return response()->file($viewToPdf, [
                    //                         'Content-Type' => 'application/pdf',
                    //                         'Content-Disposition' => 'inline; filename="document.pdf"'
                    //                     ])->deleteFileAfterSend(false);
                }

                return response()->json([
                    'status' => 200,
                    'message' => 'Success',
                    'data' => $response,
                    'rowId' => $rowId,
                ], 200);
            }
            else{
                $message = 'Not found';
                $response['form'] = view('documentapproval::form.view_disallowed', compact('message'))->render();
                return response()->json([
                    'status' => 404,
                    'message' => 'Not found',
                    'data' => $response,
                    'rowId' => $rowId,
                ], 200);
            }
        }
    }

    public function getDocumentList(Request $request) {
        $token = SafeToken::decode($request->token);
        $employeeId = $token['id'];
        $docApprovalId = $token['a'];
        $referenceId = $token['b'];
        $tokenType = (array_key_exists('t', $token)) ? $token['t'] : null;
        $companyId = (array_key_exists('cid', $token)) ? $token['cid'] : '1';
        $groupId = (array_key_exists('g', $token)) ? $token['g'] : null;

        $response = collect();
        $response['form'] = '';
        $model = new DocumentApprovalModel();

        // dd($token);
        $getHeader = $model->documentApprovalHeader()
                            ->from('doc_approval_header as a')
                            ->select('a.employee_id', 'a.doc_approval_id', 'a.doc_type_id', 'a.doc_name', 'a.department_name')
                            ->where('a.doc_approval_id', $docApprovalId)
                            ->where('a.is_active', '1')
                            ->first();

        if($getHeader) {
            if($tokenType == 'INSPECTION_FORM') {
                // GET INSPECTION FORM
                $rowList = '';
                $getInspectionForm = $model->docApprovalOrderInspection()
                                        ->from('doc_approval_order_inspection as a')
                                        ->leftJoin('doc_approval_order_application as b', function($join) {
                                            $join->on('b.application_id', '=', 'a.application_id')
                                                ->where('b.is_active', '1');
                                        })
                                        ->select('a.inspection_id', 'a.order_form_id', 'a.path_detail', 'a.filename', 'a.po_number', 'a.application_id', 'a.doc_approval_id')
                                        ->where('a.inspection_id', $token['d'])
                                        ->where('a.company_id', $companyId)
                                        ->whereNotNull('a.created_at')
                                        ->where('a.is_active', '1')
                                        ->orderBy('a.inspection_id', 'desc')
                                        ->get();
