                                                        <th style="width: 90%; background-color: #c4c4c4;">APPLICATION & PO FORM</th>
                                                    </tr>
                                                </thead>
                                                <tbody>
                                                '.$rowList.'
                                                </tbody>
                                            </table>';
                        // END GET APPLICATION FORM ATTACHMENT

                        // GET COMPARISON FORM
                        $rowList = '';
                        $getComparisonForm = $model->docApprovalOrderComparison()
                                            ->from('doc_approval_order_comparison as a')
                                            ->leftJoin('doc_approval_order_group as b', function($join) use($referenceId) {
                                                $join->on('b.comparison_id', 'a.comparison_id')
                                                    ->where('b.is_active', '1')
                                                    ->orderBy('b.order_group_id', 'desc');
                                            })
                                            ->select('a.comparison_id', 'a.doc_approval_id', 'a.order_form_id', 'a.path_detail', 'a.filename', 'a.comparison_title')
                                            ->where('a.comparison_id', $getApplicationForm->comparison_id)
                                            ->where('b.order_group_id', $groupId)
                                            ->where('a.is_active', '1')
                                            ->orderBy('a.comparison_id', 'desc')
                                            ->first();
                        if ($getComparisonForm) {
                            $token = ['cid'=>$companyId,'id'=>$employeeId, 't'=>'COMPARISON_FORM', 'a' =>$getComparisonForm->doc_approval_id, 'b' => $getComparisonForm->order_form_id, 'c'=> $getComparisonForm->comparison_id, 'g'=>$groupId];
                            $encodedToken = SafeToken::encode($token);

                            $rowList .= '<tr class="rowTableCustom active" data-token="">
                                            <td class="text-center align-middle">
                                                <input type="checkbox" class="form-check-input me-2 rowTableCheckbox" name="rowTableCheckbox[]" value="'.$encodedToken.'" checked="">
                                            </td>
                                            <td>
                                                <span class="file-name fw-medium">COMPARISON : '.$getComparisonForm->comparison_title.'.pdf</span>
                                            </td>
                                        </tr>';
                            $checkAll = ' <input type="checkbox" class="form-check-input me-2 rowTableCheckboxAll" checked="">';

                            // GET ATTACHMENT COMPARISON FORM
                            $getAttachment = $model->docApprovalAttachment()
                                                ->select('attachment_id', 'mime_type', 'filename_original', 'downloadable')
                                                ->where('doc_approval_id', $getComparisonForm->doc_approval_id)
                                                ->where('reference_id', $getComparisonForm->comparison_id)
                                                ->where('doc_type_id', '6') // 6 = COMPARISON FORM
                                                ->where('is_active', '1')
                                                ->orderBy('attachment_id', 'asc')
                                                ->get();
                            foreach ($getAttachment as $row) {
                                $token = ['cid'=>$companyId,'id'=>$employeeId, 't'=>'COMPARISON_FORM_ATTACHMENT', 'a' =>$getComparisonForm->doc_approval_id, 'b' => $getComparisonForm->comparison_id, 'c' => $row->attachment_id];
                                $encodedToken = SafeToken::encode($token);

                                $rowList .= '<tr class="rowTableCustom active" data-token="">
                                                <td class="text-center align-middle">
                                                    <input type="checkbox" class="form-check-input me-2 rowTableCheckbox" name="rowTableCheckbox[]" value="'.$encodedToken.'" checked="">
                                                </td>
                                                <td>
                                                    <span class="file-name fw-medium">'.$row->filename_original.'</span>
                                                </td>
                                            </tr>';
                            }
                            // END GET ATTACHMENT COMPARISON FORM
                        }

                        if($rowList == '') {
                            $checkAll = '';
                            $rowList = '<tr class="rowTableCustom" data-token="">
                                            <td class="text-center align-middle">
                                            </td>
                                            <td>
                                                <span class="file-name fw-medium">No comparison form data</span>
                                            </td>
                                        </tr>';
                        }

                        $response['form'] .= '<table class="table table-hover table-attachment-aside" style="border: 1px solid #c4c4c4;">
                                                    <thead>
                                                        <tr>
                                                            <th class="text-center" style="width: 10%; background-color: #c4c4c4;">
                                                            '.$checkAll.'
                                                            </th>
                                                            <th style="width: 90%; background-color: #c4c4c4;">COMPARISON FORM</th>
                                                        </tr>
                                                    </thead>
                                                    <tbody>
                                                    '.$rowList.'
                                                    </tbody>
                                                </table>';
                        // END GET COMPARISON FORM

                        // GET ORDER FORM
                        $getOrderForm = $model->documentApprovalDetailOrder()
                                        ->from('doc_approval_detail_order_form as a')
                                        ->leftJoin('doc_approval_order_group as b', function($join) {
                                            $join->on('b.order_form_id', 'a.order_form_id')
                                                ->where('b.is_active', '1')
                                                ->orderBy('b.order_group_id', 'desc');
                                        })
                                        ->select('a.doc_approval_id', 'a.order_form_id', 'a.order_form_status', 'a.order_form_number', 'a.path_detail', 'a.filename')
                                        ->where('a.company_id', $companyId)
                                        ->where('a.order_form_id', $getApplicationForm->order_form_id)
                                        ->where('b.order_group_id', $groupId)
                                        ->where('a.is_active', '1')
                                        ->first();
                        if ($getOrderForm) {
                            $rowList = '';
                            $token = ['cid'=>$companyId,'id'=>$employeeId, 't'=>'ORDER_FORM', 'a' =>$getOrderForm->doc_approval_id, 'b' => $getOrderForm->order_form_id, 'c'=> null, 'g'=>$groupId];
                            $encodedToken = SafeToken::encode($token);

                            $rowList .= '<tr class="rowTableCustom active" data-token="">
                                            <td class="text-center align-middle">
                                                <input type="checkbox" class="form-check-input me-2 rowTableCheckbox" name="rowTableCheckbox[]" value="'.$encodedToken.'" checked="">
                                            </td>
                                            <td>
                                                <span class="file-name fw-medium">ORDER FORM : '.$getOrderForm->order_form_number.'.pdf</span>
                                            </td>
                                        </tr>';

                            // GET ORDER FORM ATTACHMENT
                            $getAttachment = $model->docApprovalAttachment()
                                                ->select('attachment_id', 'mime_type', 'filename_original', 'downloadable')
                                                ->where('doc_approval_id', $getOrderForm->doc_approval_id)
                                                ->where('reference_id', $getOrderForm->order_form_id)
                                                ->where('doc_type_id', '1')
                                                ->where('is_active', '1')
                                                ->orderBy('attachment_id', 'asc')
                                                ->get();
                            foreach ($getAttachment as $row) {
                                $token = ['cid'=>$companyId,'id'=>$employeeId, 't'=>'ORDER_FORM_ATTACHMENT', 'a' =>$getOrderForm->doc_approval_id, 'b' => $getOrderForm->order_form_id, 'c' => $row->attachment_id, 'g'=>$groupId];
                                $encodedToken = SafeToken::encode($token);

                                $rowList .= '<tr class="rowTableCustom active" data-token="">
                                                <td class="text-center align-middle">
                                                    <input type="checkbox" class="form-check-input me-2 rowTableCheckbox" name="rowTableCheckbox[]" value="'.$encodedToken.'" checked="">
                                                </td>
                                                <td>
                                                    <span class="file-name fw-medium">'.$row->filename_original.'</span>
                                                </td>
                                            </tr>';
                            }

                            $response['form'] .= '<table class="table table-hover table-attachment-aside" style="border: 1px solid #c4c4c4;">
                                                    <thead>
                                                        <tr>
                                                            <th class="text-center" style="width: 10%; background-color: #c4c4c4;">
                                                                <input type="checkbox" class="form-check-input me-2 rowTableCheckboxAll" checked="">
                                                            </th>
                                                            <th style="width: 90%; background-color: #c4c4c4;">ORDER FORM</th>
                                                        </tr>
                                                    </thead>
                                                    <tbody>
                                                    '.$rowList.'
                                                    </tbody>
                                                </table>';

                        }
                        // END GET ORDER FORM
                    }
                }
            }
        }

        return response()->json([
            'status' => 200,
            'message' => 'Success',
            'data' => $response,
        ], 200);
    }

    public function getProgress(Request $request) {
        $token = SafeToken::decode($request->token);
        $employeeId = $token['id'];
        $docApprovalId = $token['a'];
        $referenceId = $token['b'];
        $groupId = (array_key_exists('g', $token)) ? $token['g'] : null;
        $dataType = $request->type;
        // dd($token);
        $model = new DocumentApprovalModel();
        $response = collect();

        $getHeader = $model->documentApprovalHeader()
                            ->from('doc_approval_header AS a')
                            ->select('a.doc_type_id')
                            ->where('a.doc_approval_id', $docApprovalId)
                            ->where('a.is_active', '1')
                            ->first();
        if($getHeader) {
            $progressList = '';
            $orderFormCreatedAt = $orderFormReceivedAt = null;
            $getSigner = $model->docApprovalFlowSign()
                                    ->from('doc_approval_flow_sign as a')
                                    ->leftJoin('vw_master_employee_all as b', 'b.employee_id', 'a.employee_id')
                                    ->leftJoin('master_transaction_status as c', 'c.transaction_status_id', 'a.status')
                                    ->select('a.*', 'b.employee_name', 'b.avatar', 'c.transaction_status_name')
                                    ->where('a.doc_approval_id', $docApprovalId)
                                    ->where('a.doc_type_id', $getHeader->doc_type_id)
                                    ->where('a.reference_id', $referenceId);

            if($getHeader->doc_type_id != '1' && $groupId != null) {
                $getSigner = $getSigner->where('a.reference_group_id', $groupId);
            }

            $getSigner = $getSigner->whereNotIn('a.flow_as', ['CC','RECEIVER'])
                                    ->whereNotNull('a.employee_id')
                                    ->where('a.is_active', '1')
                                    // ->orderBy('a.flow_as', 'asc')
                                    ->orderBy('a.sign_flow_id', 'asc')
                                    ->get();
            // dd($getHeader);
            if($getHeader->doc_type_id == '1') { // 1 = ORDER FORM
                $orderForm = $applicationApproval = $purchasingProgress = '';
                $getForm = $model->documentApprovalDetailOrder()
                                    ->from('doc_approval_detail_order_form')
                                    ->select('order_form_status', 'created_at', 'final_decision_at')
                                    ->where('doc_approval_id', $docApprovalId)
                                    ->where('order_form_id', $referenceId)
                                    ->where('is_active', '1')
                                    ->first();
                if ($getForm) {
                    $orderFormCreatedAt = $getForm->created_at;
                    $orderFormReceivedAt = $getForm->final_decision_at;
                    foreach ($getSigner as $row) {
                        $comment = '--';
                        if($row->status != '3' && $row->status != '13' && $row->status != '15') {
                            $getComment = $model->docApprovalFlowComment()
                                                    ->from('doc_approval_flow_comment')
                                                    ->select('comment_id', 'reply_comment_id', 'is_reply', 'comment')
                                                    ->where('sign_flow_id', $row->sign_flow_id)
                                                    ->where('employee_id', $row->employee_id)
                                                    ->where('is_main', '1')
                                                    ->where('is_active', '1')
                                                    ->orderBy('comment_id', 'desc')
                                                    ->first();

                            if($getComment) {
                                $comment = $getComment->comment;
                            }
                        }

                        $badgeDot = $receivedAt = $badgeStatus = '';
                        if($row->flow_as == 'APPLICANT') {
                            $receivedAt = '<span class="badge bg-default fs-9">'.$row->flow_as.'</span>';
                            if($row->transaction_status_name == 'SUBMITTED') {
                                $receivedAt .= '<span class="d-block">Submited at : '.Carbon::parse($orderFormCreatedAt)->format('d-M-Y H:i:s').'</span>';
                                $badgeDot = '<div class="timeline-badge bg-success"><i class="fa-solid fa-check"></i></div>';
                                $badgeStatus = '<span class="badge bg-success fs-9 fw-semibold">SUBMITTED</span>';
                            }
                            else if($row->transaction_status_name == 'REVISED') {
                                $badgeDot = '<div class="timeline-badge bg-warning"><i class="fa-solid fa-arrow-turn-left"></i></div>';
                                $badgeStatus = '<span class="badge bg-warning fs-9 fw-semibold">REVISED</span>
                                                <span class="d-block">'.Carbon::parse($row->decision_at)->format('d-M-Y H:i:s').'</span>';
                            }
                            else if($row->transaction_status_name == 'CANCELED') {
                                $badgeDot = '<div class="timeline-badge bg-danger"><i class="fa-solid fa-xmark-large"></i></div>';
                                $badgeStatus = '<span class="badge bg-warning fs-9 fw-semibold">CANCELED</span>
                                                <span class="d-block">'.Carbon::parse($row->decision_at)->format('d-M-Y H:i:s').'</span>';
                            }
                        }
                        else{
                            $receivedAt = '<span class="badge bg-default fs-9">'.$row->flow_as.'</span>';
                            if($row->transaction_status_name == 'RECEIVED') {
                                $badgeDot = '<div class="timeline-badge pulse-animation bg-info"></div>';
                                $receivedAt .= '<span class="d-block">Received at : '.Carbon::parse($row->received_at)->format('d-M-Y H:i:s').'</span>';
                                $badgeStatus = '<span class="badge pulse-animation bg-info fs-9 fw-semibold">UNDER REVIEW</span>';
                            }
                            else if($row->transaction_status_name == 'APPROVED') {
                                $badgeDot = '<div class="timeline-badge bg-success"><i class="fa-solid fa-check"></i></div>';
                                $receivedAt .= '<span class="d-block">Received at : '.Carbon::parse($row->received_at)->format('d-M-Y H:i:s').'</span>';
                                $badgeStatus = '<span class="badge bg-success fs-9 fw-semibold">APPROVED</span>
                                                <span class="d-block">'.Carbon::parse($row->decision_at)->format('d-M-Y H:i:s').'</span>';
                            }
                            else if($row->transaction_status_name == 'REJECTED') {
                                $badgeDot = '<div class="timeline-badge bg-danger"><i class="fa-solid fa-xmark-large"></i></div>';
                                $receivedAt .= '<span class="d-block">Received at : '.Carbon::parse($row->received_at)->format('d-M-Y H:i:s').'</span>';
                                $badgeStatus = '<span class="badge bg-danger fs-9 fw-semibold">REJECTED</span>
                                                <span class="d-block">'.Carbon::parse($row->decision_at)->format('d-M-Y H:i:s').'</span>';
                            }
                            else if($row->transaction_status_name == 'PENDING') {
                                $badgeDot = '<div class="timeline-badge bg-light-dark"></div>';
                                $badgeStatus = '<span class="badge bg-default fs-9 fw-semibold">PENDING</span>';
                            }
                            else if($row->transaction_status_name == 'CANCELED') {
                                $badgeDot = '<div class="timeline-badge bg-warning"></div>';
                                $badgeStatus = '<span class="badge bg-warning fs-9 fw-semibold">CANCELED</span>';
                            }
                            else if ($row->transaction_status_name == 'CHANGED') {
                                $badgeDot = '<div class="timeline-badge bg-default"></div>';
                                $badgeStatus = '<span class="badge bg-default fs-9 fw-semibold">CHANGED</span>
                                                <span class="d-block">'.Carbon::parse($row->decision_at)->format('d-M-Y H:i:s').'</span>';
                            }
                            else if($row->transaction_status_name == 'NOT SUBMITTED') {
                                if ($getForm->application_form_status == '6') {  // 6 = REVISED,
                                    $badgeDot = '<div class="timeline-badge bg-default"></div>';
                                    $badgeStatus = '<span class="badge bg-default fs-9 fw-semibold">NOT SUBMITTED - REVISED BY USER</span>';
                                }
                                else if ($getForm->application_form_status == '12') {  // 12 = CANCELED,
                                    $badgeDot = '<div class="timeline-badge bg-default"></div>';
                                    $badgeStatus = '<span class="badge bg-default fs-9 fw-semibold">NOT SUBMITTED - CANCELED BY USER</span>';
                                }
                                else if ($getForm->application_form_status == '9') {  // 9 = REJECTED,
                                    $badgeDot = '<div class="timeline-badge bg-default"></div>';
                                    $badgeStatus = '<span class="badge bg-default fs-9 fw-semibold">NOT SUBMITTED</span>';
                                }
                            }
                            else if($row->transaction_status_name == 'SEND BACK') {
                                $badgeDot = '<div class="timeline-badge bg-secondary"><i class="fa-solid fa-arrow-turn-left"></i></div>';
                                $receivedAt .= '<span class="d-block">Received at : '.Carbon::parse($row->received_at)->format('d-M-Y H:i:s').'</span>';
                                $badgeStatus = '<span class="badge bg-secondary fs-9 fw-semibold">SEND BACK TO REVISE</span>
                                                <span class="d-block">'.Carbon::parse($row->decision_at)->format('d-M-Y H:i:s').'</span>';
                            }
                        }

                        $orderForm .= '<div class="timeline-item">
                                            '.$badgeDot.'
                                            <div class="card">
                                                <div class="row pt-2 pb-2">
                                                    <div class="col-sm-12 col-md-7 mb-sm-0 pt-0 pb-1">
                                                        <div class="card-header py-0">
                                                            <div class="d-flex align-items-center">
                                                                <span class="avatar-text">'.Str::upper($row->employee_name).'</span>
                                                            </div>
                                                        </div>
                                                        <div class="card-body py-0">
                                                            '.$receivedAt.'
                                                        </div>
                                                    </div>
                                                    <div class="col-sm-12 col-md-5 mb-sm-0 pt-0 pb-1">
                                                        <div class="card-header py-0">
                                                            <div class="d-flex align-items-center">
                                                                <span class="avatar-text fw-medium">Result</span>
                                                            </div>
                                                        </div>
                                                        <div class="card-body py-0">
                                                            '.$badgeStatus.'
                                                        </div>
                                                    </div>
                                                    <div class="col-sm-12 col-md-12 mb-sm-0 pt-0 pb-1">
                                                        <div class="card-header py-0">
                                                            <div class="d-flex align-items-center">
                                                                <span class="avatar-text fw-medium">Comments</span>
                                                            </div>
                                                        </div>
                                                        <div class="card-body py-0">
                                                            '.nl2br($comment).'
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>';
                    }

                    if($dataType != 'PROGRESS_SIGN') {
                        // GET APPLICATION & PO FORM APPROVAL
                        if ($getForm->order_form_status == '8') { // 8 = APPROVED, 9 = REJECTED
                            $getApplication = $model->docApprovalOrderApplication()
                                                    ->from('doc_approval_order_application AS a')
                                                    ->leftJoin('master_vendor as c', 'c.vendor_id', '=', 'a.vendor_id')
                                                    ->select('a.application_id', 'a.doc_approval_id', 'a.application_form_status', 'a.created_by', 'a.created_at', 'a.final_decision_at', 'a.received_order_by', 'a.received_order_at', 'a.invoiced_order_by', 'a.invoiced_order_at', 'c.vendor_name', 'a.open_order_at');
                            if($groupId != null) {
                                $getApplication = $getApplication->leftJoin('doc_approval_order_group as b', 'b.application_id', '=', 'a.application_id')
                                                                ->where('b.order_group_id', '=', $groupId);
                            }

                            $getApplication = $getApplication->where('a.order_form_id', $referenceId)
                                                        ->where('a.is_active', '1')
                                                        ->orderBy('a.application_id', 'desc')
                                                        ->first();

                            if($getApplication) {
                                $applicationApproval = '<div class="timeline-item">
                                                            <div class="timeline-badge bg-success"><i class="fa-solid fa-check"></i></div>
                                                            <div class="card">
                                                                <div class="row pt-2 pb-2">
                                                                    <div class="col-sm-12 col-md-7 mb-sm-0 pt-0 pb-1">
                                                                        <div class="card-body py-0">
                                                                            <span class="badge bg-success fs-9 fw-semibold">ORDER FORM RECEIVED</span>
                                                                            <span class="d-block">'.Carbon::parse($getForm->final_decision_at)->format('d-M-Y H:i:s').'</span>
                                                                        </div>
                                                                    </div>
                                                                </div>
                                                            </div>
                                                        </div>';
                                $getSigner = $model->docApprovalFlowSign()
                                                        ->from('doc_approval_flow_sign as a')
                                                        ->leftJoin('vw_master_employee_all as b', 'b.employee_id', 'a.employee_id')
                                                        ->leftJoin('master_transaction_status as c', 'c.transaction_status_id', 'a.status')
                                                        ->select('a.*', 'b.employee_name', 'b.avatar', 'c.transaction_status_name')
                                                        ->where('a.doc_approval_id', $getApplication->doc_approval_id)
                                                        ->where('a.doc_type_id', '2')
                                                        ->where('a.reference_id', $getApplication->application_id)
                                                        ->whereNotIn('a.flow_as', ['CC','RECEIVER'])
                                                        ->whereNotNull('a.employee_id')
                                                        ->where('a.reference_group_id', $groupId)
                                                        ->where('a.is_active', '1')
                                                        ->orderBy('a.sign_flow_id', 'asc')
                                                        ->get();
                                foreach ($getSigner as $row) {
                                    $comment = '--';
                                    if($row->status != '3' && $row->status != '13' && $row->status != '15') {
                                        $getComment = $model->docApprovalFlowComment()
                                                                ->from('doc_approval_flow_comment')
                                                                ->select('comment_id', 'reply_comment_id', 'is_reply', 'comment')
                                                                ->where('sign_flow_id', $row->sign_flow_id)
                                                                ->where('employee_id', $row->employee_id)
                                                                ->where('is_main', '1')
                                                                ->where('is_active', '1')
                                                                ->orderBy('comment_id', 'desc')
                                                                ->first();

                                        if($getComment) {
                                            $comment = $getComment->comment;
                                        }
                                    }

                                    $badgeDot = $receivedAt = $badgeStatus = '';
                                    if($row->flow_as == 'APPLICANT') {
                                        $receivedAt = '<span class="badge bg-default fs-9">'.$row->flow_as.'</span>';
                                        if($row->transaction_status_name == 'SUBMITTED') {
                                            $receivedAt .= '<span class="d-block">Received at : '.Carbon::parse($orderFormReceivedAt)->format('d-M-Y H:i:s').'</span>';
                                            $badgeDot = '<div class="timeline-badge bg-success"><i class="fa-solid fa-check"></i></div>';
                                            $badgeStatus = '<span class="badge bg-success fs-9 fw-semibold">SUBMITTED</span>
                                                            <span class="d-block">'.Carbon::parse($row->decision_at)->format('d-M-Y H:i:s').'</span>';
                                        }
                                        else if($row->transaction_status_name == 'REVISED') {
                                            $badgeDot = '<div class="timeline-badge bg-warning"><i class="fa-solid fa-arrow-turn-left"></i></div>';
                                            $badgeStatus = '<span class="badge bg-warning fs-9 fw-semibold">REVISED</span>
                                                            <span class="d-block">'.Carbon::parse($row->decision_at)->format('d-M-Y H:i:s').'</span>';
                                        }
                                        else if($row->transaction_status_name == 'CANCELED') {
                                            $badgeDot = '<div class="timeline-badge bg-danger"><i class="fa-solid fa-xmark-large"></i></div>';
                                            $badgeStatus = '<span class="badge bg-warning fs-9 fw-semibold">CANCELED</span>
                                                            <span class="d-block">'.Carbon::parse($row->decision_at)->format('d-M-Y H:i:s').'</span>';
                                        }

                                        $applicationApproval .= '<div class="timeline-item">
                                                                    '.$badgeDot.'
                                                                    <div class="card">
                                                                        <div class="row pt-2 pb-2">
                                                                            <div class="col-sm-12 col-md-7 mb-sm-0 pt-0 pb-1">
                                                                                <div class="card-header py-0">
                                                                                    <div class="d-flex align-items-center">
                                                                                        <span class="avatar-text">'.Str::upper($row->employee_name).'</span>
                                                                                    </div>
                                                                                </div>
                                                                                <div class="card-body py-0">
                                                                                    '.$receivedAt.'
                                                                                </div>
                                                                            </div>
