    public function getInspection(Request $request) {
        $token = SafeToken::decode($request->token);
        $companyId = $token['cid'];
        $employeeId = $token['id'];
        $docApprovalId = $token['a'];
        $referenceId = $token['b'];
        $groupId = $token['g'];

        $model = new DocumentApprovalModel();
        $response = [];
        $response['inspectionFlow'] = $response['form'] = [];

        $inspectionDepartment = $inspectionReceiver = $inspectionChecker = $inspectionConfirmer = 'Not Available';
        $arrReceiver = $arrDepartment = [];
        $getInspectionReceiver = $model->docApprovalOrderApplication()
                                    ->from('doc_approval_order_application as a')
                                    ->leftJoin('doc_approval_detail_order_form as b', 'a.order_form_id', '=', 'b.order_form_id')
                                    ->leftJoin('doc_approval_matrix as c', function($join) {
                                        $join->on('c.employee_id', '=', 'b.employee_id')
                                            ->on('c.department_id', '=', 'b.department_id')
                                            ->where('c.matrix_as', 'INSPECTION_RECEIVER')
                                            ->where('c.doc_type_id', '4');
                                    })
                                    ->leftJoin('vw_master_employee_all as d', 'd.employee_id', 'c.employee_id_approval')
                                    ->leftJoin('vw_master_department as e', 'e.department_id', 'b.department_id')
                                    ->select('b.department_id', 'c.employee_id_approval', 'd.employee_name', 'e.department_name')
                                    ->where('a.application_id', $referenceId)
                                    // ->where('c.matrix_as', 'INSPECTION_RECEIVER')
                                    ->get();
        foreach($getInspectionReceiver as $index => $rowInspectionReceiver) {
            $inspectionDepartment = $rowInspectionReceiver->department_name;
            if(!empty($rowInspectionReceiver->employee_name)) {
                if($inspectionReceiver == 'Not Available') {
                    $inspectionReceiver = $rowInspectionReceiver->employee_name;
                }
                else {
                    $inspectionReceiver .= ' / '.$rowInspectionReceiver->employee_name;
                }

                if(!in_array($rowInspectionReceiver->employee_id_approval, $arrReceiver)) {
                    array_push($arrReceiver, $rowInspectionReceiver->employee_id_approval);
                }

                if(!in_array($rowInspectionReceiver->department_id, $arrDepartment)) {
                    array_push($arrDepartment, $rowInspectionReceiver->department_id);
                }
            }
        }

        if(!empty($arrReceiver) && !empty($arrDepartment)) {
            $getInspectionMatrix = $model->docApprovalOrderApplication()
                                        ->from('doc_approval_matrix as a')
                                        ->leftJoin('vw_master_employee_all as b', 'b.employee_id', 'a.employee_id_approval')
                                        ->select('b.employee_name', 'a.matrix_as')
                                        ->whereIn('a.employee_id', $arrReceiver)
                                        ->whereIn('a.department_id', $arrDepartment)
                                        ->where('a.matrix_as', '<>', 'INSPECTION_RECEIVER')
                                        ->where('a.doc_type_id', '4')
                                        ->oldest('a.matrix_id')
                                        ->get();
            foreach($getInspectionMatrix as $rowInspectionMatrix) {
                if($rowInspectionMatrix->matrix_as == 'INSPECTION_CHECKER') {
                    if($inspectionChecker == 'Not Available') {
                        $inspectionChecker = $rowInspectionMatrix->employee_name;
                    }
                    else {
                        $inspectionChecker .= ' / '.$rowInspectionMatrix->employee_name;
                    }
                }
                else if($rowInspectionMatrix->matrix_as == 'INSPECTION_CONFIRMER') {
                    if($inspectionConfirmer == 'Not Available') {
                        $inspectionConfirmer = $rowInspectionMatrix->employee_name;
                    }
                    else {
                        $inspectionConfirmer .= ' / '.$rowInspectionMatrix->employee_name;
                    }
                }
            }
        }

        $response['inspectionFlow'] = '<div class="mb-3" style="border: 1px solid #c4c4c4;">
                <div class="p-2" style="width: 100%; background-color: #c4c4c4;">
                    <span class="data-label">INSPECTION FORM FLOW</span>
                </div>
                <div class="p-2 data-details">
                    <div class="data-row">
                        <span class="data-label">Department</span>
                        <span class="data-separator">:</span>
                        <span class="data-value">'.$inspectionDepartment.'</span>
                    </div>
                    <div class="data-row">
                        <span class="data-label">Receiver</span>
                        <span class="data-separator">:</span>
                        <span class="data-value">'.$inspectionReceiver.'</span>
                    </div>
                    <div class="data-row">
                        <span class="data-label">Checker</span>
                        <span class="data-separator">:</span>
                        <span class="data-value">'.$inspectionChecker.'</span>
                    </div>
                    <div class="data-row">
                        <span class="data-label">Confirmer</span>
                        <span class="data-separator">:</span>
                        <span class="data-value">'.$inspectionConfirmer.'</span>
                    </div>
                </div>
            </div>';

        $getInspection = $model->docApprovalOrderInspection()
                                ->from('doc_approval_order_inspection as a')
                                // ->leftJoin('doc_approval_order_application as b', function($join) {
                                //     $join->on('b.application_id', '=', 'a.application_id')
                                //         ->where('b.is_active', '1');
                                // })
                                ->leftJoin('vw_master_employee_all as c', 'c.employee_id', 'a.created_by')
                                ->select('a.inspection_id', 'a.order_form_id', 'a.path_detail', 'a.filename', 'a.po_number', 'a.application_id', 'a.doc_approval_id', 'a.goods_received', 'c.avatar', 'c.employee_name', 'a.created_at', 'a.vendor_name', 'a.ship_date', 'a.incoming_date', 'a.inspection_form_status')
                                ->where('a.application_id', $referenceId)
                                ->where('a.is_active', '1')
                                ->orderBy('a.inspection_id', 'desc')
                                ->get();

        foreach($getInspection as $rowInspection) {
            $token = ['a' => $rowInspection->doc_approval_id, 'b' => $rowInspection->inspection_id, 'c' => null];
            $encodedToken = SafeToken::encode($token);

            $formStatus = '';
            if($rowInspection->inspection_form_status == '5') { // 5 = NEED REVISION
                $formStatus = '<span class="badge bg-warning fs-9 fw-semibold">SEND BACK TO REVISE</span>';
            }
            else if($rowInspection->inspection_form_status == '8') { // 8 = APPROVED
                $formStatus = '<span class="badge bg-success fs-9 fw-semibold">FULLY APPROVED</span>';
            }
            else if($rowInspection->inspection_form_status == '9') { // 9 = REJECTED
                $formStatus = '<span class="badge bg-danger fs-9 fw-semibold">FULLY REJECTED</span>';
            }
            else if($rowInspection->inspection_form_status == '2') { // 2 = SUBMITTED
                $formStatus = '<span class="badge bg-info fs-9 fw-semibold">ONGOING APPROVAL</span>';
            }
            $formStatus = $formStatus != '' ? '<div class="float-end badge-status">'.$formStatus.'</div>' : '';

            $getFormItem = $model->docApprovalOrderInspectionItem()
                                ->from('doc_approval_order_inspection_item')
                                ->select('appliance_item', 'quantity', 'incoming_qty', 'remaining_qty')
                                ->where('doc_approval_id', $rowInspection->doc_approval_id)
                                ->where('inspection_id', $rowInspection->inspection_id)
                                ->where('is_active', '1')
                                ->orderBy('inspection_item_id', 'asc')
                                ->get();

            $allItems = '';
            foreach ($getFormItem as $index => $rowItem) {
                if($index + 1 == 6) {
                    $allItems .= '<li>... and others</li>';
                    break;
                }
                else {
                    $item = count($getFormItem) > 1 ? ($index + 1).'. '.$rowItem->appliance_item : $rowItem->appliance_item;
                    $allItems .= '<li>'.$item.'</li>';
                }
            }

            $avatar = '<div class="d-flex align-items-center">
                            <div class="avatar avatar-xs d-flex align-items-center me-1">
                                <img class="avatar-img" src="'.asset('storage/avatars/'.$rowInspection->avatar).'" alt="">
                            </div>
                            <span class="avatar-name-card fs-8 fw-medium">'.Str::upper($rowInspection->employee_name).'</span>
                        </div>';
            $bottomCard = '<div class="d-flex justify-content-between align-items-center">
                                '.$avatar.'
                                <div class="text-end">
                                    <small class="text-muted text-nowrap">Submitted '.$this->timeAgo($rowInspection->created_at, false).'</small>
                                </div>
                            </div>';

            $uniqId = uniqid();
            $viewForm = true;
            $uniqIdView = $uniqId;

            $response['form'][] = '<div class="card card-content view-file-card mb-2-2" data-token="'.$encodedToken.'" data-filename="INSPECTION FORM">
                                <div class="card-header p-2-2 pb-0">
                                    <div class="card-title m-0 fs-7">INSPECTION FORM
                                        '.$formStatus.'
                                    </div>
                                </div>
                                <div class="card-body p-2-2 pt-0">
                                    <div class="mb-2 pt-1 data-details">
                                        <div class="data-row">
                                            <span class="data-label">PO No.</span>
                                            <span class="data-separator">:</span>
                                            <span class="data-value">'.$rowInspection->po_number.'</span>
                                        </div>
                                        <div class="data-row">
                                            <span class="data-label">Incoming Date</span>
                                            <span class="data-separator">:</span>
                                            <span class="data-value">'.Carbon::parse($rowInspection->incoming_date)->format('d-M-Y').'</span>
                                        </div>
                                        <div class="data-row">
                                            <span class="data-label">Goods Received</span>
                                            <span class="data-separator">:</span>
                                            <span class="data-value fw-bold">'.$rowInspection->goods_received.'</span>
                                        </div>
                                        <div class="data-row">
                                            <span class="data-label">Vendor</span>
                                            <span class="data-separator">:</span>
                                            <span class="data-value">'.$rowInspection->vendor_name.'</span>
                                        </div>
                                        <div class="data-row">
                                            <span class="data-label">Items</span>
                                            <span class="data-separator">:</span>
                                            <span class="data-value">
                                                <ul class="data-item-list">
                                                    '.$allItems.'
                                                </ul>
                                            </span>
                                        </div>
                                    </div>
                                    '.$bottomCard.'
                                </div>
                            </div>';
        }

        return response()->json([
                            'status' => 200,
                            'message' => 'Success',
                            'data' => $response,
                        ], 200);
    }

    public function getAttachment(Request $request) {
        $token = SafeToken::decode($request->token);
        $employeeId = $token['id'];
        $docApprovalId = $token['a'];
        $referenceId = $token['b'];
        $tokenType = isset($token['t']) ? $token['t'] : null;
        $flowType = $request->type;

        $response = collect();
        $response['form'] = '';
        $model = new DocumentApprovalModel();

        if($tokenType == 'PO_FORM_FILE') {
            $getApplicationForm = $model->docApprovalOrderApplication()
                                        ->from('doc_approval_order_application as a')
