    public function updateAction(Request $request) {
        $approvalFlow = 'SEQUENCE'; // SEQUENCE OR PARALEL
        $actionType = $request->actionType;
        $token = SafeToken::decode($request->tokenForm);
        $rowId = $request->rowId;

        $validator = Validator::make($token, [
            'id' => 'required',
            'a' => 'required',
            'b' => 'required',
        ]);

        if ($validator->fails()) {
            return response()->json(['message' => 'Invalid token form', 'errors' => $validator->errors()], 422)
                            ->setStatusCode(422, 'Invalid token form');
        }

        $companyId = (array_key_exists('cid', $token)) ? $token['cid'] : '1';
        $groupId = (array_key_exists('g', $token)) ? $token['g'] : null;
        $employeeId = $token['id'];
        $docApprovalId = $token['a'];
        $referenceId = $token['b'];
        // $approvalSignId = $token['c'];
        $source = $request->source;
        $response = collect();
        $signerStatus = '';

        try {
            if($actionType == 'REJECT' || $actionType == 'CANCEL'){
                $validatedData = $request->validate([
                    'commentAction' => 'required|string|max:255',
                ],[
                    'commentAction.required' => 'Reason is required',
                ]);
            }
            else if($actionType == 'SEND_BACK'){
                $validatedData = $request->validate([
                    'commentAction' => 'required|string|max:255',
                    'sendBackTo' => 'required|max:255',
                ],[
                    'commentAction.required' => 'Reason is required',
                    'sendBackTo.required' => 'Send back to is required',
                ]);
            }
            else if($actionType == 'SAVE_GOODS_RECEIVED'){
                $validatedData = $request->validate([
                    'receivedDateOrder' => 'required|date_format:d-m-Y',
                ],[
                    'receivedDateOrder.required' => 'Received date is required',
                ]);
            }
            else if($actionType == 'SAVE_INVOICED'){
                $validateRules = [
                    'invoicedDateOrder.*' => 'required|date_format:d-m-Y',
                    'invoiceDueDate.*' => 'required|date_format:d-m-Y',
                    'invoiceNo.*' => 'required|string|max:100',
                    'invoiceAmount.*' => 'required|string|max:100',
                ];
                $validateMessages = [
                    'invoicedDateOrder.*.required' => 'Invoice date is required',
                    'invoiceDueDate.*.required' => 'Due date is required',
                    'invoiceNo.*.required' => 'Invoice number is required',
                    'invoiceAmount.*.required' => 'Invoice amount is required',
                ];

                for($x = 0; $x < count($request->invoiceNo); $x++){
                    $validateRules["attachmentFile$x"] = 'required|file|max:5120|mimetypes:application/pdf,image/jpeg,image/png,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.ms-outlook,application/ms-tnef';

                    $validateMessages["attachmentFile$x.required"] = 'Attachment file is required';
                    $validateMessages["attachmentFile$x.mimetypes"] = 'Attachment must be a PDF, JPEG, PNG, Excel, Word or Outlook file.';
                    $validateMessages["attachmentFile$x.max"] = 'Attachment may not be greater than 5 MB.';
                }

                $validatedData = $request->validate($validateRules, $validateMessages);
            }

            $commentAction = Str::trim($request->input('commentAction', null));
            $sendBackTo = $request->input('sendBackTo', null);
            $decisionAt = Carbon::now()->format('Y-m-d H:i:s');
            $arrNotifications = array();
            $arrNotifications[$docApprovalId] = array();

            $model = new DocumentApprovalModel();
            if($request->type == 'PURCHASING') { // UPDATE AS PURCHASING
                $getHeader = $model->documentApprovalHeader()
                                ->from('doc_approval_header as a')
                                ->select('a.doc_approval_id', 'a.employee_id','a.doc_type_id', 'a.doc_number', 'a.doc_status_id', 'a.department_name', 'a.form_status_id', 'a.company_id')
                                // ->where('a.company_id', $companyId)
                                ->where('a.doc_approval_id', $docApprovalId)
                                ->where('a.is_active', '1')
                                ->orderBy('a.doc_approval_id', 'desc')
                                ->first();
                if($getHeader->doc_type_id == '1') { // 1 = ORDER FORM
                    $getForm = $model->documentApprovalDetailOrder()
                                    ->from('doc_approval_detail_order_form as a')
                                    ->leftJoin('master_transaction_status as c', 'c.transaction_status_id', 'a.order_form_status')
                                    ->select('a.order_form_id', 'a.order_form_status', 'a.path_detail', 'a.filename', 'c.transaction_status_name')
                                    // ->where('a.company_id', $companyId)
                                    ->where('a.doc_approval_id', $getHeader->doc_approval_id)
                                    ->where('a.is_active', '1')
                                    ->orderBy('a.order_form_id', 'desc')
                                    ->first();
                    if ($getForm) {
                        if($actionType == 'ARCHIVE') {

                        }
                        else {
                            $getFlowSign = $model->docApprovalFlowSign()
                                            ->from('doc_approval_flow_sign')
                                            ->select('sign_flow_id')
                                            // ->where('company_id', $companyId)
                                            ->where('doc_approval_id', $getHeader->doc_approval_id)
                                            ->where('reference_id', $getForm->order_form_id)
                                            ->where('employee_id', $employeeId)
                                            ->where('reference_group_id', $groupId)
                                            ->where('flow_as', 'RECEIVER')
                                            ->where('is_active', '1')
                                            ->orderBy('sign_flow_id', 'desc')
                                            ->first();
                            if($getFlowSign) {
                                $signFlowId = $getFlowSign->sign_flow_id;
                                // UPDATE CURRENT SIGNER
                                $dataUpdate = [
                                    'status' => '14', // 14 = SEND BACK
                                    'decision_at' => $decisionAt,
                                    'decision_source' => $source,
                                    'reference_group_id' => $groupId,
                                ];

                                $updateAction = $model->docApprovalFlowSign()
                                                        // ->where('company_id', $companyId)
                                                        ->where('doc_approval_id', $docApprovalId)
                                                        ->where('reference_id', $getForm->order_form_id)
                                                        ->where('employee_id', $employeeId)
                                                        ->where('status', '3') // 3 = RECEIVED
                                                        ->where('is_active', 1)
                                                        ->update($dataUpdate);
                                // END UPDATE CURRENT SIGNER
                            }
                            else {
                                $receiveAt = $decisionAt;
                                $getFlowSignSendBack = $model->docApprovalFlowSign()
                                                            ->from('doc_approval_flow_sign as a')
                                                            ->rightJoin('doc_approval_order_group as b', function($join) {
                                                                $join->on('b.order_group_id', 'a.reference_group_id')
                                                                    ->where('b.is_active', '1')
                                                                    ->orderBy('b.order_group_id', 'desc');
                                                            })
                                                            ->select('a.decision_at')
                                                            // ->where('a.company_id', $companyId)
                                                            ->where('b.order_form_id', $getForm->order_form_id)
                                                            ->where('a.status', '14') // 14 = SEND BACK
                                                            ->where('b.order_group_id', $groupId)
                                                            ->whereNotIn('a.flow_as', ['APPLICANT','CC','RECEIVER'])
                                                            ->where('a.is_active', '1')
                                                            ->orderBy('a.sign_flow_id', 'desc')
                                                            ->first();
                                if($getFlowSignSendBack) {
                                    $receiveAt = $getFlowSignSendBack->decision_at;
                                }

                                $dataInsert = [
                                    'employee_id' => $employeeId,
                                    'company_id' => $companyId,
                                    'flow_as' => 'RECEIVER',
                                    'doc_approval_id' => $getHeader->doc_approval_id,
                                    'doc_type_id' => $getHeader->doc_type_id,
                                    'reference_id' => $getForm->order_form_id,
                                    'reference_group_id' => $groupId,
                                    'status' => '14', // 14 = SEND BACK
                                    'received_at' => $receiveAt,
                                    'decision_at' => $decisionAt,
                                    'decision_source' => $source,
                                ];
                                $insertFlowSign = $model->docApprovalFlowSign()->create($dataInsert);
                                $signFlowId = $insertFlowSign->id;
                            }

                            $dataInsert = [
                                'sign_flow_id' => $signFlowId,
                                'company_id' => $companyId,
                                'reply_comment_id' => null,
                                'employee_id' => $employeeId,
                                'comment' => Str::trim($commentAction),
                                'comment_at' => $decisionAt,
                                'is_reply' => 0,
                                'is_main' => 1,
                                'is_active' => 1,
                            ];
                            $model->docApprovalFlowComment()->create($dataInsert);

                            // UPDATE OTHER RECEIVER
                            $dataUpdate = [
                                'status' => '16', // 16 = NOT SUBMITTED
                                'decision_at' => null,
                                'decision_source' => null,
                            ];

                            $updateAction = $model->docApprovalFlowSign()
                                                    // ->where('company_id', $companyId)
                                                    ->where('doc_approval_id', $docApprovalId)
                                                    ->where('reference_id', $getForm->order_form_id)
                                                    ->where('employee_id', '<>', $employeeId)
                                                    ->where('flow_as', 'RECEIVER')
                                                    ->where('status', '3') // 3 = RECEIVED
                                                    ->where('is_active', 1)
                                                    ->update($dataUpdate);
                            // UPDATE OTHER RECEIVER

                            if($actionType == 'SEND_BACK'){
                                if(array_key_exists('c', $token) && array_key_exists('d', $token)) {
                                    if($token['c'] != null && $token['d'] != null) {
                                        $dataUpdate = [
                                            'is_need_revision' => '1'
                                        ];

                                        $updateAction = $model->documentApprovalOrderGroup()
                                                            // ->where('company_id', $companyId)
                                                            ->where('order_form_id', $getForm->order_form_id)
                                                            ->where('application_id', $token['d'])
                                                            ->where('is_active', 1)
                                                            ->update($dataUpdate);
                                    }
                                }

                                $message = 'Successfully Send Back Form to User';
                                $dataUpdate = [
                                    'order_form_status' => '5', // 5 = NEEDS REVISION
                                    'final_decision_at' => $decisionAt,
                                ];

                                // UPDATE FORM
                                $updateAction = $model->documentApprovalDetailOrder()
                                                    // ->where('company_id', $companyId)
                                                    ->where('doc_approval_id', $docApprovalId)
                                                    ->where('order_form_id', $getForm->order_form_id)
                                                    ->where('is_active', 1)
                                                    ->update($dataUpdate);

                                // IF SEND BACK, NOTIFY TO APPLICANT
                                $getApplicant = $model->docApprovalFlowSign()
                                                    ->from('doc_approval_flow_sign as a')
                                                    ->select('a.sign_flow_id', 'a.employee_id', 'a.company_id')
                                                    // ->where('a.company_id', $companyId)
                                                    ->where('a.doc_approval_id', $getHeader->doc_approval_id)
                                                    ->where('a.reference_id', $getForm->order_form_id)
                                                    ->where('a.employee_id', $sendBackTo)
                                                    ->where('a.flow_as', '=', 'APPLICANT')
                                                    ->where('a.is_active', '1')
                                                    ->get();

                                foreach($getApplicant as $rowApplicant){
                                    $arrNotifications[$docApprovalId][] = [
                                                                            'docApprovalId' => $docApprovalId,
                                                                            'signFlowId' => $rowApplicant->sign_flow_id,
                                                                            'referenceId' => $getForm->order_form_id,
                                                                            'companyId' => $rowApplicant->company_id,
                                                                            'employeeId' => $rowApplicant->employee_id,
                                                                            'flowAs' => 'APPLICANT',
                                                                            'notification' => 'COMPLETED_REVISED',
                                                                        ];
                                }

                                if(Storage::exists('private/doc_approval'.$getForm->path_detail.$getForm->filename.'.xlsx')) {
                                    Storage::delete('private/doc_approval'.$getForm->path_detail.$getForm->filename.'.xlsx');
                                }
                            }

                            $updateStatus = true;
                            $token = ['cid' => $companyId, 'id' => $employeeId,'a' => $docApprovalId,'b' => $getForm->order_form_id,'c' =>null,'d'=>null,'g'=> $groupId];
                            $jsonToken = json_encode($token);
                            $encodedToken = SafeToken::encode($token);
                            $response['tokenForm'] = $encodedToken;

                            if($actionType == 'SEND_BACK') {
                                $signerStatus = 'SEND BACK TO REVISE';
                                $footerButton = '<div class="alert alert-warning m-0 w-100 p-2" role="alert">You have <span class="fw-semibold">SEND BACK TO REVISE</span> this form</div>';
                            }
                            else if($actionType == 'CANCEL') {
                                $signerStatus = 'CANCELED';
                                $footerButton = '<div class="alert alert-danger m-0 w-100 p-2" role="alert">You have <span class="fw-semibold">CANCELED</span> this form</div>';
                            }

                            // CHECK ARRAY NOTIFICATIONS
                            if (count($arrNotifications[$docApprovalId]) > 0) {
                                $requestData = new Request();
                                $requestData->merge(['notifications' => $arrNotifications]);
                                $this->sendEmail($requestData);
                            }

                            $arrSigner = [];
                            return response()->json(['signer' => $arrSigner, 'footerButton' => $footerButton, 'message' => $message, 'data' => $response, 'rowId' => $rowId], 200);
                        }
                    }
                    else {
                        return response()->json(['message' => 'Your approval is not available on this form'], 202)
                                        ->setStatusCode(202, 'Your approval is not available on this form');
                    }
                }
                else if($getHeader->doc_type_id == '2') { // 2 = APPLICATION & PO FORM
                    $getForm = $model->docApprovalOrderApplication()
                                    ->from('doc_approval_order_application as a')
                                    ->leftJoin('doc_approval_order_group as b', 'b.application_id', '=', 'a.application_id')
                                    ->select('a.application_id', 'a.order_form_id', 'a.application_form_status', 'a.application_number', 'b.order_group_id', 'a.path_detail', 'a.filename', 'a.company_id', 'a.goods_received')
                                    // ->where('a.company_id', $companyId)
                                    ->where('a.doc_approval_id', $docApprovalId)
                                    ->where('a.is_active', '1')
                                    ->orderBy('a.application_id', 'desc')
                                    ->first();

                    if ($getForm) {
                        $message = '';
                        if(($actionType == 'ARCHIVE' && ($getForm->application_form_status == '9' || $getForm->application_form_status == '12')) || ($actionType == 'CANCEL_TO_ARCHIVE' && $getForm->application_form_status == '5') || $actionType == 'CANCEL_APPLICATION_PO') { // 5 = NEED REVISE, 9 = REJECTED, 12 = CANCELED
                            if($actionType == 'CANCEL_TO_ARCHIVE' || $actionType == 'CANCEL_APPLICATION_PO'){
                                $validatedData = $request->validate([
                                    'commentAction' => 'required|string|max:255',
                                ],[
                                    'commentAction.required' => 'Reason is required',
                                ]);
                            }

                            $getOrderForm = $model->documentApprovalDetailOrder()
                                                ->from('doc_approval_detail_order_form as a')
                                                ->leftJoin('master_transaction_status as b', 'b.transaction_status_id', 'a.order_form_status')
                                                ->select('a.doc_approval_id', 'a.order_form_id', 'a.order_form_status', 'a.order_form_number', 'a.path_detail', 'a.filename', 'a.employee_id', 'b.transaction_status_name', 'a.company_id')
                                                ->where('a.company_id', $companyId)
                                                ->where('a.order_form_id', $getForm->order_form_id)
                                                ->where('a.is_active', '1')
                                                ->first();
                            if($getOrderForm) {
                                if($actionType == 'CANCEL_TO_ARCHIVE') {
                                    if($getOrderForm->order_form_status != '8') {
                                        return response()->json(['message' => 'Form has been '.$getOrderForm->transaction_status_name, 'errors' => 'Form has been '.$getOrderForm->transaction_status_name], 404)
                                        ->setStatusCode(404, 'Form has been '.$getOrderForm->transaction_status_name);
                                    }
                                }

                                // UPDATE ORDER GROUP
                                if($getForm->application_form_status == '9') {
                                    $dataUpdate = [
                                        'is_rejected' => '1',
                                    ];
                                }
                                else {
                                    $dataUpdate = [
                                        'is_canceled' => '1',
                                    ];
                                }

                                $updateAction = $model->documentApprovalOrderGroup()
                                                    ->where('order_form_id', $getForm->order_form_id)
                                                    ->where('application_id', $getForm->application_id)
                                                    ->update($dataUpdate);

                                if($actionType == 'CANCEL_TO_ARCHIVE' || $actionType == 'CANCEL_APPLICATION_PO') {
                                    $reason = Str::trim($request->commentAction);
                                }
                                else {
                                    $reason = '';
                                }
                                // CHECK MULTIPLE PO NOT CANCELED OR REJECTED
                                $getOrderGroup = $model->documentApprovalOrderGroup()
