    public function updateSigner(Request $request) {
        $employeeId = $this->employeeId;
        $companyId = $this->companyId;
        $actionType = $request->actionType;
        $token = SafeToken::decode($request->tokenForm);

        $validator = Validator::make($token, [
            'id' => 'required',
            'a' => 'required',
            'b' => 'required',
        ]);

        if ($validator->fails()) {
            return response()->json(['message' => 'Invalid token form', 'errors' => $validator->errors()], 422)
                            ->setStatusCode(422, 'Invalid token form');
        }

        $docApprovalId = $token['a'];
        $referenceId = $token['b'];
        $documentTypeId = $request->documentType;
        // $approvalSignId = $token['c'];
        $response = collect();

        try {
            $validatedData = $request->validate([
                'checker_1' => 'required|string|max:255',
                'checker_2' => Rule::when($request->locationOrder == '22', [
                                    'required',
                                    'string',
                                    'max:255',
                                ]),
                'approver' => 'required|string|max:255',
            ], [
                'checker_1.required' => 'First Checker is required',
                'checker_2.required' => 'Second Checker is required',
                'approver.required' => 'Approver is required',
            ]);

            $model = new DocumentApprovalModel();
            if($documentTypeId == '1') {
                $getForm = $model->documentApprovalDetailOrder()
                                ->from('doc_approval_detail_order_form')
                                ->select('order_form_id', 'order_form_status as form_status', 'employee_id', 'department_id', 'path_detail', 'filename')
                                ->where('doc_approval_id', $docApprovalId)
                                ->where('order_form_id', '=', $referenceId)
                                ->where('is_active', '1')
                                ->first();
            }

            if($getForm) {
                if($getForm->form_status == '2') { // 2 = SUBMITTED
                    $reviewerFlow = 'SEQUENCE'; // SEQUENCE OR PARALEL
                    $approverFlow = 'SEQUENCE'; // SEQUENCE OR PARALEL
                    $countChecker = count($request->reviewer);
                    $arrNotifications = array();
                    $arrNotifications[$docApprovalId] = array();

                    $dataUpdate = [
                        'is_active' => '0',
                    ];
                    $model->docApprovalFlowSign()
                            ->where('doc_approval_id', $docApprovalId)
                            ->where('reference_id', $getForm->order_form_id)
                            ->whereIn('flow_as', ['CHECKER_1','CHECKER_2','APPROVER'])
                            ->whereIn('status', ['3','13']) // 3 = RECEIVED, 13 = PENDING
