                    // $pdfWriter->setFont('arial');
                    // $pdfWriter->save($tempPdfFile);

                    $token = ['cid' => $companyId, 'id' => $employeeId,'a' => $docApprovalId,'b' => $getForm->order_form_id,'c' =>null,'d'=>null];
                    $encodedToken = SafeToken::encode($token);
                    $response['tokenForm'] = $encodedToken;

                    if (count($arrNotifications[$docApprovalId]) > 0) {
                        $requestData = new Request();
                        $requestData->merge(['notifications' => $arrNotifications]);
                        $this->sendEmail($requestData);
                    }

                    return response()->json(['status' => 200, 'message' => 'Successfully Update Data', 'data' => $response], 200);
                }
                else {
                    $formStatus = '';
                    if($getForm->form_status == '6') {
                        $formStatus = 'REVISED';
                    }
                    else if($getForm->form_status == '8') {
                        $formStatus = 'APPROVED';
                    }
                    else if($getForm->form_status == '9') {
                        $formStatus = 'REJECTED';
                    }
                    else if($getForm->form_status == '12') {
                        $formStatus = 'CANCELED';
                    }

                    $message = 'Form has been '.$formStatus.', please refresh this page.';
                    return response()->json([
                        'status' => 400,
                        'message' => $message,
                    ], 400);
                }
            }
            else {
                return response()->json([
                    'status' => 404,
                    'message' => 'Form not found, please refresh this page.',
                ]);
            }
        }
        catch (ValidationException $e) {
            return response()->json(['message' => 'Please fill the required form.', 'errors' => $e->errors()], 422)
                            ->setStatusCode(422, 'Please fill the required form.');
        }
    }

