                                    $bcc = null;
                                    dispatch(new SendEmailJob(
                                                $accountId, // ACCOUNT ID
                                                $getEmployee->employee_email, // TO
                                                $cc,
                                                $bcc,
                                                $mailSubject, // SUBJECT
                                                $mailBody, // BODY
                                                'normal', // PRIORITY = normal, low, high
                                                [], // ATTACHMENT ARRAY
                                            ));
                                }
                                else {
                                    return false;
                                }
                            }
                        }
                        else {
                            return false;
                        }
                    }
                }
                else {
                    return false;
                }
            }
        }

