                        $items = '';
                        $no = 1;
                        foreach ($getFormItem as $rowItem) {
                            $items .= $items != '' ? '<br>' : '';
                            $items .= count($getFormItem) > 1 ? $no.'. '.$rowItem->appliance_item : $rowItem->appliance_item;
