    public function getSendBackOptions(Request $request){
        $token = SafeToken::decode($request->tokenForm);
        $employeeId = $token['id'];
        $docApprovalId = $token['a'];
        $referenceId = $token['b'];
        // $approvalSignId = $token['c'];
        $type = $request->type;

        $model = new DocumentApprovalModel();
        if($type == 'PURCHASING') {
            $getData = $model->docApprovalFlowSign()->from('doc_approval_flow_sign as a')
                            ->leftJoin('vw_master_employee_all as b', 'b.employee_id', 'a.employee_id')
                            ->select('a.sign_flow_id', 'a.employee_id', 'a.flow_as', 'b.employee_name', 'b.avatar')
                            ->where('a.doc_approval_id', $docApprovalId)
                            ->where('reference_id', $referenceId)
                            ->where('status', '2') // 3 = RECEIVED
                            ->where('a.flow_as', 'APPLICANT')
                            ->where('a.is_active', '1')
                            ->orderBy('a.sign_flow_id', 'asc')
                            ->get();
            return $getData;
        }
        // else if($type == 'APPROVAL') {
        else {
            // CHECK THIS SIGNER
            $getFlow = $model->docApprovalFlowSign()->from('doc_approval_flow_sign')
                                                    ->select('doc_type_id', 'reference_id', 'flow_as', 'status')
                                                    ->where('doc_approval_id', $docApprovalId)
                                                    ->where('reference_id', $referenceId)
                                                    ->where('employee_id', $employeeId)
                                                    // ->where('sign_flow_id', $approvalSignId)
                                                    ->whereNotIn('flow_as', ['RECEIVER','CC'])
                                                    ->where('is_active', '1')

                                                    ->first();
            if($getFlow){
                // GET ALL SIGNER HAS SUBMITTED OR APPROVED
                $getData = $model->docApprovalFlowSign()->from('doc_approval_flow_sign as a')
                                                        ->leftJoin('vw_master_employee_all as b', 'b.employee_id', 'a.employee_id')
                                                        ->select('a.sign_flow_id', 'a.employee_id', 'a.flow_as', 'b.employee_name', 'b.avatar')
                                                        ->where('a.doc_approval_id', $docApprovalId)
                                                        ->where('reference_id', $referenceId)
                                                        ->where('status', '<>', '13') // 3 = RECEIVED
                                                        ->where('a.employee_id', '!=', $employeeId);

                if($getFlow->doc_type_id == '1') { // 1 = ORDER FORM
                    $getData = $getData->where('a.flow_as', 'APPLICANT');
                }
                else {
                    $getData = $getData->where('a.flow_as', 'APPLICANT');
                    // if($getFlow->flow_as == 'CHECKER' || $getFlow->flow_as == 'REVIEWER'){
                    //     $getData = $getData->where('a.flow_as', 'APPLICANT');
                    // }
                    // else if($getFlow->flow_as == 'APPROVER'){
                    //     $getData = $getData->whereIn('a.status', ['2', '8'])
                    //                         ->whereIn('a.flow_as', ['APPLICANT', 'CHECKER', 'REVIEWER']);
                    // }
                }

                $getData = $getData->where('a.is_active', '1')
                                    ->orderBy('a.sign_flow_id', 'asc')
                                    ->get();
                return $getData;
            }
            else{
                return null;
            }
        }
    }

    public function romanNumber($number){
        $arrRomanNumber = [
            1 => 'I',
            2 => 'II',
            3 => 'III',
            4 => 'IV',
            5 => 'V',
            6 => 'VI',
            7 => 'VII',
            8 => 'VIII',
            9 => 'IX',
            10 => 'X',
            11 => 'XI',
            12 => 'XII'
        ];

        if (!is_numeric((int)$number) || (int)$number < 1 || (int)$number > 12) {
            return null;
        }

        return $arrRomanNumber[(int)$number];
    }

    public function timeAgo($dateTime, $full = false) {
        try {
            if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateTime)) {
                // ONLY DATE
                $now = new DateTime();
                $today = new DateTime($now->format('Y-m-d'));
                $ago = new DateTime($dateTime);
                $diff = $today->diff($ago);

                if ($diff->days === 0 && $diff->y === 0 && $diff->m === 0) {
                    return 'Today';
                }
            }
            elseif (preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/', $dateTime)) {
                // DATE AND TIME
                $now = new DateTime();
                $ago = new DateTime($dateTime);
                $diff = $now->diff($ago);

                if ($diff->y === 0 && $diff->m === 0 && $diff->d === 0 &&
                    $diff->h === 0 && $diff->i === 0 && $diff->s === 0) {
                    return 'just now';
                }
            }
            else {
                return "Invalid date format";
            }

            $days = $diff->days;
            $weeks = floor($days / 7);
            $remainingDays = $days % 7;

            $string = [
                'y' => 'year',
                'm' => 'month',
                'w' => 'week',
                'd' => 'day',
                'h' => 'hour',
                'i' => 'minute',
                's' => 'second',
            ];

            $diffArray = [
                'y' => $diff->y,
                'm' => $diff->m,
                'w' => $weeks,
                'd' => $remainingDays,
                'h' => $diff->h,
                'i' => $diff->i,
                's' => $diff->s,
            ];

            foreach ($string as $k => &$v) {
                if ($diffArray[$k] > 0) {
                    $v = $diffArray[$k] . ' ' . $v . ($diffArray[$k] > 1 ? 's' : '');
                } else {
                    unset($string[$k]);
                }
            }

            if (!$full) {
                $string = array_slice($string, 0, 1);
            }

            return $string ? implode(', ', $string) . ' ago' : 'just now';

        }
        catch (Exception $e) {
            return "Error: " . $e->getMessage();
        }
    }

    public function getFileIcon($mimeType, $fileName = null){
        $iconClass = '';
        $checkExtension = function (array $extensions) use ($fileName) {
            return collect($extensions)->contains(function ($ext) use ($fileName) {
                return str_ends_with(strtolower($fileName), $ext);
            });
        };

        if (str_contains($mimeType, 'pdf')) {
            $iconClass = 'far fa-file-pdf';
        } elseif (str_contains($mimeType, 'image')) {
            $iconClass = 'far fa-file-image';
        } elseif (str_contains($mimeType, 'excel') || str_contains($mimeType, 'spreadsheetml')) {
            $iconClass = 'far fa-file-excel';
        } elseif (str_contains($mimeType, 'wordprocessingml')) {
            $iconClass = 'far fa-file-word';
        } elseif (
            str_contains($mimeType, 'ms-outlook') ||
            str_contains($mimeType, 'ms-tnef') ||
            $mimeType === 'message/rfc822' ||
            str_contains($mimeType, 'vnd.ms-outlook') ||
            $checkExtension(['.msg', '.eml'])
        ) {
            $iconClass = 'far fa-envelope';
        } else {
            $iconClass = 'far fa-file';
        }

        return $iconClass;
    }

    private function formatNumber($number) {
        $absoluteNumber = abs($number);
        $formattedNumber = ($absoluteNumber == round($absoluteNumber))
            ? number_format($absoluteNumber, 0, '.', ',')
            : number_format($absoluteNumber, 2, '.', ',');

        return $number < 0 ? '-' . $formattedNumber : $formattedNumber;
    }

    private function getMimeTypeByExtension(string $filename) {
        $mimeTypes = [
            'txt' => 'text/plain',
            'html' => 'text/html',
            'htm' => 'text/html',
            'css' => 'text/css',
            'js' => 'application/javascript',
            'csv' => 'text/csv',
            'ics' => 'text/calendar',
            'md' => 'text/markdown',
            'markdown' => 'text/markdown',
            'xml' => 'application/xml',
            'jpg' => 'image/jpeg',
            'jpeg' => 'image/jpeg',
            'png' => 'image/png',
            'gif' => 'image/gif',
            'bmp' => 'image/bmp',
            'svg' => 'image/svg+xml',
            'tif' => 'image/tiff',
            'tiff' => 'image/tiff',
            'webp' => 'image/webp',
            'ico' => 'image/x-icon',
            'mp3' => 'audio/mpeg',
            'aac' => 'audio/aac',
            'wav' => 'audio/wav',
            'oga' => 'audio/ogg',
            'mid' => 'audio/midi',
            'midi' => 'audio/midi',
            'weba' => 'audio/webm',
            'opus' => 'audio/opus',
            'mpeg' => 'video/mpeg',
            'mpg' => 'video/mpeg',
            'mp4' => 'video/mp4',
            'avi' => 'video/x-msvideo',
            'ogv' => 'video/ogg',
            'webm' => 'video/webm',
            '3gp' => 'video/3gpp',
            '3g2' => 'video/3gpp2',
            'pdf' => 'application/pdf',
            'zip' => 'application/zip',
            'json' => 'application/json',
            'doc' => 'application/msword',
            'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'xls' => 'application/vnd.ms-excel',
            'xlsx' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'ppt' => 'application/vnd.ms-powerpoint',
            'pptx' => 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
            'epub' => 'application/epub+zip',
            'jar' => 'application/java-archive',
            'swf' => 'application/x-shockwave-flash',
            'rar' => 'application/x-rar-compressed',
            '7z' => 'application/x-7z-compressed',
            'apk' => 'application/vnd.android.package-archive',
            'mpkg' => 'application/vnd.apple.installer+xml',
            'bin' => 'application/octet-stream',
        ];

        $expFilename = Str::of($filename)->explode('.');
        $extension = Str::lower($expFilename->last());
        return $mimeTypes[$extension] ?? 'application/octet-stream';
    }
}

class Mpdf2 extends Mpdf {
    protected $spreadsheet;
    protected $companyId;
    protected $showHeader;
    protected $showFooter;

    public function __construct(\PhpOffice\PhpSpreadsheet\Spreadsheet $spreadsheet) {
        parent::__construct($spreadsheet);
    }

    public function setParameters($companyId, $showHeader = false, $showFooter = false) {
        $this->companyId = $companyId;
        $this->showHeader = $showHeader;
        $this->showFooter = $showFooter;
        return $this;
    }

    protected function createExternalWriterInstance($config) {
        $mpdf = new \Mpdf\Mpdf([
            'mode' => 'utf-8',
            'exposeVersion' => false,
            'tempDir' => storage_path('app/temp'),
            'fontDir' => [storage_path('fonts')],
            'fontdata' => [
                'arial' => [
                    'R' => 'arial.ttf',
                    'B' => 'arial_Bold.ttf',
                    'I' => 'arial_Italic.ttf',
                    'BI' => 'arial_Bold_Italic.ttf',
                ],
            ],
            'default_font' => 'arial',
            'margin_header' => 6,
            'margin_footer' => 6,
            'setAutoTopMargin' => 'stretch',
            'setAutoBottomMargin' => 'stretch',
        ]);

        // if ($this->showFooter) {
        //     $footerHtml = '<div style="text-align: center; font-size: 9px; font-weight: bold; font-family: arial">
        //                         Page {PAGENO} of {nbpg}
        //                     </div>';
        //     $mpdf->SetHTMLFooter($footerHtml);
        // }

        if ($this->showHeader) {
            switch ($this->companyId) {
                case '316':
                    $letterHeadPath = storage_path('app/private/template/Leterhead_LID_Pakuwon.png');
                    break;
                case '317':
                    $letterHeadPath = storage_path('app/private/template/Leterhead_BML_Pakuwon.png');
                    break;
                case '322':
                    $letterHeadPath = storage_path('app/private/template/Leterhead_VID.jpg');
                    break;
            }

            $headerHtml = '<div style="text-align: center;">
                            <img src="'.$letterHeadPath.'" style="width: 2480px; height: 150px; margin-top: 0px; margin-left: 4px; margin-right: 4px; margin-bottom: 3px" />
                        </div>';
            $mpdf->SetHTMLHeader($headerHtml);
        }

        return $mpdf;
    }
}
